// Задания «Решу ЕГЭ» (hist-ege.sdamgia.ru), разложены по темам tools/build_ege.py
const EGE = [{"id":334,"tp":2,"kind":"choice","type":"Тип Д1","body":"<p>Кого из названных лиц русские князья считали родоначальником своей династии?<p><p>&nbsp;</p><p>1)&#8239;&#8239;Аскольда<p>2)&#8239;&#8239;Дира<p>3)&#8239;&#8239;Рюрика<p>4)&#8239;&#8239;Олега","sol":"<b>Пояснение. </b><p>Начало русской государственности связывают с событиями 862&#8239;г.&#8239;&#8239;— призванием варягов во главе с князем Рюриком. Аскольд и Дир были дружинниками Рюрика. Олег стал княжить позднее, после смерти Рюрика.<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3ПояснениеСпрятать пояснение &middot; \n                    1 комментарий\n                     &middot; Помощь","ans":"3"},{"id":412,"tp":1,"kind":"choice","type":"Тип Д1","body":"<p>Волхвами в Древней Руси называли<p><p>&nbsp;</p><p>1)&#8239;&#8239;обедневших крестьян-общинников<p>2)&#8239;&#8239;глав крупных зажиточных семей<p>3)&#8239;&#8239;первых священнослужителей в христианских храмах<p>4)&#8239;&#8239;жрецов языческих культов, знахарей","sol":"<b>Пояснение. </b><p>Волхвы в Древней Руси&#8239;&#8239;— это служители, жрецы языческих культов. <p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4ПояснениеСпрятать пояснение &middot; Помощь","ans":"4"},{"id":529,"tp":3,"kind":"choice","type":"Тип Д1","body":"<p>Какое литературное произведение из названных принадлежит Владимиру Мономаху?<p><p>&nbsp;</p><p>1)&#8239;&#8239;«Апостол»<p>2)&#8239;&#8239;«Поучение детям»<p>3)&#8239;&#8239;«Задонщина»<p>4)&#8239;&#8239;«Русская Правда»","sol":"<b>Пояснение. </b><p>В XII в. киевский князь Владимир Мономах написал «Поучение детям»&#8239;&#8239;— свод нравственных правил и наставлений. «Апостол»&#8239;&#8239;— это первая печатная книга, которая была выпущена в 1564 году. «Задонщина»&#8239;&#8239;— это произведение XIV века, рассказывающее о событиях Куликовской битвы. «Русская правда»&#8239;&#8239;— это свод законов Древней Руси.  <p>&nbsp;</p><p>Правильный ответ указан под номером: 2.Ответ: 2ПояснениеСпрятать пояснение &middot; Помощь","ans":"2"},{"id":568,"tp":3,"kind":"choice","type":"Тип Д1","body":"<p>С каким из названных событий связано имя князя Владимира Мономаха?<p><p>&nbsp;</p><p>1.&#8239;&#8239;С Любечским съездом князей<p>2.&#8239;&#8239;С дунайскими походами<p>3.&#8239;&#8239;С разгромом хазар<p>4.&#8239;&#8239;С разгромом печенегов","sol":"<b>Пояснение. </b><p>В 1097&#8239;г. состоялся съезд князей в Любече, инициатором которого был князь Владимир Мономах. Дунайские походы и разгром хазар связаны с именем князя Святослава. Разгром печенегов произошел в 1036&#8239;г. в правление князя Ярослава Мудрого.<p>&nbsp;</p><p>Правильный ответ указан под номером: 1.Ответ: 1ПояснениеСпрятать пояснение &middot; \n                    1 комментарий\n                     &middot; Помощь","ans":"1"},{"id":685,"tp":2,"kind":"choice","type":"Тип Д1","body":"<p>С каким событием в истории Руси связано начало династии Рюриковичей?<p><p>&nbsp;</p><p>1.&#8239;&#8239;Походом князя Олега на Киев<p>2.&#8239;&#8239;Призванием варягов<p>3.&#8239;&#8239;Крещением Руси<p>4.&#8239;&#8239;Изданием Русской Правды","sol":"<b>Пояснение. </b><p>Начало династии Рюриковичей связано с призванием варягов на Русь в 862&#8239;г. Рюрик считался родоначальником первой правящей династии на Руси. Олег княжил после смерти Рюрика и совершил поход на Киев в 882&#8239;г. Крещение Руси произошло в 988&#8239;г., свод законов «Русская правда» создавался в XI—XII вв., то есть в период существования государства Древняя Русь.<p>&nbsp;</p><p>Правильный ответ указан под номером: 2.Ответ: 2ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"2"},{"id":841,"tp":2,"kind":"choice","type":"Тип Д1","body":"<p>Согласно летописным свидетельствам Рюрик правил во второй половине IX в. в (во)<p><p>&nbsp;</p><p>1)&#8239;&#8239;Киеве<p>2)&#8239;&#8239;Новгороде<p>3)&#8239;&#8239;Владимире<p>4)&#8239;&#8239;Чернигове","sol":"<b>Пояснение. </b><p>В 862&#8239;г. произошло легендарное призвание варягов во главе с князем Рюриком в Новгород. Киев, Владимир, Чернигов стали центрами княжеской власти позднее.<p>&nbsp;</p><p>Правильный ответ указан под номером: 2.Ответ: 2ПояснениеСпрятать пояснение &middot; Помощь","ans":"2"},{"id":880,"tp":2,"kind":"choice","type":"Тип Д1","body":"<p>«Иду на вы»&#8239;&#8239;— с этими словами обращался к своим врагам перед походом князь<p><p>&nbsp;</p><p>1)&#8239;&#8239;Олег<p>2)&#8239;&#8239;Святослав<p>3)&#8239;&#8239;Владимир Мономах<p>4)&#8239;&#8239;Ярослав Мудрый","sol":"<b>Пояснение. </b><p>Согласно летописи, князь Святослав предупреждал своих врагов боевым кличем «Иду на вы». Святослав был типичный князь-воин, который проводил активную внешнюю политику, например&#8239;&#8239;— разгромил хазар, воевал с Дунайской Болгарией и Византией.<p>&nbsp;</p><p>Правильный ответ указан под номером: 2.Ответ: 2ПояснениеСпрятать пояснение &middot; Помощь","ans":"2"},{"id":997,"tp":2,"kind":"choice","type":"Тип Д1","body":"<p>Кто из князей осуществил поход на Царьград в 907&#8239;г.?<p><p>&nbsp;</p><p>1.&#8239;&#8239;Князь Олег<p>2.&#8239;&#8239;Князь Игорь<p>3.&#8239;&#8239;Князь Владимир<p>4.&#8239;&#8239;Князь Святослав","sol":"<b>Пояснение. </b><p>Киевский князь Олег (879−912&#8239;гг.) совершил успешный поход на Царьград 907&#8239;г., а затем в&#8239;911&#8239;г.<p>&nbsp;</p><p>Правильный ответ указан под номером: 1.Ответ: 1ПояснениеСпрятать пояснение &middot; Помощь","ans":"1"},{"id":1036,"tp":4,"kind":"choice","type":"Тип Д1","body":"<p>Последним князем единой Руси в XII в. был<p><p>&nbsp;</p><p>1)&#8239;&#8239;Юрий Долгорукий<p>2)&#8239;&#8239;Владимир Мономах<p>3)&#8239;&#8239;Мстислав Великий<p>4)&#8239;&#8239;Ярослав Мудрый","sol":"<b>Пояснение. </b><p>Старший сын Владимира Мономаха Мстислав Великий 1125—1132&#8239;гг. был последним князем, при котором сохранялось единство русских земель вокруг Киева. Юрий Долгорукий был ростово-суздальским князем. При Ярославе Мудром Русь достигла расцвета.<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3ПояснениеСпрятать пояснение &middot; Помощь","ans":"3"},{"id":1076,"tp":2,"kind":"choice","type":"Тип Д1","body":"<p>С кем воевал князь Святослав Игоревич (962–972)?<p><p>&nbsp;</p><p>1.&#8239;&#8239;С татаро-монголами<p>2.&#8239;&#8239;С хазарами<p>3.&#8239;&#8239;С крестоносцами<p>4.&#8239;&#8239;С варягами","sol":"<b>Пояснение. </b><p>Князь Святослав Игоревич разгромил Хазарский каганат в 966 году.<p>&nbsp;</p><p>Правильный ответ указан под номером: 2.Ответ: 2ПояснениеСпрятать пояснение &middot; \n                    1 комментарий\n                     &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"2"},{"id":1155,"tp":2,"kind":"choice","type":"Тип Д1","body":"<p>«Иду на вы»&#8239;&#8239;— с этими словами обращался к своим врагам перед походом князь<p><p>&nbsp;</p><p>1)&#8239;&#8239;Олег<p>2)&#8239;&#8239;Святослав<p>3)&#8239;&#8239;Владимир Мономах<p>4)&#8239;&#8239;Игорь","sol":"<b>Пояснение. </b><p>##«Иду на вы»&#8239;&#8239;— это был боевой клич князя Святослава, который согласно летописи большую часть жизни провел в походах и таким образом предупреждал своих врагов о наступлении. <p>&nbsp;</p><p>Правильный ответ указан под номером: 2.Ответ: 2ПояснениеСпрятать пояснение &middot; Помощь","ans":"2"},{"id":2380,"tp":2,"kind":"choice","type":"Тип Д1","body":"<p>С каким событием в истории Руси связано начало династии Рюриковичей?<p>&nbsp;</p><p>1.&#8239;&#8239;Борьбой с Хазарским каганатом<p>2.&#8239;&#8239;Призванием варягов<p>3.&#8239;&#8239;Походом князя Олега на Византию<p>4.&#8239;&#8239;Изданием Русской Правды","sol":"<b>Пояснение. </b><p>Начало династии Рюриковичей связано с призванием варягов в 862 году. На Русь пришли Рюрик, Синеус и Трувор.<p>&nbsp;</p><p>Правильный ответ указан под номером: 2.Ответ: 2ПояснениеСпрятать пояснение &middot; Помощь","ans":"2"},{"id":3345,"tp":3,"kind":"choice","type":"Тип Д1","body":"<p>Как назывался сборник законов Древнерусского государства?<p><p>&nbsp;</p><p>1)&#8239;&#8239;«Повесть временных лет»<p>2)&#8239;&#8239;Русская Правда<p>3)&#8239;&#8239;Соборное уложение<p>4)&#8239;&#8239;Судебник","sol":"<b>Пояснение. </b><p>Сборник законов Древнерусского государства составленный в XI в. назывался «Русская Правда».<p>Соборное уложение и Судебник были составлены уже в  XV−XVII вв;<p>«Повесть временных лет»&#8239;&#8239;— это летопись о истории Древнерусского государства.<p>&nbsp;</p><p>Правильный ответ указан под номером: 2.Ответ: 2Источник: ЕГЭ по истории 30.05.2013. Основная волна. Центр. Вариант 1ПояснениеСпрятать пояснение &middot; Помощь","ans":"2"},{"id":3825,"tp":1,"kind":"choice","type":"Тип Д1","body":"<p>В Древней Руси словом «вервь» называли<p><p>&nbsp;</p><p>1)&#8239;&#8239;время ухода крестьян от владельца<p>2)&#8239;&#8239;форму сбора дани<p>3)&#8239;&#8239;общину<p>4)&#8239;&#8239;совет бояр при князе","sol":"<b>Пояснение. </b><p>Вервь (от «вервь»&#8239;&#8239;— верёвка, участок земли, отмеренный верёвкой), древняя общинная организация на Руси и у хорватов. Упоминается в Русской правде (законодательном памятнике Киевской Руси) и в Полицком статуте.<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3Источник: ЕГЭ по истории 30.05.2013. Основная волна. Сибирь. Вариант 1ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"3"},{"id":3945,"tp":1,"kind":"choice","type":"Тип Д1","body":"<p>В Древней Руси словом «вервь» называли<p><p>&nbsp;</p><p>1)&#8239;&#8239;форму сбора дани<p>2)&#8239;&#8239;время ухода крестьян от владельца<p>3)&#8239;&#8239;совет бояр при князе<p>4)&#8239;&#8239;общину","sol":"<b>Пояснение. </b><p>Вервь (от «вервь»&#8239;&#8239;— верёвка, участок земли, отмеренный верёвкой), древняя общинная организация на Руси и у хорватов. Упоминается в Русской правде (законодательном памятнике Киевской Руси) и в Полицком статуте.<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4Источник: ЕГЭ по истории 30.05.2013. Основная волна. Сибирь. Вариант 4ПояснениеСпрятать пояснение &middot; Помощь","ans":"4"},{"id":4454,"tp":2,"kind":"choice","type":"Тип Д1","body":"<p>Какое событие произошло раньше остальных?<p>&nbsp;</p><p>1)&#8239;&#8239;Любеческий съезд князей<p>2)&#8239;&#8239;походы князя Святослава в Дунайскую Болгарию<p>3)&#8239;&#8239;принятие «Русской правды»<p>4)&#8239;&#8239;восстание древлян и гибель князя Игоря","sol":"<b>Пояснение. </b><p>Любеческий съезд князей 1097&#8239;г;<p>походы князя Святослава в Дунайскую Болгарию&#8239;&#8239;— 967-72&#8239;гг;<p>принятие «Русской правды»&#8239;&#8239;— 1038&#8239;г;<p>восстание древлян и гибель князя Игоря&#8239;&#8239;— 945&#8239;г.<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4ПояснениеСпрятать пояснение &middot; Помощь","ans":"4"},{"id":4584,"tp":2,"kind":"choice","type":"Тип Д1","body":"<p>Одним из центров восточнославянских союзов племён, возникших ещё до X в., был город<p>&nbsp;</p><p>1)&#8239;&#8239;Владимир<p>2)&#8239;&#8239;Тверь<p>3)&#8239;&#8239;Полоцк<p>4)&#8239;&#8239;Ярославль","sol":"<b>Пояснение. </b><p>Первое известное упоминание о Полоцке 862 год в «Повести временных лет».<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3ПояснениеСпрятать пояснение &middot; Помощь","ans":"3"},{"id":4624,"tp":2,"kind":"choice","type":"Тип Д1","body":"<p>Укажите годы правления князя Владимира Святого.<p>&nbsp;</p><p>1)&#8239;&#8239;862—879&#8239;гг.<p>2)&#8239;&#8239;912—945&#8239;гг.<p>3)&#8239;&#8239;980—1015&#8239;гг.<p>4)&#8239;&#8239;1113—1125&#8239;гг.","sol":"<b>Пояснение. </b><p>Княжение Владимира Святого 980—1015&#8239;гг.<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3ПояснениеСпрятать пояснение &middot; \n                    1 комментарий\n                     &middot; Помощь","ans":"3"},{"id":4670,"tp":2,"kind":"choice","type":"Тип Д1","body":"<p>Какое государство на юго-востоке соседствовало с Древнерусским<p>государством на раннем периоде его истории (IX–X вв.)?<p>&nbsp;</p><p>1)&#8239;&#8239;Дунайская Болгария<p>2)&#8239;&#8239;Венгрия<p>3)&#8239;&#8239;Хазарский каганат<p>4)&#8239;&#8239;Золотая Орда","sol":"<b>Пояснение. </b><p>Золотой Орды еще не существовало. Венгрия&#8239;&#8239;— сосед на Западе, Дунайская Болгария&#8239;&#8239;— на юго-западе. На юго-востоке&#8239;&#8239;— Хазарский каганат.<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"3"},{"id":4710,"tp":3,"kind":"choice","type":"Тип Д1","body":"<p>Правление Ярослава Мудрого относится к<p>&nbsp;</p><p>1)&#8239;&#8239;X в.<p>2)&#8239;&#8239;XI в.<p>3)&#8239;&#8239;XII в.<p>4)&#8239;&#8239;XIII в.","sol":"<b>Пояснение. </b><p>Годы правления Ярослава Мудрого в Киеве 1019—1054&#8239;гг. <p>&nbsp;</p><p>Правильный ответ указан под номером: 2.Ответ: 2ПояснениеСпрятать пояснение &middot; Помощь","ans":"2"},{"id":4790,"tp":4,"kind":"choice","type":"Тип Д1","body":"<p>Какое из перечисленных событий произошло раньше других?<p>&nbsp;</p><p>1.&#8239;&#8239;Поход хана Тохтамыша на Москву<p>2.&#8239;&#8239;Гибель князя Андрея Боголюбского<p>3.&#8239;&#8239;Битва на реке Сити<p>4.&#8239;&#8239;Ледовое побоище","sol":"<b>Пояснение. </b><p>Поход хана Тохтамыша на Москву 1382&#8239;г., гибель князя Андрея Боголюбского 1174&#8239;г., битва на реке Сити 1238&#8239;г., Ледовое побоище 1242&#8239;г.<p>&nbsp;</p><p>Правильный ответ указан под номером: 2.Ответ: 2ПояснениеСпрятать пояснение &middot; Помощь","ans":"2"},{"id":4870,"tp":4,"kind":"choice","type":"Тип Д1","body":"<p>В какой из перечисленных городов была перенесена столица Северо-Восточной Руси князем Андреем Боголюбским?<p>&nbsp;</p><p>1)&#8239;&#8239;Москва<p>2)&#8239;&#8239;Тверь<p>3)&#8239;&#8239;Владимир<p>4)&#8239;&#8239;Переяславль","sol":"<b>Пояснение. </b><p>Андрей Боголюбский перенес столицу Северо-Восточной Руси из Суздаля во Владимир.<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"3"},{"id":4910,"tp":5,"kind":"choice","type":"Тип Д1","body":"<p>Какое из перечисленных событий произошло позже других?<p>&nbsp;</p><p>1.&#8239;&#8239;Битва на р. Калке<p>2.&#8239;&#8239;Объединение Киева и Новгорода под единой княжеской властью<p>3.&#8239;&#8239;Первое упоминание Москвы в летописи<p>4.&#8239;&#8239;Съезд князей в Любече","sol":"<b>Пояснение. </b><p>Битва на р. Калке&#8239;&#8239;— 1223&#8239;г., объединение Киева и Новгорода под единой княжеской властью&#8239;&#8239;— 882&#8239;г., первое упоминание Москвы в летописи&#8239;&#8239;— 1147&#8239;г., съезд князей в Любече&#8239;&#8239;— 1097&#8239;г.<p>&nbsp;</p><p>Правильный ответ указан под номером: 1.Ответ: 1ПояснениеСпрятать пояснение &middot; \n                    2 комментария\n                     &middot; Помощь","ans":"1"},{"id":4993,"tp":5,"kind":"choice","type":"Тип Д1","body":"<p>Какое из перечисленных событий относится к XIII в.?<p>&nbsp;</p><p>1.&#8239;&#8239;Битва на р. Воже<p>2.&#8239;&#8239;Поход новгород-северского князя Игоря против половцев<p>3.&#8239;&#8239;Битва на р. Калке<p>4.&#8239;&#8239;Разгром печенегов Ярославом Мудрым у Киева","sol":"<b>Пояснение. </b><p>Битва на р. Воже 1378&#8239;г; поход новгород-северского князя Игоря против половцев 1185&#8239;г; битва на р. Калке 1223&#8239;г; разгром печенегов Ярославом Мудрым у Киева 1036&#8239;г.<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3ПояснениеСпрятать пояснение &middot; Помощь","ans":"3"},{"id":5033,"tp":2,"kind":"choice","type":"Тип Д1","body":"<p>Какое из перечисленных событий относится к X в.?<p>&nbsp;</p><p>1.&#8239;&#8239;Объединение Киева и Новгорода под властью князя Олега<p>2.&#8239;&#8239;Подписание первого письменного договора Руси с Византией<p>3.&#8239;&#8239;Начало составления Русской Правды<p>4.&#8239;&#8239;Крестовый поход Руси против половцев","sol":"<b>Пояснение. </b><p>Объединение Киева и Новгорода под властью князя Олега&#8239;&#8239;— 882&#8239;г; подписание первого письменного договора Руси с Византией&#8239;&#8239;— 911&#8239;г; начало составления Русской Правды&#8239;&#8239;— XI в; крестовый поход Руси против половцев&#8239;&#8239;— XII&#8239;в.<p>&nbsp;</p><p>Правильный ответ указан под номером: 2.Ответ: 2ПояснениеСпрятать пояснение &middot; Помощь","ans":"2"},{"id":5135,"tp":6,"kind":"choice","type":"Тип Д1","body":"<p>Какое из перечисленных событий произошло в XIII в.?<p>&nbsp;</p><p>1.&#8239;&#8239;Разгром Хазарского каганата<p>2.&#8239;&#8239;Крещение Руси<p>3.&#8239;&#8239;Невская битва<p>4.&#8239;&#8239;Разгром печенегов под Киевом","sol":"<b>Пояснение. </b><p>Разгром Хазарского каганата&#8239;&#8239;— 964−968&#8239;гг;<p>Крещение Руси&#8239;&#8239;— 988&#8239;г;<p>Невская битва&#8239;&#8239;— 1240&#8239;г;<p>Разгром печенегов под Киевом&#8239;&#8239;— 1036&#8239;г.<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"3"},{"id":5374,"tp":3,"kind":"choice","type":"Тип Д1","body":"<p>Какое событие относится ко времени правления Ярослава Мудрого?<p>&nbsp;</p><p>1.&#8239;&#8239;Установление уроков и погостов<p>2.&#8239;&#8239;Подчинение Киеву племён северян<p>3.&#8239;&#8239;Крещение князя и его дружины в Корсуни (Херсонесе)<p>4.&#8239;&#8239;Создание первого на Руси письменного свода законов","sol":"<b>Пояснение. </b><p>1)&#8239;&#8239;установление уроков и погостов - Ольга Святая<p>&nbsp;</p><p>2)&#8239;&#8239;подчинение Киеву племён северян - Олег Вещий<p>&nbsp;</p><p>3)&#8239;&#8239;крещение князя и его дружины в Корсуни (Херсонесе) - Владимир Красное Солнышко<p>&nbsp;</p><p>4)&#8239;&#8239;создание первого на Руси письменного свода законов - Ярослав Мудрый<p>Правильный ответ: 4Ответ: 4ПояснениеСпрятать пояснение &middot; Помощь","ans":"4"},{"id":5416,"tp":5,"kind":"choice","type":"Тип Д1","body":"<p>Первое сражение русских дружин с монголо-татарами произошло на реке<p>&nbsp;</p><p>1)&#8239;&#8239;Калка <p>2)&#8239;&#8239;Вожа <p>3)&#8239;&#8239;Угра <p>4)&#8239;&#8239;Нева","sol":"<b>Пояснение. </b><p>1)&#8239;&#8239;Калка 1223г<p>&nbsp;</p><p>2)&#8239;&#8239;Вожа 1378г<p>&nbsp;</p><p>3)&#8239;&#8239;Угра 1480г<p>&nbsp;</p><p>4)&#8239;&#8239;Нева 1240, против шведов, а не татар.<p>Правильный ответ: 1Ответ: 1ПояснениеСпрятать пояснение &middot; Помощь","ans":"1"},{"id":5632,"tp":4,"kind":"choice","type":"Тип Д1","body":"<p>В какой из перечисленных городов была перенесена столица Северо-Восточной Руси князем Андреем Боголюбским?<p>&nbsp;</p><p>1)&#8239;&#8239;Владимир <p>2)&#8239;&#8239;Москва <p>3)&#8239;&#8239;Суздаль<p>4)&#8239;&#8239;Ростов","sol":"<b>Пояснение. </b><p>Андрей Боголюбский перенес столицу княжества из Суздаля во Владимир.<p>Правильный ответ: 1Ответ: 1ПояснениеСпрятать пояснение &middot; Помощь","ans":"1"},{"id":5837,"tp":2,"kind":"choice","type":"Тип Д1","body":"<p>Поляне, древляне, вятичи – это племенные союзы<p>&nbsp;</p><p>1)&#8239;&#8239;восточнославянские<p>2)&#8239;&#8239;балтские<p>3)&#8239;&#8239;угро-финские<p>4)&#8239;&#8239;тюркские","sol":"<b>Пояснение. </b><p>Это названия племен восточных славян. Правильный ответ: 1Ответ: 1ПояснениеСпрятать пояснение &middot; Помощь","ans":"1"},{"id":5878,"tp":4,"kind":"choice","type":"Тип Д1","body":"<p>Кто из перечисленных исторических лиц были современниками?<p>&nbsp;</p><p>1)&#8239;&#8239;Юрий Долгорукий и Ярослав Осмомысл<p>2)&#8239;&#8239;Александр Невский и Ярослав Мудрый<p>3)&#8239;&#8239;Всеволод III Большое Гнездо и Владимир Мономах<p>4)&#8239;&#8239;Андрей Боголюбский и Владимир Святой","sol":"<b>Пояснение. </b><p>Ярослав Владимирович (Владими́ркович) Осмомысл (ок. 1130—1 октября 1187) был современником Юрия Долгорукого 1090-е годы&#8239;&#8239;— 15 мая 1157 года.<p>Правильный ответ: 1Ответ: 1ПояснениеСпрятать пояснение &middot; Помощь","ans":"1"},{"id":5988,"tp":2,"kind":"choice","type":"Тип Д1","body":"<p>Назовите князя, в годы правления которого был заключён первый письменный договор между Русью и Византийской империей.<p>&nbsp;</p><p>1)&#8239;&#8239;Владимир Мономах<p>2)&#8239;&#8239;Олег Вещий<p>3)&#8239;&#8239;Игорь Старый<p>4)&#8239;&#8239;Владимир Святославич","sol":"<b>Пояснение. </b><p>Князь Олег в 911&#8239;г заключил первый письменный договор с Византией. Правильный ответ:2Ответ: 2ПояснениеСпрятать пояснение &middot; Помощь","ans":"2"},{"id":217,"tp":5,"kind":"choice","type":"Тип Д1","body":"<p>Какие из перечисленных дат относятся к монголо-татарскому нашествию на Русь?<p><p>&nbsp;</p><p>1)&#8239;&#8239;882-980&#8239;гг.<p>2)&#8239;&#8239;980-1025&#8239;гг.<p>3)&#8239;&#8239;1113-1125&#8239;гг.<p>4)&#8239;&#8239;1237-1240&#8239;гг.","sol":"<b>Пояснение. </b><p>Первые три ответа связаны с событиями домонгольской Руси. Например, 1113—1125&#8239;гг.&#8239;&#8239;— годы правления киевского князя Владимира Мономаха. 1237—1240&#8239;гг.&#8239;&#8239;— период нашествия хана Батыя на Русь.<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4ПояснениеСпрятать пояснение &middot; \n                    1 комментарий\n                     &middot; Помощь","ans":"4"},{"id":607,"tp":6,"kind":"choice","type":"Тип Д1","body":"<p>Кто стоял во главе русских войск, одержавших победу на льду Чудского озера?<p><p>&nbsp;</p><p>1)&#8239;&#8239;Дмитрий Донской<p>2)&#8239;&#8239;Александр Невский<p>3)&#8239;&#8239;Святослав Игоревич<p>4)&#8239;&#8239;Иван Калита","sol":"<b>Пояснение. </b><p>Разгром немецких рыцарей на льду Чудского озера произошел под руководством новгородского князя Александра Невского 5 апреля 1242&#8239;г. Имя Дмитрия Донского связано с победой русских над монголами на Куликовом поле в 1380&#8239;г. Князь Святослав проводил активную внешнюю политику в X в. Иван Калита правил в Москве в XIV в.<p>&nbsp;</p><p>Правильный ответ указан под номером: 2.Ответ: 2ПояснениеСпрятать пояснение &middot; Помощь","ans":"2"},{"id":2303,"tp":4,"kind":"choice","type":"Тип Д1","body":"<p>Кто из князей Древнерусского\tгосударства сумел приостановить распад государства в начале XII в.?<p><p>&nbsp;</p><p>1)&#8239;&#8239;Ярослав Мудрый<p>2)&#8239;&#8239;Юрий Долгорукий<p>3)&#8239;&#8239;Владимир Мономах<p>4)&#8239;&#8239;Всеволод Большое Гнездо","sol":"<b>Пояснение. </b><p>Распад  Древнерусского государства произошел в 30-е гг. XII в. Время правления Владимира Мономаха 1113—1125&#8239;гг. Правление Ярослава Мудрого относится к периоду расцвета Руси. Юрий Долгорукий и Всеволод Большое Гнездоправили в период раздробленности.<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3ПояснениеСпрятать пояснение &middot; Помощь","ans":"3"},{"id":3585,"tp":6,"kind":"choice","type":"Тип Д1","body":"<p>Какое из названных событий относится к XIII в.?<p><p>&nbsp;</p><p>1)&#8239;&#8239;«стояние» на реке Угре<p>2)&#8239;&#8239;сражение на реке Воже<p>3)&#8239;&#8239;Куликовская битва<p>4)&#8239;&#8239;Ледовое побоище","sol":"<b>Пояснение. </b><p>Ледовое побоище&#8239;&#8239;— 1242&#8239;г. XIII в, Куликовская  битва&#8239;&#8239;— 1380&#8239;г., битва на р. Воже&#8239;&#8239;— 1378&#8239;г., стояние на р. Угре&#8239;&#8239;— 1480&#8239;г.<p>&nbsp;</p><p>Ответ:  4.Ответ: 4Источник: ЕГЭ по истории 30.05.2013. Основная волна. Дальний Восток. Вариант 1ПояснениеСпрятать пояснение &middot; \n                    1 комментарий\n                     &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"4"},{"id":3865,"tp":4,"kind":"choice","type":"Тип Д1","body":"<p>В каком из центров удельной Руси (XII—XV вв.) высшим законодательным органом власти было вече?<p><p>&nbsp;</p><p>1)&#8239;&#8239;Новгороде<p>2)&#8239;&#8239;Владимире<p>3)&#8239;&#8239;Москве<p>4)&#8239;&#8239;Киеве","sol":"<b>Пояснение. </b><p>Высшими органами государственной власти в Новгороде являлись вече и Совет господ.<p>&nbsp;</p><p>По своему происхождению Новгородское вече было городским собранием, похожим на остальные, существовавшие в других городах Руси в XII столетии. Вече не было постоянно действующим органом. Оно созывалось не периодически, а только тогда, когда в нем была действительная необходимость. Чаще всего это случалось во время войн, восстаний и призыва князей. Вече созывалось князем, посадником или тысяцким на Торговой стороне города, на Ярославовом дворе, или же собирали вече по воле народа, на Софийской или Торговой стороне. Состояло оно из жителей как Новгорода, так и его пригородов; ограничений в среде новгородских граждан не было: всякий свободный и самостоятельный человек мог идти на вече. Вече собиралось по звону вечевого колокола. <p>&nbsp;</p><p>Правильный ответ указан под номером: 1.Ответ: 1Источник: ЕГЭ по истории 30.05.2013. Основная волна. Сибирь. Вариант 2ПояснениеСпрятать пояснение &middot; Помощь","ans":"1"},{"id":3985,"tp":4,"kind":"choice","type":"Тип Д1","body":"<p>В какой город была перенесена столица Северо-Восточной Руси Андреем Боголюбским?<p><p>&nbsp;</p><p>1)&#8239;&#8239;Ярославль<p>2)&#8239;&#8239;Ростов<p>3)&#8239;&#8239;Москва<p>4)&#8239;&#8239;Владимир","sol":"<b>Пояснение. </b><p>После смерти отца (1157) стал князем Владимирским, Ростовским и Суздальским. Став «самовластцем всей Суздальской земли», Андрей Боголюбский перенёс столицу княжества во Владимир.<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4Источник: ЕГЭ по истории 30.05.2013. Основная волна. Сибирь. Вариант 5ПояснениеСпрятать пояснение &middot; Помощь","ans":"4"},{"id":4185,"tp":5,"kind":"choice","type":"Тип Д1","body":"<p>Зимой 1239—1240&#8239;гг. опустошили Южную Русь и взяли Киев войска хана.<p>&nbsp;</p><p>1)&#8239;&#8239;Тамерлана<p>2)&#8239;&#8239;Батыя<p>3)&#8239;&#8239;Чингисхана<p>4)&#8239;&#8239;Мамая","sol":"<b>Пояснение. </b><p>Монголами во время их похода на Русь командовал внук Чингис-хана хан Батый.<p>&nbsp;</p><p>Правильный ответ указан под номером: 2.Ответ: 2ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"2"},{"id":41,"tp":2,"kind":"choice","type":"Тип Д1","body":"<p>С каким событием в истории России связано начало правления династии Рюриковичей?<p>&nbsp;</p><p>1)&#8239;&#8239;c походом князя Олега на Киев<p>2)&#8239;&#8239;с призванием варягов<p>3)&#8239;&#8239;с крещением Руси<p>4)&#8239;&#8239;с изданием Русской правды","sol":"<b>Пояснение. </b><p>Начало правления династии Рюриковичей связано с призванием варягов в 862 году в Новгород. Все русские князья и цари (1598&#8239;г.) считали себя потомками легендарного князя Рюрика. Поход Олега на Киев (882&#8239;г.), крещение Руси (988&#8239;г.), издание Русской правды (XI−XII вв.)&#8239;&#8239;—&#8239;это события, связанные с историей первого государства&#8239;&#8239;—&#8239;Древняя Русь.<p>&nbsp;</p><p>Правильный ответ указан под номером: 2.Ответ: 2ПояснениеСпрятать пояснение &middot; Помощь","ans":"2"},{"id":119,"tp":1,"kind":"choice","type":"Тип Д1","body":"<p>Какой из названных племенных союзов, по данным «Повести временных лет», жил на западном берегу Днепра? <p>&nbsp;</p><p><p>&nbsp;</p><p>1)&#8239;&#8239;поляне<p>2)&#8239;&#8239;кривичи<p>3)&#8239;&#8239;вятичи<p>4)&#8239;&#8239;дреговичи","sol":"<b>Пояснение. </b><p>На западном берегу Днепра жили дреговичи.Поляне жили в Среднем Приднепровье. Кривичи&#8239;&#8239;— в верховье Днепра. Вятичи&#8239;&#8239;— в междуречье Оки и Волги.<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4ПояснениеСпрятать пояснение &middot; \n                    2 комментария\n                     &middot; Помощь","ans":"4"},{"id":179,"tp":4,"kind":"choice","type":"Тип Д1","body":"<p>Кто из названных князей пригласил в 1147&#8239;г. Святослава Ольговича «в город Москов» на пир?<p><p>&nbsp;</p><p>1)&#8239;&#8239;Владимир Мономах<p>2)&#8239;&#8239;Андрей Боголюбский<p>3)&#8239;&#8239;Юрий Долгорукий<p>4)&#8239;&#8239;Иван Калита","sol":"<b>Пояснение. </b><p>В Ипатьевской летописи приводится факт встречи в 1147 году в Москве князя Святослава Ольговича и Юрия Долгорукого (1125—1157&#8239;гг.). 1147 год считают годом первого упоминания о Москве в летописи, а князя Юрия Долгорукого&#8239;&#8239;— основателем Москвы.<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3ПояснениеСпрятать пояснение &middot; Помощь","ans":"3"},{"id":998,"tp":5,"kind":"choice","type":"Тип Д1","body":"<p>Какое из названных событий произошло раньше других?<p><p>&nbsp;</p><p>1.&#8239;&#8239;Разгром немецких рыцарей на Чудском озере<p>2.&#8239;&#8239;Разгром шведских войск на реке Неве<p>3.&#8239;&#8239;Разорение монголо-татарами Рязанского и Владимиро-Суздальского княжеств<p>4.&#8239;&#8239;Куликовская битва","sol":"<b>Пояснение. </b><p>Раньше других произошло разорение монголо-татарами Рязанского и Владимиро-Суздальского княжеств&#8239;&#8239;— 1237—1238&#8239;гг. Разгром немецких рыцарей на Чудском озере произошел в 1242&#8239;г. Разгром шведских войск на реке Неве&#8239;&#8239;— в 1240&#8239;г. Куликовская битва произошла в 1380&#8239;г. <p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"3"},{"id":2304,"tp":5,"kind":"choice","type":"Тип Д1","body":"<p>Какое событие произошло в XIII в.?<p>&nbsp;</p><p>1.&#8239;&#8239;Созыв Любечского съезда князей<p>2.&#8239;&#8239;Составление «Русской правды»<p>3.&#8239;&#8239;Поход хана Тохтамыша на Москву<p>4.&#8239;&#8239;Установление монгольского владычества","sol":"<b>Пояснение. </b><p>Установление монгольского владычества произошло в XIII в. после нашествия Батыя на Русь. Созыв Любечского съезда князей произошел в 1097&#8239;г. (XI в.), составление «Русской правды» относится к XI в., поход хана Тохтамыша на Москву состоялся в 1382 году (XIV в.).<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4ПояснениеСпрятать пояснение &middot; Помощь","ans":"4"},{"id":3346,"tp":4,"kind":"choice","type":"Тип Д1","body":"<p>Общерусские походы против половцев в начале XII в. возглавлял князь<p><p>&nbsp;</p><p>1)&#8239;&#8239;Андрей Боголюбский<p>2)&#8239;&#8239;Дмитрий Донской<p>3)&#8239;&#8239;Владимир Мономах<p>4)&#8239;&#8239;Александр Невский","sol":"<b>Пояснение. </b><p>Андрей Боголюбский (около 1111&#8239;&#8239;— 1174), князь владимиро-суздальский с 1157, сын Юрия Долгорукого.<p>Дмитрий Иванович Донской (12.10.1350, Москва,&#8239;&#8239;— 19.5.1389, там же), великий князь владимирский и московский с 1359, сын князя Ивана II Ивановича Красного, внук Ивана I Даниловича Калиты.<p>Александр Невский (около 1220&#8239;&#8239;— 14.11.1263), русский государственный деятель, полководец, князь новгородский [1236—51], великий князь владимирский с 1252.<p>Владимир Всеволодович Мономах (1053—1125), великий князь киевский в 1113—25, государственный деятель, военачальник и писатель. Возглавлял общерусские походы против половцев.<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3Источник: ЕГЭ по истории 30.05.2013. Основная волна. Центр. Вариант 1ПояснениеСпрятать пояснение &middot; Помощь","ans":"3"},{"id":3386,"tp":6,"kind":"choice","type":"Тип Д1","body":"<p>Против кого сражалась русская рать в Невской битве в 1240&#8239;г.?<p><p>&nbsp;</p><p>1.&#8239;&#8239;Монголов<p>2.&#8239;&#8239;Половцев<p>3.&#8239;&#8239;Шведов<p>4.&#8239;&#8239;Хазар","sol":"<b>Пояснение. </b><p>В 1240 году новгородское войско под командованием Александра Ярославича разбило войско шведских рыцарей на месте их высадке на реке Неве.<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3Источник: ЕГЭ по истории 30.05.2013. Основная волна. Центр. Вариант 2ПояснениеСпрятать пояснение &middot; Помощь","ans":"3"},{"id":3546,"tp":6,"kind":"choice","type":"Тип Д1","body":"<p>Против кого сражалась русская рать в Невской битве в 1240&#8239;г.?<p><p>&nbsp;</p><p>1.&#8239;&#8239;Половцев<p>2.&#8239;&#8239;Хазар<p>3.&#8239;&#8239;Монголов<p>4.&#8239;&#8239;Шведов","sol":"<b>Пояснение. </b><p>В 1240&#8239;г. русские войска под руководством князя Александра Ярославича разбили войско шведских рыцарей.<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4Источник: ЕГЭ по истории 30.05.2013. Основная волна. Центр. Вариант 6ПояснениеСпрятать пояснение &middot; \n                    1 комментарий\n                     &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"4"},{"id":3547,"tp":3,"kind":"choice","type":"Тип Д1","body":"<p>Что из перечисленного было следствием набегов половцев во второй половине XI в.?<p><p>&nbsp;</p><p>1.&#8239;&#8239;Установление военного союза Руси с Великим княжеством Литовским<p>2.&#8239;&#8239;Полное прекращение княжеских междоусобиц<p>3.&#8239;&#8239;Установление военного союза Руси с Хазарским каганатом<p>4.&#8239;&#8239;Миграция населения из Среднего Поднепровья в Волжско-Окский район","sol":"<b>Пояснение. </b><p>Из-за постоянной половецкой угрозы началась миграция населения из Среднего Поднепровья в Волжско-Окский район, где люди чувствовали себя гораздо безопаснее.<p> Хазарского каганата уже не было, Великого княжества Литовского еще не было.<p> А княжеские усобицы только усилились, так как теперь русские князья для борьбы со своими противниками приглашали половецкие отряды.<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4Источник: ЕГЭ по истории 30.05.2013. Основная волна. Центр. Вариант 6ПояснениеСпрятать пояснение &middot; Помощь","ans":"4"},{"id":3746,"tp":5,"kind":"choice","type":"Тип Д1","body":"<p>Какое из перечисленных событий произошло раньше других?<p><p>&nbsp;</p><p>1)&#8239;&#8239;Ледовое побоище<p>2)&#8239;&#8239;«стояние» на реке Угре<p>3)&#8239;&#8239;Куликовская битва<p>4)&#8239;&#8239;битва на реке Калке","sol":"<b>Пояснение. </b><p>Битва на реке Калке  1223&#8239;г., Ледовое побоище 1242&#8239;г., Куликовская  битва 1380&#8239;г., Стояние на Угре 1480&#8239;г.<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4Источник: ЕГЭ по истории 30.05.2013. Основная волна. Дальний Восток. Вариант 5ПояснениеСпрятать пояснение &middot; \n                    1 комментарий\n                     &middot; Помощь","ans":"4"},{"id":4066,"tp":5,"kind":"choice","type":"Тип Д1","body":"<p>Что из названного было причиной поражения русских войск на реке Калке в 1223&#8239;г.?<p><p>&nbsp;</p><p>1.&#8239;&#8239;Вассальная зависимость русских земель от монголов<p>2.&#8239;&#8239;Выступление половцев на стороне монголов<p>3.&#8239;&#8239;Несогласованность в действиях русских князей<p>4.&#8239;&#8239;Союз монголов с немецкими рыцарями","sol":"<b>Пояснение. </b><p>Часть князей не вышли сражаться в поле, а соорудили лагерь на холме. Монголы разбили их поочередно.<p>Несогласованность в их действиях&#8239;&#8239;— одна из причин поражения.<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3Источник: ЕГЭ по истории 30.05.2013. Основная волна. Урал. Вариант 1ПояснениеСпрятать пояснение &middot; Помощь","ans":"3"},{"id":4266,"tp":5,"kind":"choice","type":"Тип Д1","body":"<p>Что из названного было причиной поражения русских войск на реке Калке в 1223&#8239;г.?<p><p>&nbsp;</p><p>1.&#8239;&#8239;Вассальная зависимость русских земель от монголов<p>2.&#8239;&#8239;Союз монголов с немецкими рыцарями<p>3.&#8239;&#8239;Несогласованность в действиях русских князей<p>4.&#8239;&#8239;Выступление половцев на стороне монголов","sol":"<b>Пояснение. </b><p>Несогласованность русских князей, часть которых не вступила в сражение а осталась в укрепленных лагере, привела к поражению. <p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3Источник: ЕГЭ по истории 30.05.2013. Основная волна. Урал. Вариант 5ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"3"},{"id":4495,"tp":4,"kind":"choice","type":"Тип Д1","body":"<p>Правление какого князя относится к середине XII в. ?<p>&nbsp;</p><p>1)&#8239;&#8239;Александра Невского<p>2)&#8239;&#8239;Юрия Долгорукого<p>3)&#8239;&#8239;Ярослава Мудрого<p>4)&#8239;&#8239;Владимира Святого","sol":"<b>Пояснение. </b><p>Правление Александра Невского относится к XIII в;<p>Правление Юрия Долгорукого к XII в;<p>Ярослава Мудрого 1019−1054&#8239;гг.); Владимира Святого (980−1015&#8239;гг.).<p>&nbsp;</p><p>Правильный ответ указан под номером: 2.Ответ: 2ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"2"},{"id":180,"tp":5,"kind":"choice","type":"Тип Д2","body":"<p>Русь попала в зависимость от Золотой Орды в результате<p><p>&nbsp;</p><p>1)&#8239;&#8239;нашествия Батыя<p>2)&#8239;&#8239;похода Мамая<p>3)&#8239;&#8239;походов Чингисхана<p>4)&#8239;&#8239;набегов половцев","sol":"<b>Пояснение. </b><p>В результате похода Батыя на Русь 1237—1240&#8239;гг. русские земли попали в зависимость от Золотой Орды. Зависимость заключалась в уплате дани в пользу Орды и получении князьями ярлыка на княжение. Поход Чингисхана был ранее, поход Мамая позднее и привел к ослаблению зависимости русских земель от Орды.<p>&nbsp;</p><p>Правильный ответ указан под номером: 1.Ответ: 1ПояснениеСпрятать пояснение &middot; Помощь","ans":"1"},{"id":765,"tp":3,"kind":"choice","type":"Тип Д2","body":"<p>Что из указанного относится к последствиям правления Владимира Мономаха?<p><p>&nbsp;</p><p>1.&#8239;&#8239;Упорядоченная система налогообложения<p>2.&#8239;&#8239;Ограничение законом имущественных прав смердов<p>3.&#8239;&#8239;Принятие Русью христианства из Византии<p>4.&#8239;&#8239;Обеспечение защиты границ Руси от набегов половцев","sol":"<b>Пояснение. </b><p>Владимир Мономах совершил удачные походы против половцев в XII веке и обеспечил защиту границ Руси от их набегов. Остальные события произошли раньше. <p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4ПояснениеСпрятать пояснение &middot; \n                    1 комментарий\n                     &middot; Помощь","ans":"4"},{"id":1038,"tp":1,"kind":"choice","type":"Тип Д2","body":"<p>Переход восточных славян от родовой к соседской общине во второй половине I тыс.&#8239;н.&#8239;э. привёл к<p><p>&nbsp;</p><p>1)&#8239;&#8239;появлению индивидуального крестьянского хозяйства<p>2)&#8239;&#8239;организации коллективного труда на общей пашне<p>3)&#8239;&#8239;возникновению феодальной собственности на землю<p>4)&#8239;&#8239;появлению частной собственности крестьян на свои наделы","sol":"<b>Пояснение. </b><p>Переход восточных славян от родовой к соседской общине во второй половине I тыс.&#8239;н.&#8239;э. привёл к появлению частной собственности крестьян на свои наделы. Соседская община состояла из отдельных семей, за которыми были закреплены земельные наделы. Это породило частную собственность, а в последствии социальное неравенство. Таким образом, славянское общество подходило к возникновению государственности.<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4ПояснениеСпрятать пояснение &middot; \n                    1 комментарий\n                     &middot; Помощь","ans":"4"},{"id":1078,"tp":3,"kind":"choice","type":"Тип Д2","body":"<p>Что из перечисленного было одним из результатов княжения Владимира Мономаха?<p><p>&nbsp;</p><p>1.&#8239;&#8239;Временное ослабление княжеских усобиц<p>2.&#8239;&#8239;Полный разгром половцев<p>3.&#8239;&#8239;Перенесение столицы из Киева в Новгород<p>4.&#8239;&#8239;Зарождение каменного зодчества на Руси","sol":"<b>Пояснение. </b><p>Одним из результатов княжения Владимира Мономаха было временное ослабление княжеских усобиц. Он сумел восстановить единство русских земель вокруг Киева, совершил успешные походы против половцев.<p>&nbsp;</p><p>Правильный ответ указан под номером: 1.Ответ: 1ПояснениеСпрятать пояснение &middot; \n                    3 комментария\n                     &middot; Помощь","ans":"1"},{"id":1117,"tp":3,"kind":"choice","type":"Тип Д2","body":"<p>Что из перечисленного было одним из результатов княжения Ярослава Мудрого?<p><p>&nbsp;</p><p>1.&#8239;&#8239;Появление письменности на Руси<p>2.&#8239;&#8239;Разгром Хазарии<p>3.&#8239;&#8239;Постройка Софийского собора в Киеве<p>4.&#8239;&#8239;Постройка Успенского собора во Владимире","sol":"<b>Пояснение. </b><p>Одним из результатов княжения Ярослава Мудрого (1019—1054&#8239;гг.) был разгром печенегов в 1036 году и в честь этой победы постройка Софийского собора в Киеве. Письменность на Руси появилась раньше. Хазария была разгромлена в 966 году князем Святославом. Успенский собор во Владимире был построен в XII веке.<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"3"},{"id":1200,"tp":3,"kind":"choice","type":"Тип Д2","body":"<p>Что из названного относится к последствиям правления Владимира Мономаха?<p><p>&nbsp;</p><p>1.&#8239;&#8239;Упорядоченная система налогообложения<p>2.&#8239;&#8239;Ограничение законом имущественных прав смердов<p>3.&#8239;&#8239;Принятие Русью христианства из Византии<p>4.&#8239;&#8239;Обеспечение защиты границ Руси от набегов половцев","sol":"<b>Пояснение. </b><p>К последствиям правления Владимира Мономаха относится обеспечение защиты границ Руси от набегов половцев. Владимир Мономах совершил много удачных походов против половцев. Княгиня Ольга ввела упорядоченную систему налогообложения. Имущественные права смердов защищены по «Русской правде». Христианство было принято при Владимире Красно Солнышко.<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4ПояснениеСпрятать пояснение &middot; Помощь","ans":"4"},{"id":1251,"tp":5,"kind":"choice","type":"Тип Д2","body":"<p>Что явилось итогом похода войск Батыя на Русь в 1237—1238&#8239;гг.?<p><p>&nbsp;</p><p>1.&#8239;&#8239;Включение Рязанского княжества в состав Золотой Орды<p>2.&#8239;&#8239;Разорение Киева<p>3.&#8239;&#8239;Разорение Великого Новгорода<p>4.&#8239;&#8239;Разорение северо-восточных земель","sol":"<b>Пояснение. </b><p>В итоге похода Батыя на Русь 1237—1238&#8239;гг. были разорены северо-восточные земли. Разорение Киева произошло в 1240 году. До Новгорода монголы не дошли. Рязань в состав золотой Орды никогда не входила.<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4ПояснениеСпрятать пояснение &middot; Помощь","ans":"4"},{"id":2305,"tp":5,"kind":"choice","type":"Тип Д2","body":"<p>Что явилось последствием ордынского владычества?<p>&nbsp;</p><p>1.&#8239;&#8239;Вхождение русских княжеств в состав Золотой Орды<p>2.&#8239;&#8239;Распад Древнерусского государства на княжества и земли<p>3.&#8239;&#8239;Упадок торгового пути «из варяг в греки»<p>4.&#8239;&#8239;Изменение характера княжеской власти","sol":"<b>Пояснение. </b><p>Последствием ордынского владычества явилось изменение характера княжеской власти, так как русские князья должны были получать в Орде ярлык на великое княжение.<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4ПояснениеСпрятать пояснение &middot; Помощь","ans":"4"},{"id":3176,"tp":4,"kind":"choice","type":"Тип Д2","body":"<p>Наступивший в 30-е гг. XII в. политический распад Древнерусского государства привёл к<p>&nbsp;</p><p>1)&#8239;&#8239;расколу Русской православной церкви<p>2)&#8239;&#8239;возрождению полюдья как способа сбора дани киевским князем с подвластных земель<p>3)&#8239;&#8239;снижению обороноспособности русских земель<p>4)&#8239;&#8239;призванию варягов для управления русскими землями","sol":"<b>Пояснение. </b><p>Раскол русской православной церкви&#8239;&#8239;— XVII в.; полюдье как форма сбора дани киевским князем существовала до 945&#8239;г.; призвание варягов для управления русскими землями в 862&#8239;г.<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3ПояснениеСпрятать пояснение &middot; Помощь","ans":"3"},{"id":3216,"tp":2,"kind":"choice","type":"Тип Д2","body":"<p>Что стало одним из результатов военных походов Святослава Игоревича?<p>&nbsp;</p><p>1.&#8239;&#8239;Крещение Святослава и его дружины в Византии<p>2.&#8239;&#8239;Разгром Ливонского ордена<p>3.&#8239;&#8239;Прекращение набегов половцев на русские земли<p>4.&#8239;&#8239;Разгром Хазарского каганата","sol":"<b>Пояснение. </b><p>Святослав оставался язычником, Ливонский орден был разгромлен в XVI в., половцы пришли в степи в Днепром и Волгой в XI в.<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"4"},{"id":3427,"tp":3,"kind":"choice","type":"Тип Д2","body":"<p>Что из перечисленного было следствием набегов половцев во второй половине XI в.?<p><p>&nbsp;</p><p>1.&#8239;&#8239;Миграция населения из Среднего Поднепровья в Волжско-Окский район<p>2.&#8239;&#8239;Установление военного союза Руси с Хазарским каганатом<p>3.&#8239;&#8239;Полное прекращение княжеских междоусобиц<p>4.&#8239;&#8239;Установление военного союза Руси с Великим княжеством Литовским","sol":"<b>Пояснение. </b><p>Из-за набегов половцев началась миграция населения из Среднего Поднепровья в Волжско-Окский район, где люди чувствовали себя в большей безопасности.  Хазарский каганат к тому времени уже прекратил свое существование; Великого княжества Литовского еще не было; вторжение половцев не только не привело к прекращению княжеских усобиц, а даже усилило их так как русские князья часто использовали половецкие отряды для борьбы со своими соперниками.<p>&nbsp;</p><p>Правильный ответ указан под номером: 1.Ответ: 1Источник: ЕГЭ по истории 30.05.2013. Основная волна. Центр. Вариант 3ПояснениеСпрятать пояснение &middot; Помощь","ans":"1"},{"id":3827,"tp":2,"kind":"choice","type":"Тип Д2","body":"<p>Что из перечисленного относится к результатам правления древнерусского князя Олега?<p><p>&nbsp;</p><p>1.&#8239;&#8239;Принятие Русью христианства<p>2.&#8239;&#8239;Подавление восстания древлян<p>3.&#8239;&#8239;Принятие Русской Правды<p>4.&#8239;&#8239;Объединение Киева и Новгорода","sol":"<b>Пояснение. </b><p>Олег (882−912&#8239;гг.) сумел объединить Киев и Новгород и на пути из варяг в греки основать Древнерусское государство. Все остальное было позже: принятие Русью христианства 988&#8239;г.; подавление восстания древлян&#8239;&#8239;— 945&#8239;г.; принятие Русской Правды&#8239;&#8239;— 1038&#8239;г.<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4Источник: ЕГЭ по истории 30.05.2013. Основная волна. Сибирь. Вариант 1ПояснениеСпрятать пояснение &middot; Помощь","ans":"4"},{"id":3907,"tp":5,"kind":"choice","type":"Тип Д2","body":"<p>Что было одной из причин поражения Руси в борьбе с монголами в XIII в.?<p><p>&nbsp;</p><p>1.&#8239;&#8239;Военная и политическая разобщённость русских земель<p>2.&#8239;&#8239;Создание военного союза между монголами и немецкими рыцарями<p>3.&#8239;&#8239;Союз монголов с половецкими ханами<p>4.&#8239;&#8239;Начало проведения военной реформы в русских землях","sol":"<b>Пояснение. </b><p>Кроме силы монгольского войска, еще одной важной причиной поражения русских земель стала их разобщенность из-за феодальной раздробленности.<p>&nbsp;</p><p>Правильный ответ указан под номером: 1.Ответ: 1Источник: ЕГЭ по истории 30.05.2013. Основная волна. Сибирь. Вариант 3ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"1"},{"id":4027,"tp":2,"kind":"choice","type":"Тип Д2","body":"<p>Что из перечисленного относится к результатам правления древнерусского князя Олега?<p><p>&nbsp;</p><p>1.&#8239;&#8239;Объединение Киева и Новгорода<p>2.&#8239;&#8239;Подавление восстания древлян<p>3.&#8239;&#8239;Принятие Русской Правды<p>4.&#8239;&#8239;Принятие Русью христианства","sol":"<b>Пояснение. </b><p>Олег (882−912&#8239;гг.) объединил в единое целое Древнерусское государство с центрами в Киеве и Новгороде.<p>&nbsp;</p><p>Правильный ответ указан под номером: 1.Ответ: 1Источник: ЕГЭ по истории 30.05.2013. Основная волна. Сибирь. Вариант 6ПояснениеСпрятать пояснение &middot; Помощь","ans":"1"},{"id":4067,"tp":2,"kind":"choice","type":"Тип Д2","body":"<p>Следствием активной военной деятельности князя Святослава Игоревича стало<p><p>&nbsp;</p><p>1)&#8239;&#8239;расширение территории Древнерусского государства<p>2)&#8239;&#8239;заключение первого письменного договора с Византией<p>3)&#8239;&#8239;объединение Киева и Новгорода под властью одного князя<p>4)&#8239;&#8239;прекращение набегов печенегов на русские земли","sol":"<b>Пояснение. </b><p>Святослав в ходе своих походов присоединил к территории Древнерусского государства новые земли, а вот пресечь набеги печенегов не смог. <p>&nbsp;</p><p>Правильный ответ указан под номером: 1.Ответ: 1Источник: ЕГЭ по истории 30.05.2013. Основная волна. Урал. Вариант 1ПояснениеСпрятать пояснение &middot; Помощь","ans":"1"},{"id":4227,"tp":6,"kind":"choice","type":"Тип Д2","body":"<p>Что из названного являлось одним из итогов деятельности князя Александра Невского?<p><p>&nbsp;</p><p>1.&#8239;&#8239;Обеспечение безопасности северо-западных рубежей Руси<p>2.&#8239;&#8239;Укрепление Москвы как центра объединения русских земель<p>3.&#8239;&#8239;Присоединение к Москве Великого Новгорода<p>4.&#8239;&#8239;Получение от Золотой Орды права сбора дани со всех русских земель","sol":"<b>Пояснение. </b><p>Александр Невский будучи новгородским князем сумел обеспечить безопасность северо-западных рубежей Руси, нанеся поражения шведским и немецким рыцарям. <p>&nbsp;</p><p>Правильный ответ указан под номером: 1.Ответ: 1Источник: ЕГЭ по истории 30.05.2013. Основная волна. Урал. Вариант 4ПояснениеСпрятать пояснение &middot; \n                    1 комментарий\n                     &middot; Помощь","ans":"1"},{"id":4496,"tp":2,"kind":"choice","type":"Тип Д2","body":"<p>Что из названного было причиной неудачи языческой реформы князя Владимира в 980&#8239;г.?<p>&nbsp;</p><p>1.&#8239;&#8239;Многие славянские племена, входившие в состав Киевской Руси, уже приняли христианство<p>2.&#8239;&#8239;При реформе ни один из славянских языческих богов не был обозначен как верховное божество<p>3.&#8239;&#8239;При реформе не было создано единого святилища (капища) языческих богов<p>4.&#8239;&#8239;Каждое племя продолжало поклоняться своим богам, не нуждаясь в едином религиозном центре","sol":"<b>Пояснение. </b><p>Одной из причин неудачи языческой реформы князя Владимира в 980&#8239;г. стало, то что каждое племя продолжало поклоняться своим богам, не нуждаясь в едином религиозном центре.<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4ПояснениеСпрятать пояснение &middot; \n                    1 комментарий\n                     &middot; Помощь","ans":"4"},{"id":4586,"tp":2,"kind":"choice","type":"Тип Д2","body":"<p>Что из названного было одной из причин Крещения Руси?<p>&nbsp;</p><p>1.&#8239;&#8239;Обещание римским папой помощи в борьбе с кочевниками<p>2.&#8239;&#8239;Заключение союза с Хазарским каганатом<p>3.&#8239;&#8239;Крестовые походы против Руси немецких рыцарей<p>4.&#8239;&#8239;Стремление великого князя киевского сплотить своё государство","sol":"<b>Пояснение. </b><p>Владимир стремился сплотить свое государство принятием единой веры. <p>Все остальное неверно: <p>1.&#8239;&#8239;римский папа не имел отношения к принятию Русью христиантва, Русь принимала христианство от Византии;<p>2.&#8239;&#8239;Хазарский каганат уже не существовал;<p>3.&#8239;&#8239;крестовые походы начнутся значительно позже.<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"4"},{"id":4626,"tp":5,"kind":"choice","type":"Тип Д2","body":"<p>Что из перечисленного относится к причинам успеха монгольского нашествия на Русь?<p>&nbsp;</p><p>1.&#8239;&#8239;Отказ великого князя владимирского от попыток сопротивления нашествию<p>2.&#8239;&#8239;Совместные действия монголов и западных феодалов против Руси<p>3.&#8239;&#8239;Ослабление русских земель в результате борьбы с Великим княжеством Литовским<p>4.&#8239;&#8239;Политическая раздробленность русских земель","sol":"<b>Пояснение. </b><p>Политическая раздробленность ослабила русские княжества поодиночке они не имели сил противостоять монголо-татарам.<p> Все остальное неверно:<p>1 Владимирский князь боролся и погиб на реке Сити.<p>2.&#8239;&#8239;Совместных действий не было.<p>3.&#8239;&#8239;Великого княжества Литовского еще не было.<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4ПояснениеСпрятать пояснение &middot; Помощь","ans":"4"},{"id":4712,"tp":3,"kind":"choice","type":"Тип Д2","body":"<p>Что стало непосредственным следствием Любеческого съезда князей?<p>&nbsp;</p><p>1.&#8239;&#8239;Временное ограничение междоусобиц<p>2.&#8239;&#8239;Перенос столицы из Киева во Владимир<p>3.&#8239;&#8239;Союз с половцами против монголов<p>4.&#8239;&#8239;Крещение Руси","sol":"<b>Пояснение. </b><p>Съезд князей в Любече прекратил временно междоусобные распри и объединил князей для борьбы с половцами. <p>&nbsp;</p><p>Правильный ответ указан под номером: 1.Ответ: 1ПояснениеСпрятать пояснение &middot; Помощь","ans":"1"},{"id":4832,"tp":5,"kind":"choice","type":"Тип Д2","body":"<p>К последствиям установления ордынского владычества на Руси относится<p>&nbsp;</p><p>1)&#8239;&#8239;начало раздробления Древнерусского государства<p>2)&#8239;&#8239;отмена местничества<p>3)&#8239;&#8239;введение уроков и погостов<p>4)&#8239;&#8239;получение русскими князьями ярлыков на княжение","sol":"<b>Пояснение. </b><p>После установления зависимости русских княжеств от Орды, русские князья должны были получать разрешение&#8239;&#8239;— ярлык. на право княжения в Орде.<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4ПояснениеСпрятать пояснение &middot; Помощь","ans":"4"},{"id":4872,"tp":2,"kind":"choice","type":"Тип Д2","body":"<p>К итогам походов древнерусского князя Святослава относится<p>&nbsp;</p><p>1)&#8239;&#8239;объединение Киева и Новгорода под единой княжеской властью<p>2)&#8239;&#8239;разгром печенегов<p>3)&#8239;&#8239;покорение половцев<p>4)&#8239;&#8239;разгром Хазарского каганата","sol":"<b>Пояснение. </b><p>Святослав в ходе своих походов разгромил Хазарский каганат. <p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4ПояснениеСпрятать пояснение &middot; Помощь","ans":"4"},{"id":4995,"tp":2,"kind":"choice","type":"Тип Д2","body":"<p>Что стало одним из результатов похода князя Олега Вещего на Константинополь?<p>&nbsp;</p><p>1.&#8239;&#8239;Гибель князя Олега<p>2.&#8239;&#8239;Поражение русского войска от византийцев, применивших «греческий огонь»<p>3.&#8239;&#8239;Заключение выгодного для Руси торгового договора<p>4.&#8239;&#8239;Заключение брака между Олегом и византийской принцессой","sol":"<b>Пояснение. </b><p>В результате похода Олега на Константинополь, по легенде прибил свой щит на врата Царьграда, Русь заключила выгодный торговый договор с Византией.<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"3"},{"id":5035,"tp":3,"kind":"choice","type":"Тип Д2","body":"<p>Что стало одним из последствий восстания в Киеве в 1113&#8239;г.?<p>&nbsp;</p><p>1.&#8239;&#8239;Призвание варяжских князей<p>2.&#8239;&#8239;Упорядочение сбора дани&#8239;&#8239;— установление «уроков» и «погостов»<p>3.&#8239;&#8239;Отмена кровной мести<p>4.&#8239;&#8239;Законодательный запрет на превращение свободного человека в холопы за долги","sol":"<b>Пояснение. </b><p>Владимир Мономах захвативший власть в Киеве в 1113&#8239;г. принял новый сборник законов «Устав Владимира Всеволодовича», в котором запретил превращать свободных людей в холопы за долги.<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4ПояснениеСпрятать пояснение &middot; Помощь","ans":"4"},{"id":5593,"tp":2,"kind":"choice","type":"Тип Д2","body":"<p>Что из названного относится к последствиям восстания древлян 945&#8239;г.?<p>&nbsp;</p><p>1.&#8239;&#8239;Изменение порядка сбора дани в Киевской Руси<p>2.&#8239;&#8239;Распад Древнерусского государства<p>3.&#8239;&#8239;Перенос столицы из Киева во Владимир<p>4.&#8239;&#8239;Ограничение ростовщического процента Уставом о резанах","sol":"<b>Пояснение. </b><p>Ольга после подавления восстания крестьян провела реформу сбора дани, учредив уроки и погосты.<p>Правильный ответ: 1Ответ: 1ПояснениеСпрятать пояснение &middot; Помощь","ans":"1"},{"id":5633,"tp":4,"kind":"choice","type":"Тип Д2","body":"<p>Что из перечисленного было одной из причин (предпосылок) политической раздробленности Руси?<p>&nbsp;</p><p>1.&#8239;&#8239;Уплата Русью дани Орде<p>2.&#8239;&#8239;Развитие торговли с Византией<p>3.&#8239;&#8239;Угроза набегов печенегов<p>4.&#8239;&#8239;Упадок пути «из варяг в греки»","sol":"<b>Пояснение. </b><p>К числу причин начала раздробленности русских земель относится: наличие слабых экономических связей между отдельными частями государства, которое усугубилось приходом в упадок торгового пути из варяг в греки.<p>Правильный ответ: 4Ответ: 4ПояснениеСпрятать пояснение &middot; Помощь","ans":"4"},{"id":5919,"tp":4,"kind":"choice","type":"Тип Д2","body":"<p>Что было одной из причин наступившей в 30-е гг. XII в. политической раздробленности?<p>&nbsp;</p><p>1.&#8239;&#8239;Господство натурального хозяйства<p>2.&#8239;&#8239;Распространение языческих верований<p>3.&#8239;&#8239;Установление власти Золотой Орды над Русью<p>4.&#8239;&#8239;Утверждение вечевых порядков во всех русских землях","sol":"<b>Пояснение. </b><p>Слабость экономических связей и господство натурального хозяйства - основные причины феодальной раздробленности.<p>Правильный ответ: 1Ответ: 1ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"1"},{"id":6029,"tp":5,"kind":"choice","type":"Тип Д2","body":"<p>Что из перечисленного явилось одним из последствий монгольского нашествия на Русь в XIII в.?<p>&nbsp;</p><p>1.&#8239;&#8239;Начало распада Руси на самостоятельные земли<p>2.&#8239;&#8239;Передача баскакам управления русскими городами<p>3.&#8239;&#8239;Установление экономической зависимости Руси от Золотой Орды<p>4.&#8239;&#8239;Включение всех русских земель в состав Золотой Орды","sol":"<b>Пояснение. </b><p>в результате похода Батыя Русь потерял экономическую и политическую независимость. правильный ответ: 3Ответ: 3ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"3"},{"id":494,"tp":3,"kind":"choice","type":"Тип Д3","body":"<p>Прочтите отрывок из сочинения современного историка и укажите, как называлась летопись, о которой говорится в документе.<p>&nbsp;</p><p>«Эпоха Владимира Мономаха была временем расцвета художественной и культурной деятельности на Руси. В Киеве и в других городах воздвигались новые каменные церкви, украшенные живописью... К этому времени относится составление нашей первоначальной летописи».<p><p>&nbsp;</p><p>1)&#8239;&#8239;«Апостол»<p>2)&#8239;&#8239;«Русская Правда»<p>3)&#8239;&#8239;«Изборник»<p>4)&#8239;&#8239;«Повесть временных лет»","sol":"<b>Пояснение. </b><p>В начале XII века в период княжения Владимира Мономаха монах Киево-Печерского монастыря Нестор составил летопись «Повесть временных лет». «Апостол»&#8239;&#8239;— первая печатная книга, изданная в&#8239;1564 году. «Русская правда»&#8239;&#8239;— свод законов XI—XII вв. «Изборник»&#8239;&#8239;— книга XIII века.<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4ПояснениеСпрятать пояснение &middot; \n                    1 комментарий\n                     &middot; Помощь","ans":"4"},{"id":805,"tp":4,"kind":"choice","type":"Тип Д3","body":"<p>Какой из названных памятников был построен в XII в.?<p><p>&nbsp;</p><p>1.&#8239;&#8239;Церковь Покрова на Нерли<p>2.&#8239;&#8239;Успенский собор Московского Кремля<p>3.&#8239;&#8239;Храм Василия Блаженного<p>4.&#8239;&#8239;Церковь Вознесения в селе Коломенском","sol":"<b>Пояснение. </b><p>В XII веке во Владимиро-Суздальской земле была построена церковь Покрова на Нерли. Успенский собор Московского кремля был возведен в XV веке. Храм Василия Блаженного, церковь Вознесения в селе Коломенском были возведены в XVI веке.<p>&nbsp;</p><p>Правильный ответ указан под номером: 1.Ответ: 1ПояснениеСпрятать пояснение &middot; \n                    1 комментарий\n                     &middot; Помощь","ans":"1"},{"id":2306,"tp":4,"kind":"choice","type":"Тип Д3","body":"<p>К памятникам архитектуры Владимиро-Суздальской земли относится<p>&nbsp;</p><p>1)&#8239;&#8239;Церковь Спаса на р. Нередице<p>2)&#8239;&#8239;собор Василия Блаженного<p>3)&#8239;&#8239;Церковь Покрова на Нерли<p>4)&#8239;&#8239;Церковь Фёдора Стратилата на Ручье","sol":"<b>Пояснение. </b><p>Церковь Покрова на Нерли является памятником архитектуры Владимиро-Суздальской земли. Церковь Спаса на р. Нередице и Церковь Фёдора Стратилата на Ручье памятники архитектуры Новгородской земли. Собор Василия Блаженного был построен в Москве.<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"3"},{"id":3177,"tp":3,"kind":"choice","type":"Тип Д3","body":"<p>Создание какого памятника зодчества относится к XI в.?<p>&nbsp;</p><p>1)&#8239;&#8239;Дмитриевского собора во Владимире<p>2)&#8239;&#8239;Благовещенского собора в Москве<p>3)&#8239;&#8239;Софийского собора в Новгороде<p>4)&#8239;&#8239;Церкви Покрова в Филях","sol":"<b>Пояснение. </b><p>Дмитриевский собор во Владимире&#8239;&#8239;— XII&#8239;в.; Благовещенский собор в Москве&#8239;&#8239;— конец XV&#8239;в.; Церковь Покрова в Филях&#8239;&#8239;— конец XVII&#8239;в.<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3ПояснениеСпрятать пояснение &middot; Помощь","ans":"3"},{"id":3348,"tp":4,"kind":"choice","type":"Тип Д3","body":"<p>Какой из названных храмов является памятником древнерусского зодчества XII в.?<p><p>&nbsp;</p><p>1)&#8239;&#8239;Архангельский собор Московского Кремля<p>2)&#8239;&#8239;церковь Покрова на Нерли<p>3)&#8239;&#8239;церковь Вознесения в селе Коломенском<p>4)&#8239;&#8239;собор Василия Блаженного в Москве","sol":"<b>Пояснение. </b><p> Первый деревянный Архангельский собор в Кремле возник на месте нынешнего, возможно, ещё во время княжения Михаила Хоробрита, брата Александра Невского, в 1247—1248 годах. В 1333 году, за одно лето, Иван Калита построил новый каменный храм&#8239;&#8239;— по обету, в благодарность за избавление Руси от голода, вызванного пошедшей в рост и не давшей зёрен рожью. Новый Архангельский собор был освящён митрополитом Феогностом 20 сентября 1333 года. Существующий собор был сооружён в 1505—1508&#8239;гг. под руководством итальянского зодчего Алевиза Нового на месте старого собора XIV века<p> Церковь Покрова на Нерли&#8239;&#8239;— традиционной является датировка храма по Н.&#8239;Н.&#8239;Воронину&#8239;&#8239;— 1165 год, основанная на сообщении Жития Андрея Боголюбского о том, что церковь Покрова была построена в память о погибшем сыне великого князя&#8239;&#8239;— Изяславе Андреевиче. Современные исследователи С.&#8239;В.&#8239;Заграевский и Т.&#8239;П.&#8239;Тимофеевана основании летописной информации обосновывают более раннюю дату храма&#8239;&#8239;— 1158 год.<p>Церковь Вознесения Господня в селе Коломенском на Москве-реке была построена в 1532 году. <p>Собор Василия Блаженного в Москве или Покровский собор был построен в 1555—1561 годах по приказу Ивана Грозного в память о взятии Казани и победе над Казанским ханством.<p>&nbsp;</p><p>Правильный ответ указан под номером: 2.Ответ: 2Источник: ЕГЭ по истории 30.05.2013. Основная волна. Центр. Вариант 1ПояснениеСпрятать пояснение &middot; Помощь","ans":"2"},{"id":5674,"tp":4,"kind":"choice","type":"Тип Д3","body":"<p>Церковь Покрова на Нерли была построена в период княжения во Владимиро-Суздальской земле<p>&nbsp;</p><p>1)&#8239;&#8239;Юрия Долгорукого<p>2)&#8239;&#8239;Андрея Боголюбского<p>3)&#8239;&#8239;Всеволода Большое Гнездо<p>4)&#8239;&#8239;Юрия Всеволодовича","sol":"<b>Пояснение. </b><p>Церковь Покрова на Нерли построена при Андрее Боголюбском в 1165г.<p>Правильный ответ:2Ответ: 2ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"2"},{"id":455,"tp":2,"kind":"choice","type":"Тип Д4","body":"<p>Прочтите отрывок из летописи и укажите, о ком идёт речь в приведённом отрывке.<p>&nbsp;</p><p>«Сказал (он) матери своей и боярам своим: \"Не любо мне сидеть в Киеве, хочу жить в Переяславце на Дунае&#8239;&#8239;— ибо там середина земли моей, туда стекаются все блага: из Греческой земли&#8239;&#8239;— золото, паволоки, вина, различные аллоды, из Чехии и из Венгрии серебро и кони, из Руси же меха и воск, мёд и рабы\"».<p><p>&nbsp;</p><p>1)&#8239;&#8239;Олеге<p>2)&#8239;&#8239;Игоре<p>3)&#8239;&#8239;Святославе<p>4)&#8239;&#8239;Ярославе","sol":"<b>Пояснение. </b><p>Эти слова принадлежат киевскому князю Святославу, который проводил активную внешнюю политику. Во время войны с Дунайской Болгарией, одержав ряд побед,  Святослав решил перенести столицу в город Переяславец в устье Дуная&#8239;&#8239;— крупный торговый центр Европы. Но попытка окончилась неудачей.<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"3"},{"id":806,"tp":2,"kind":"choice","type":"Тип Д4","body":"<p>Прочтите отрывок из книги современного историка А.&#8239;Ю.&#8239;Карпова и определите, о каком историческом персонаже идёт речь:<p>&nbsp;</p><p>«Но отсвет её дел, отсвет её имени доходят до нас даже сквозь эту тысячелетнюю мглу. Её свершения во многом определили и наш сегодняшний день, и всё содержание нашей истории, которая – в том виде, в котором она дана нам,&#8239;&#8239;— была бы невозможна без её усилий по созданию Киевской державы, без осознанного ею выбора веры, без её путешествия в Царьград…».<p>&nbsp;</p><p>1)&#8239;&#8239;Царевна Софья<p>2)&#8239;&#8239;Софья Палеолог<p>3)&#8239;&#8239;Княгиня Ольга<p>4)&#8239;&#8239;Елена Глинская","sol":"<b>Пояснение. </b><p>В тексте речь идет о киевской княгине Ольге, которая совершила поездку в Константинополь (Царьград) и приняла христианство. Это во многом определило выбор ее внука, князя Владимира, в&#8239;988&#8239;году в пользу принятия христианства. Царевна Софья, Софья Палеолог, Елена Глинская правили уже в христианскую эпоху.<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3ПояснениеСпрятать пояснение &middot; Помощь","ans":"3"},{"id":845,"tp":6,"kind":"choice","type":"Тип Д4","body":"<p>Прочтите отрывок из произведения историка и определите, о каком русском князе идёт в нём речь:<p>&nbsp;</p><p>«Своей осторожной осмотрительной политикой он уберёг Русь от окончательного разорения ратями кочевников. Вооружённой борьбой, торговой политикой, избирательной дипломатией он избежал новых войн на Севере и на Западе, возможного, но гибельного для Руси союза с папством и сближения курии и крестоносцев с Ордой. Он выиграл время, дав Руси окрепнуть и оправиться от страшного разорения. Он&#8239;&#8239;— родоначальник политики московских князей, политики возрождения России. … Новгородский летописец, сообщив о кончине и похоронах князя, со сдержанной горечью сетует о человеке, «иже потрудися за Новгород, и за всю Русскую землю».<p>&nbsp;</p><p>1)&#8239;&#8239;Александр Невский<p>2)&#8239;&#8239;Иван Калита<p>3)&#8239;&#8239;Дмитрий Донской<p>4)&#8239;&#8239;Даниил Галицкий","sol":"<b>Пояснение. </b><p>В тексте речь идет о князе Александре Невском. Именно он проводил политику соглашения с Ордой и тем самым не допустил союза монголов и Запада против Руси. Его младший сын Даниил был первым московским князем. Московские князья были также продолжателями политического курса князя Александра Ярославича. Это дает право считать самого Александра Невского родоначальником политики московских князей.<p>&nbsp;</p><p>Правильный ответ указан под номером: 1.Ответ: 1ПояснениеСпрятать пояснение &middot; Помощь","ans":"1"},{"id":962,"tp":3,"kind":"choice","type":"Тип Д4","body":"<p>Прочтите отрывок из документа и укажите, о каком князе идёт речь. <p>&nbsp;</p><p>«Узнав о набеге печенегов, он спешил из Новгорода в южную Россию и сразился с варварами под стенами Киева... Князь одержал победу... В память сего знаменитого торжества Великий князь заложил на месте сражения великолепную церковь и, распространив Киев, обвёл его каменными стенами... он назвал их главные врата Золотыми, а новую церковь Святою Софией...»<p>&nbsp;</p><p>1)&#8239;&#8239;Александре Невском<p>2)&#8239;&#8239;Дмитрии Донском<p>3)&#8239;&#8239;Ярославе Мудром<p>4)&#8239;&#8239;Иване Калите","sol":"<b>Пояснение. </b><p>В 1036 году Великий киевский князь Ярослав Мудрый разбил печенегов у стен Киева. В честь этой победы были построены Софийский собор и Золотые ворота.<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3ПояснениеСпрятать пояснение &middot; Помощь","ans":"3"},{"id":1080,"tp":6,"kind":"choice","type":"Тип Д4","body":"<p>Прочтите отрывок из исторического источника и укажите событие, о котором идёт речь.<p>&nbsp;</p><p>«В полку великого князя Александра оказалось шесть мужей храбрых, которые вместе с ним мужественно сражались. Первый Гаврило Алексеич…ожесточенно бился среди полка шведов…»<p>&nbsp;</p><p>1)&#8239;&#8239;Ледовое побоище<p>2)&#8239;&#8239;Невская битва<p>3)&#8239;&#8239;Куликовская битва<p>4)&#8239;&#8239;битва на р. Калке","sol":"<b>Пояснение. </b><p>Речь идет о Невской битве, состоявщейся 15 июля 1240 года. Под предводительством новгородского князя Александра Ярославича были разгромлены шведы на реке Неве. Сохранилось предание о шести храбрых мужах&#8239;&#8239;— героях Невской битвы.<p>&nbsp;</p><p>Правильный ответ указан под номером: 2.Ответ: 2ПояснениеСпрятать пояснение &middot; Помощь","ans":"2"},{"id":1409,"tp":4,"kind":"choice","type":"Тип Д4","body":"<p>Прочтите отрывок из сочинения историка Б.&#8239;А.&#8239;Рыбакова и укажите век, к которому относятся описанные события.<p>&nbsp;</p><p>«\"И раздрася вся Русская земля...\"&#8239;&#8239;— записал в своей хронике один из летописцев... После смерти великого князя киевского Мстислава, сына Мономаха, все княжества Руси вышли из повиновения Киеву и начали жить самостоятельной жизнью. Но в ещё большей мере для наступления новой эпохи...характерны длительные кровопролитные усобицы князей, войны за расширение земельных владений, которые современник с горечью называл \"погибелью земли Русской\"...»<p>&nbsp;</p><p>1)&#8239;&#8239;X в.<p>2)&#8239;&#8239;XI в.<p>3)&#8239;&#8239;XII в.<p>4)&#8239;&#8239;XIV в.","sol":"<b>Пояснение. </b><p>В 30-е гг. XII в. после смерти Мстислава Великого (1125—1132&#8239;гг.) начался период раздробленности, произошел распад Древнерусского государства. <p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"3"},{"id":1448,"tp":2,"kind":"choice","type":"Тип Д4","body":"<p>Прочтите отрывок из «Повести временных лет» и укажите имя князя, с которым связаны описанные события.<p>&nbsp;</p><p>«В лето 971. ...И собрали греки против [князя] 100 тысяч (воинов) и не дали дани. И пошел князь на греков, а те вышли против Руси. Увидев это, Русь убоялась большого множества воинов. И сказал князь: \"Уже вам некуда деться, волей или неволей должны мы стать против, да не посрамим землю Русскую, но ляжем костьми здесь, мёртвые ведь позора не знают, если же побежим, то примем позор\"».<p>&nbsp;</p><p>1)&#8239;&#8239;Ярослав Мудрый<p>2)&#8239;&#8239;Святослав<p>3)&#8239;&#8239;Владимир Мономах<p>4)&#8239;&#8239;Игорь","sol":"<b>Пояснение. </b><p>Речь идет о киевском князе Святославе (964—972&#8239;гг.) и его походе на Балканы. Ему принадлежат слова «мертвые сраму не имут».<p>&nbsp;</p><p>Правильный ответ указан под номером: 2.Ответ: 2ПояснениеСпрятать пояснение &middot; Помощь","ans":"2"},{"id":2307,"tp":5,"kind":"choice","type":"Тип Д4","body":"<p>Прочтите отрывок из древнерусской летописи и укажите событие, о котором в нём говорится.<p>&nbsp;</p><p>«Уже в исходе февраля к великому князю Юрию Всеволодовичу, его брату Святославу Всеволодовичу, племянникам&#8239;&#8239;— Васильку Константиновичу, Всеволоду Константиновичу и Владимиру Константиновичу&#8239;&#8239;— пришёл вестник с известием, что город Владимир взят, епископ, великая княгиня, князья и все люди сожжены, а некоторые перебиты. «А твоего старшего сына Всеволода с братьями убили вне города и идут к тебе»... Юрий ждал своего брата Ярослава, и не было его. И князь приказал своему воеводе укреплять людей и готовиться к бою... Сошлись полки, и была крупная битва и злая сеча; кровь лилась, как вода. Божьим попущением татары победили русских князей. Был убит тогда великий князь Владимирский Юрий Всеволодович и многие его воеводы и бояре, и было перебито воинство его».<p>&nbsp;</p><p>1.&#8239;&#8239;Битка на р. Калке.<p>2.&#8239;&#8239;Битва на р. Сити.<p>3.&#8239;&#8239;Битва на р. Неве.<p>4.&#8239;&#8239;Битва на р. Воже.","sol":"<b>Пояснение. </b><p>Великий князь Владимирский Юрий Всеволодович погиб в сражении с монголами на р. Сить 4 марта 1238&#8239;г. Об этом говорится в тексте.<p>&nbsp;</p><p>Правильный ответ указан под номером: 2.Ответ: 2ПояснениеСпрятать пояснение &middot; Помощь","ans":"2"},{"id":3389,"tp":4,"kind":"multi","type":"Тип Д4","body":"<p>Прочтите отрывок из «Повести временных лет» и назовите князя, о котором идёт речь.<p>&nbsp;</p><p>«...заложил же и церковь святой Софии, митрополию и затем церковь на Золотых воротах... И стала при нём вера христианская расширяться, и черноризцы стали умножаться, и монастыри стали появляться... Отец его, Владимир, землю вспахал и размягчил, то есть крещением просветил, [сын] же засеял книжными словами сердца верных людей, а мы пожинаем, ученье принимая книжное.<p>...Ещё при жизни дал он наставление сыновьям своим: \"И если будете жить в любви между собою, Бог будет в вас и покорит вам врагов...\" И так разделил он между ними города, запретив им переступать пределы братьев и сгонять со стола».<p>&nbsp;</p><p>1)&#8239;&#8239;Андрей Боголюбский<p>2)&#8239;&#8239;Игорь Святославич<p>3)&#8239;&#8239;Ярослав Мудрый<p>4)&#8239;&#8239;Святослав Игоревич","sol":"<b>Пояснение. </b><p>В отрывке идет речь о сыне Владимира Красное Солнышко князе Ярославе Мудром.<p>&nbsp;</p><p>Правильный ответ указан под номером: 3.Ответ: 3Источник: ЕГЭ по истории 30.05.2013. Основная волна. Центр. Вариант 2ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"3"},{"id":3429,"tp":2,"kind":"choice","type":"Тип Д4","body":"<p>Прочтите отрывок из сочинения историка и назовите князя, о котором идёт речь.<p>&nbsp;</p><p>«Ещё при жизни матери, оставив на попечении Ольги Киевское княжество, [князь] совершил первые свои блестящие походы. Он пошёл на Оку и подчинил вятичей, которые тогда платили дань хазарам; затем обратился на хазар и разгромил Хазарское царство, взяв главные города хазар... Наконец, [князь] проник на Волгу, разорил землю камских болгар и взял их город Болгар. Словом, [он] победил и разорил всех восточных соседей Руси, входивших в систему Хазарской державы. Главной силой в Причерноморье становилась теперь Русь».<p>&nbsp;</p><p>1)&#8239;&#8239;Владимир<p>2)&#8239;&#8239;Святослав<p>3)&#8239;&#8239;Олег<p>4)&#8239;&#8239;Рюрик","sol":"<b>Пояснение. </b><p>Князь Святослав, сын Ольги и Игоря прославился как выдающийся полководец, он покорил вятичей, разгромил волжских болгар и Хазарский каганат.<p>&nbsp;</p><p>Правильный ответ указан под номером: 2.Ответ: 2Источник: ЕГЭ по истории 30.05.2013. Основная волна. Центр. Вариант 3ПояснениеСпрятать пояснение &middot; Помощь","ans":"2"},{"id":3509,"tp":5,"kind":"choice","type":"Тип Д4","body":"<p>Прочтите отрывок из сочинения современного историка и укажите имя хана, о походе которого идёт речь.<p>&nbsp;</p><p>«Дав своему войску возможность собраться с силами в степях Северного Причерноморья и Поволжья и получив подкрепление с востока, [он] продолжил поход на запад. Были уничтожены Чернигов и Переяславль, ... пал после осады Киев... Затем [он] огнём и мечом прошёлся по Галицко-Волынской земле, разгромил Венгрию, Польшу, Хорватию. Было побеждено войско рыцарей, посланных навстречу монголам императором Германии».<p>&nbsp;</p><p>1)&#8239;&#8239;Тимур<p>2)&#8239;&#8239;Чингисхан<p>3)&#8239;&#8239;Мамай<p>4)&#8239;&#8239;Батый","sol":"<b>Пояснение. </b><p>Речь идет о походе хана Батыя в 1240−1242&#8239;гг. Мамай, Чингис-хан и Тимур в Европу не вторгались.<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4Источник: ЕГЭ по истории 30.05.2013. Основная волна. Центр. Вариант 5ПояснениеСпрятать пояснение &middot; Помощь","ans":"4"},{"id":3629,"tp":2,"kind":"choice","type":"Тип Д4","body":"<p>Прочтите отрывок из «Повести временных лет» и назовите киевского князя, о котором идёт речь.<p>&nbsp;</p><p>«Древляне же, услышав, что идёт [князь] снова, держали совет с князем своим Малом: \"Если повадится волк к овцам, то вынесет всё стадо, пока не убьют его; так и этот: если не убьём его, то всех нас погубит\". И послали к нему, говоря: \"Зачем идёшь опять? Забрал уже всю дань\". И не послушал их [князь]; и древляне, выйдя из города Искоростеня, убили [князя] и всю дружину его, так как было её мало. И погребён был [князь], и есть могила его у Искоростеня в Деревской земле и до сего времени».<p>&nbsp;</p><p>1)&#8239;&#8239;Олег<p>2)&#8239;&#8239;Святослав<p>3)&#8239;&#8239;Рюрик<p>4)&#8239;&#8239;Игорь","sol":"<b>Пояснение. </b><p>В 945&#8239;г. древлянами был убит князь Игорь за попытку собрать дань два раза.<p>&nbsp;</p><p>Правильный ответ указан под номером: 4.Ответ: 4Источник: ЕГЭ по истории 30.05.2013. Основная волна. Дальний Восток. Вариант 2ПояснениеСпрятать пояснение &middot; Помощь","ans":"4"},{"id":3749,"tp":4,"kind":"choice","type":"Тип Д4","body":"<p>Прочтите отрывок из сочинения историка и назовите князя, о котором идёт речь.<p>&nbsp;</p><p>«...затратил большие средства на украшение своей столицы, взяв за образец столицу Византии Царьград. В Киеве... строятся Золотые Ворота, грандиозный Софийский собор... При нём переписывались многие книги, много переводилось с греческого языка на русский... киевский князь, с которым стремились породниться королевские дома Франции, Венгрии, Норвегии...»<p>&nbsp;</p><p>1)&#8239;&#8239;Ярослав Мудрый<p>2)&#8239;&#8239;Андрей Боголюбский<p>3)&#8239;&#8239;Дмитрий Донской<p>4)&#8239;&#8239;Святослав Игоревич","sol":"<b>Пояснение. </b><p>При Ярославе  Мудром был построен Софийский  собор и Золотые ворота  в Киеве, заключен ряд династических  браков членов его семьи, большое внимание уделялось просвещению.<p>&nbsp;</p><p>Правильный ответ указан под номером: 1.Ответ: 1Источник: ЕГЭ по истории 30.05.2013. Основная волна. Дальний Восток. Вариант 5ПояснениеСпрятать пояснение &middot; Помощь","ans":"1"},{"id":3829,"tp":2,"kind":"choice","type":"Тип Д4","body":"<p>Прочтите отрывок из сочинения историка и назовите князя, о котором идёт речь.<p>&nbsp;</p><p>«[Князь] собрал вокруг себя беспредельно преданную дружину из пришлых варягов, местных славян и кочевых торков и отдался далёким предприятиям: в походах он делил с простыми воинами все опасности и лишения, не возил с собой ни запасов, ни котлов, обходился без шатров, спал на голой земле, подложив под голову седло, и т.&#8239;п. Прежде всего он двинулся через низовье Дона на хазар, разрушил построенную византийцами крепость Саркел, разграбил хазарскую столицу Итиль и хазарский торговый город Семендар... Походы [князя] вконец расстроили Хазарское царство, хазары уже более не могли подняться, их место в степях заняли более дикие печенеги».<p>&nbsp;</p><p>1)&#8239;&#8239;Святослав<p>2)&#8239;&#8239;Рюрик<p>3)&#8239;&#8239;Владимир<p>4)&#8239;&#8239;Игорь","sol":"<b>Пояснение. </b><p>Святосла́в И́горевич (Свѧтославъ Игоревичь, 942&#8239;&#8239;— март 972)&#8239;&#8239;— князь новгородский в 945—969 годах, великий князь киевский с 945&#8239;по 972 год, прославился как полководец. Разбил Волжскую Булгарию и Хазарский каганат.<p>&nbsp;</p><p>Правильный ответ указан под номером: 1.Ответ: 1Источник: ЕГЭ по истории 30.05.2013. Основная волна. Сибирь. Вариант 1ПояснениеСпрятать пояснение &middot; Помощь","ans":"1"},{"id":4458,"tp":5,"kind":"choice","type":"Тип Д4","body":"<p>Прочтите отрывок из сочинения историка и укажите название города, о котором идёт речь.<p>&nbsp;</p><p>«Ни в каком другом краю Древней Руси не встретим такого счастливого подбора условий, благоприятных для широкого развития политической жизни. [Город] рано освободился от давления княжеской власти и стал в стороне от княжеских усобиц и половецких разбоев, не испытал непосредственного гнета и страха татарского, в глаза не видал ордынского баскака, был экономическим и политическим центром громадной промышленной области, рано вступил в деятельные торговые сношения и мог вступить в тесные культурные связи с европейским Западом, был несколько веков торговым посредником между этим Западом и азиатским Востоком. Дух свободы и предприимчивости, политическое сознание \"мужей вольных\"<...>&#8239;&#8239;— нигде более в Древней Руси не соединялось столько материальных и духовных средств, чтобы воспитать в обществе эти качества, необходимые для устроения крепкого и справедливого общественного порядка...».<p>&nbsp;</p><p>1)&#8239;&#8239;Новгород<p>2)&#8239;&#8239;Москва<p>3)&#8239;&#8239;Киев<p>4)&#8239;&#8239;Владимир","sol":"<b>Пояснение. </b><p>В документе речь идет о Новгороде. Доказательства: рано освободился от давления княжеской власти, стоял в стороне от половецких набегов и княжеских усобиц, посредник в торговле между Западом и Востоком.<p>&nbsp;</p><p>Правильный ответ указан под номером: 1.Ответ: 1ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"1"},{"id":5555,"tp":3,"kind":"choice","type":"Тип Д4","body":"<p>Прочтите отрывок из «Повести временных лет» и определите год, пропущенный в тексте.<p>«В __________ году пришли Святополк, Владимир, Давыд Игоревич, Василько Ростилавич и брат его Олег и съехались в Любече для установления мира, говоря между собой: «Зачем мы губим русскую землю, учиняя распри между собою? А половцы нашу землю разоряют и рады, что между нами междоусобия. С этих пор будем все единодушны и храним землю русскую, пусть каждый держит отчину свою…».<p>&nbsp;</p><p>1)&#8239;&#8239;988&#8239;г.<p>2)&#8239;&#8239;1054&#8239;г.<p>3)&#8239;&#8239;1097&#8239;г.<p>4)&#8239;&#8239;1125&#8239;г.","sol":"<b>Пояснение. </b><p>Речь идет о съезде князей в Любече в 1097г.<p>Правильный ответ: 3Ответ: 3ПояснениеСпрятать пояснение &middot; Помощь","ans":"3"},{"id":5675,"tp":5,"kind":"choice","type":"Тип Д4","body":"<p>Прочтите отрывок из летописи и укажите век, когда произошли описанные события.<p>&nbsp;</p><p>«Пришла весть к великому князю Юрию: “Владимир взят, соборная церковь вместе с епископом, княгиней с детьми и снохами и внуками погибла в огне, старейшие сыновья Всеволод с братом убиты вне города, люди перебиты, а на тебя идут”. Он же, услышав об этом, закричал громко, со слезами, плача прежде всего по православной вере<p>христианской, и более всего о церкви и о епископе, и о людях, ибо был милостив, нежели о себе и жене и детях... И так он молился со слезами, когда внезапно появились [враги]. И пришли [они] на реку Сить против великого князя Юрия».<p>&nbsp;</p><p>1)&#8239;&#8239;X в. <p>2)&#8239;&#8239;XI в. <p>3)&#8239;&#8239;XII в.<p>4)&#8239;&#8239;XIII в.","sol":"<b>Пояснение. </b><p>В 1238г состоялась битва на реке Сить в которой войска Батыя разбили войско Юрия Всеволодовича, владимирского князя. Ответ: 4.Ответ: 4ПояснениеСпрятать пояснение &middot; Помощь","ans":"4"},{"id":6031,"tp":5,"kind":"choice","type":"Тип Д4","body":"<p>Прочтите отрывок из Повести и укажите десятилетие, когда произошли описанные события.<p>&nbsp;</p><p>«И некий из вельмож рязанских по имени Евпатий Коловрат был в то время в Чернигове с князем Ингварем Ингваревичем, и услышал о нашествии царя Батыя, и выступил из Чернигова с малою дружиною, и помчался быстро. И приехал в землю Рязанскую и увидел её опустевшую, города разорены,<p>церкви пожжены, люди убиты. И помчался во град Рязань и увидел город разорён, государей убитых и множество народа полегшего: одни убиты и посечены, другие пожжены, а иные в реке потоплены. И воскричал Евпатий в горести души своей, распаляяся в сердце своём. И собрал небольшую дружину – тысячу семьсот человек, которых Бог соблюл вне города. И погнались вослед безбожного царя, и едва нагнали его в земле Суздальской, и внезапно напали на станы Батыевы».<p>&nbsp;</p><p>1)&#8239;&#8239;1220-е гг. <p>2)&#8239;&#8239;1230-е гг. <p>3)&#8239;&#8239;1240-е гг. <p>4)&#8239;&#8239;1250-е гг.","sol":"<b>Пояснение. </b><p>Речь идет о подвиге Евпатия Коловрата. Правильный ответ: 2Ответ: 2ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"2"},{"id":250,"tp":2,"kind":"open","type":"Тип 13","body":"<p><b>Прочтите отрывок из исторического источника и кратко ответьте на вопрос(-&#8288;ы). Ответы предполагают использование информации из источника, а также применение исторических знаний по курсу истории соответствующего периода.</b><p>&nbsp;</p><p>Из исторического очерка:<p>&nbsp;</p><p>«В год 6370 изгнали варягов за море, и не дали им дани, и начали сами собой владеть, и не было среди них правды, и встал род на род, и была у них усобица, и стали воевать друг с другом. И сказали себе: «Поищем себе князя, который бы владел нами и судил по праву». И пошли за море к варягам, к руси... Сказали руси чудь, словене, кривичи и весь: «Земля наша велика и обильна, а порядка в ней нет. Приходите княжить и владеть нами». И избрались трое братьев со своими родами, и взяли с собой всю русь, и пришли, и сел старший, Рюрик, в Новгороде, а другой, Синеус,&#8239;&#8239;— на Белоозере, а третий, Трувор,&#8239;&#8239;— в Изборске. И от тех варягов прозвалась Русская земля».<p>Приведите название документа и имя его автора. К какому времени относится создание этого документа?","sol":"<b>Пояснение. </b><p>Автором летописи «Повесть временных лет» является монах Киево-Печерского монастыря Нестор в начале XII&#8239;века.<b>Критерии проверки:</b><p>   <table>       <tr> <th>Критерии оценивания ответа на задание С1</th>  <th>Баллы</th> </tr>  <tr> <td> Указаны десятилетие, руководитель страны, название периода </td> <td>2</td> </tr>  <tr> <td> Указаны любые два элемента </td> <td>1</td> </tr>   <tr> <td> Указан один любой элемент. ИЛИ Ответ неправильный </td> <td>0</td> </tr>    <tr> <td>Максимальное количество баллов</td> <td>2</td> </tr>  </table> ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; \n                    2 комментария\n                     &middot; Помощь1Тип 14&nbsp;№&nbsp;251 <img src=\"img/ege/sd_hist_ege_sdamgia_ru_img_briefcase_plus_png.png\" loading=\"lazy\"><img src=\"img/ege/sd_hist_ege_sdamgia_ru_img_exclamation_white_png.png\" loading=\"lazy\">Раздел кодификатора ФИПИ/Решу ЕГЭ: 1.2.1 Возникновение государственности у восточных славян. Князья и дружина Поиск исторической информации. VIII - XVII векаi <p>О каком событии идёт речь в документе? Что послужило его причинами? Укажите не менее двух причин.<p></p><b>Пояснение. </b><p>1.&#8239;&#8239;Речь идет о призвании варягов на Русь. <p>2.&#8239;&#8239;Причины призвания варягов на Русь заключались в том, что:<p>—&#8239;&#8239;«род встал на род»; <p>—&#8239;&#8239;отсутствие правды.<b>Критерии проверки:</b><p>   <table>       <tr> <th>Критерии оценивания ответа на задание С2</th>  <th>Баллы</th> </tr>  <tr> <td> Правильно указаны ответы на два вопроса </td> <td>2</td> </tr>  <tr> <td> Правильно указан ответ на один вопрос </td> <td>1</td> </tr>   <tr> <td> Ответ неправильный или неполный</td> <td>0</td> </tr>    <tr> <td>Максимальное количество баллов</td> <td>2</td> </tr>  </table> ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь\n2Тип Д22 C2&nbsp;№&nbsp;252 <img src=\"img/ege/sd_hist_ege_sdamgia_ru_img_briefcase_plus_png.png\" loading=\"lazy\"><img src=\"img/ege/sd_hist_ege_sdamgia_ru_img_exclamation_white_png.png\" loading=\"lazy\"> Анализ исторического источника. VIII - XVII векаi <p>Каковы были последствия описанного в документе события? (Укажите не менее двух последствий.)<p></p><b>Пояснение. </b><p>— призвание Рюрика считается началом русской государственности; <p>— Рюрик положил начало династии русских князей Рюриковичей;<p>— начало процесса объединения восточно-славянских племен и т.&#8239;д.<b>Критерии проверки:</b><p>   <table>       <tr> <th>Критерии оценивания ответа на задание С3</th>  <th>Баллы</th> </tr>   <tr> <td> Сформулирован итог, указаны две причины </td> <td>2</td> </tr>   <tr> <td> Сформулирован итог, указана одна причина </td> <td>1</td> </tr>   <tr> <td> Только сформулирован итог. ИЛИ ТОлько указаны 1&mdash;2 причины.<br> ИЛИ Ответ неправильный </td> <td>0</td> </tr>    <tr> <td>Максимальное количество баллов</td> <td>2</td> </tr>  </table> ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь","ans":""},{"id":1188,"tp":4,"kind":"open","type":"Тип 13","body":"<p><b>Прочтите отрывок из исторического документа и кратко ответьте на вопрос(-&#8288;ы). Ответы предполагают использование информации из источника, а также применение исторических знаний по курсу истории соответствующего периода.</b><p>&nbsp;</p><p>Из сочинения историка В.&#8239;О.&#8239;Ключевского:<p>&nbsp;</p><p>«С половины XII&#8239;в. становятся заметны признаки запустения Киевской Руси. Речная полоса по среднему Днестру с притоками, издавна так хорошо заселённая, с этого времени пустеет, население ее исчезает куда-то. <...> В числе семи запустелых городов Черниговской земли мы встречаем один из самых старинных и богатых городов Поднепровья&#8239;&#8239;— Любеч. Одновременно с признаками отлива населения из Киевской Руси замечаем и следы упадка её экономического благосостояния: Русь, пустея, вместе с тем и беднела. <...> Отлив населения из Поднепровья шёл в двух направлениях, двумя противоположными струями. Одна струя направлялась на запад, на Западный Буг, в область верхнего Днестра и верхней Вислы, в глубь Галиции и Польши. Так южнорусское население из Поднепровья возвращалось на давно забытые места, покинутые его предками. Другая струя колонизации из Приднепровья направляется в противоположный угол Русской земли, на северо-восток, за реку Угру, в междуречье Оки и Верхней Волги. <...> Она&#8239;&#8239;— источник всех основных явлений, обнаружившихся в жизни верхневолжской Руси с половины XII&#8239;в.; из последствий этой колонизации сложился весь политический и общественный быт этой Руси».<p>Как назывался период в истории России, о котором идёт речь в документе? Укажите его хронологические рамки.","sol":"<b>Пояснение. </b><p>1.&#8239;&#8239;Название периода: политическая раздробленность (или: феодальная раздробленность, государственная раздробленность, Русь удельная).<p>2.&#8239;&#8239;Хронологические рамки: середина XII&#8239;в. (или 30-&#8288;е&#8239;гг. XII&#8239;в.)&#8239;&#8239;— XV&#8239;в. (начало XVI&#8239;в.).<b>Критерии проверки:</b><p><table><tr><th>Критерии оценивания выполнения задания</th><th>Баллы</th></tr><tr><td>Указаны все элементы ответа.</td><td>2</td></tr><tr><td>Указаны любые два элемента.</td><td>1</td></tr><tr><td>Указан один любой элемент. ИЛИ Ответ неправильный.</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>2</td></tr></table>ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; \n                    2 комментария\n                     &middot; Помощь1Тип 14&nbsp;№&nbsp;1189 <img src=\"img/ege/sd_hist_ege_sdamgia_ru_img_briefcase_plus_png.png\" loading=\"lazy\"><img src=\"img/ege/sd_hist_ege_sdamgia_ru_img_exclamation_white_png.png\" loading=\"lazy\">Раздел кодификатора ФИПИ/Решу ЕГЭ: 1.3.1 Причины распада Древнерусского государства. Крупнейшие земли и княжества Поиск исторической информации. VIII - XVII векаi <p>О каких явлениях, характерных для данного периода, свидетельствует документ? Назовите не менее двух явлений. Используя текст документа и знания по истории, укажите причины этих явлений (не менее двух причин).<p></p><b>Пояснение. </b><p>1.&#8239;&#8239;Могут быть названы такие явления, как:<p>—&#8239;&#8239;отток населения из Киевской Руси;<p>—&#8239;&#8239;запустение городов Киевской Руси;<p>—&#8239;&#8239;колонизация северо-западных и северо-восточных русских земель.<p>2.&#8239;&#8239;Могут быть названы причины этих явлений:<p>—&#8239;&#8239;потеря Киевом своей исторической роли вследствие перемещения основных торговых путей;<p>—&#8239;&#8239;падение роли «пути из варяг в греки»;<p>—&#8239;&#8239;постоянные междоусобицы, вызванные борьбой за «киевский стол»;<p>—&#8239;&#8239;набеги кочевников, ослаблявшие Киевскую землю.<b>Критерии проверки:</b><p><table><tr><th>Критерии оценивания выполнения задания</th><th>Баллы</th></tr><tr><td>Названы явления, указаны две причины.</td><td>2</td></tr><tr><td>Названы явления, указана одна причина.</td><td>1</td></tr><tr><td>Только названы явления.<p> ИЛИ Указаны только 1-2 причины.<p> ИЛИ Ответ неправильный.<p></td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>2</td></tr></table>ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь\n2Тип Д22 C2&nbsp;№&nbsp;1190 <img src=\"img/ege/sd_hist_ege_sdamgia_ru_img_briefcase_plus_png.png\" loading=\"lazy\"><img src=\"img/ege/sd_hist_ege_sdamgia_ru_img_exclamation_white_png.png\" loading=\"lazy\"> Анализ исторического источника. VIII - XVII векаi <p>Как оценивает историк последствия отмеченных в документе явлений? Назовите не менее двух последствий усиления верхневолжской Руси в дальнейшей российской истории.<p></p><b>Пояснение. </b><p>1.&#8239;&#8239;Может быть приведена следующая оценка:<p>— усиление и возвышение Северо-Восточной Руси;<p>— политический и общественный быт Северо-Восточной Руси во многом был обусловлен притоком населения из Киевской Руси.<p>2.&#8239;&#8239;Указаны последствия усиления верхневолжской Руси:<p>— Северо-Восточная Русь стала в дальнейшем центром объединения всех русских земель;<p>— политический институт власти Северо-Восточной Руси (сильная княжеская власть) распространится на все Русское государство.<p><b>Критерии проверки:</b><p><table><tr><th>Критерии оценивания выполнения задания</th><th>Баллы</th></tr><tr><td>Приведена оценка и указаны последствия верхневолжской Руси.</td><td>2</td></tr><tr><td>Приведена оценка и указано одно последствие.</td><td>1</td></tr><tr><td>Только названа оценка.<p>ИЛИ Только указаны 1-2 последствия.<p>ИЛИ Ответ неправильный.<p></td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>2</td></tr></table>ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь","ans":""},{"id":2374,"tp":4,"kind":"open","type":"Тип 13","body":"<p>Из сочинения историка:<p>&nbsp;</p><p>«От всей фигуры [князя] веет чем-&#8288;то новым; но едва ли эта новизна была добрая. Князь был суровый и своенравный хозяин, который во всём поступал по-&#8288;своему, а не по старине и обычаю. Современники заметили в нём эту двойственность, смесь силы со слабостью, власти с капризом. «Такой умник во всех делах,&#8239;&#8239;— говорит о нём летописец,&#8239;&#8239;— такой доблестный, князь погубил свой смысл невоздержанием», т.&#8239;е. недостатком самообладания. Проявив в молодости на юге столько боевой доблести и политической рассудительности, он потом, живя сиднем в своём Боголюбове, наделал немало дурных дел: собирал и посылал большие рати грабить то Киев, то Новгород, раскидывал паутину властолюбивых козней по всей Русской земле из своего тёмного угла на Клязьме...<p>Прогнав из Ростовской земли больших отцовых бояр, он окружил себя такой дворней, которая в благодарность за его барские милости отвратительно его убила и разграбила его дворец. Он был очень набожен и нищелюбив, настроил много церквей в своей области, перед заутреней сам зажигал свечи в храме, как заботливый церковный староста, велел развозить по улицам пищу и питьё для больных и нищих, отечески нежно любил свой город... хотел сделать из него другой Киев, даже с особым, вторым русским митрополитом, построил в нём известные Золотые Ворота. Со времени своего побега из Вышгорода в 1155&#8239;г. в продолжение почти 20-летнего безвыездного сидения в своей волости устроил в ней такую администрацию, что тотчас по смерти его там наступила полная анархия: всюду происходили грабежи и убийства, избивали посадников, тиунов и других княжеских чиновников, и летописец с прискорбием упрекает убийц и грабителей, что они делали свои дела напрасно, потому что где закон, там и «обид», несправедливостей много. Никогда ещё на Руси ни одна княжеская смерть не сопровождалась такими постыдными явлениями. Их источника надобно искать в дурном окружении, какое создал себе князь своим произволом, неразборчивостью к людям, пренебрежением к обычаям и преданиям. В заговоре против него участвовала даже его вторая жена, родом из камской Болгарии, мстившая ему за зло, какое причинил [князь] её родине. Летопись глухо намекает, как плохо слажено было общество, в котором вращался. «Ненавидели князя свои домашние,&#8239;&#8239;— говорит она,&#8239;&#8239;— и была брань лютая в Ростовской и Суздальской земле».<p>Современники готовы были видеть в [князе] проводника новых государственных стремлений. В лице князя великоросс впервые выступал на историческую сцену, и это выступление нельзя признать удачным».<p>Укажите название периода русской истории, в который происходили описанные события. Назовите имя князя, о котором в нём говорится. К какому веку относится правление этого князя?","sol":"<b>Пояснение. </b><p>1.&#8239;&#8239;Период раздробленности (удельная Русь).<p>2.&#8239;&#8239;Князь Андрей Боголюбский.<p>3.&#8239;&#8239;XII&#8239;век.<b>Критерии проверки:</b><p><table><tr><th>Критерии оценивания выполнения задания</th><th>Баллы</th></tr><tr><td>Указаны все элементы ответа</td><td>2</td></tr><tr><td>Указаны любые два элемента</td><td>1</td></tr><tr><td>Указан один любой элемент. ИЛИ Ответ неправильный</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>2</td></tr></table>ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь1Тип 14&nbsp;№&nbsp;2375 <img src=\"img/ege/sd_hist_ege_sdamgia_ru_img_briefcase_plus_png.png\" loading=\"lazy\"><img src=\"img/ege/sd_hist_ege_sdamgia_ru_img_exclamation_white_png.png\" loading=\"lazy\">Раздел кодификатора ФИПИ/Решу ЕГЭ: 1.3.1 Причины распада Древнерусского государства. Крупнейшие земли и княжества Поиск исторической информации. VIII - XVII векаi <p>О каких новых государственных устремлениях князя говорит автор? Укажите три элемента.<p></p><b>Пояснение. </b><p>Могут быть указаны следующие элементы. <p>1.&#8239;&#8239;Стремление установить сильную княжескую власть.<p>2.&#8239;&#8239;Резиденцией князя стало Боголюбово, а не Киев.<p>3.&#8239;&#8239;Впервые установил подданические отношения по отношениюк своим слугам.<p>4.&#8239;&#8239;Пренебрегал старыми обычаями и традициями.<p><i>Могут быть указаны другие элементы.</i><b>Критерии проверки:</b><p>   <table>       <tr> <th>Критерии оценивания ответа на задание С2</th>  <th>Баллы</th> </tr>  <tr> <td> Правильно указаны 3 направления </td> <td>2</td> </tr>  <tr> <td> Правильно указаны 2 направления </td> <td>1</td> </tr>   <tr> <td> Правильно указано 1 направление<p> ИЛИ<p> Ответ неправильный </td> <td>0</td> </tr>    <tr> <td>Максимальное количество баллов</td> <td>2</td> </tr>  </table> ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь\n2Тип Д22 C2&nbsp;№&nbsp;2376 <img src=\"img/ege/sd_hist_ege_sdamgia_ru_img_briefcase_plus_png.png\" loading=\"lazy\"><img src=\"img/ege/sd_hist_ege_sdamgia_ru_img_exclamation_white_png.png\" loading=\"lazy\"> Анализ исторического источника. VIII - XVII векаi <p>Как характеризуется князь в документе? Каков итог его правления? Назовите 2 любые причины такого итога правления.<p></p><b>Пояснение. </b><p>1.&#8239;&#8239;Оценка князя в документе противоречивая:<p>—&#8239;&#8239;был набожен, построил много церквей, помогал нищим, доблестный воин;<p>—&#8239;&#8239;совершал разорительный походы по Руси (в Киев, Новгород).<p>&nbsp;</p><p>2.&#8239;&#8239;Причины, например:<p>—&#8239;&#8239;заговор против князя, в котором участвовали и члены семьи;<p>—&#8239;&#8239;неготовность общества к введенным им служебно-подданическим отношениям;<p>—&#8239;&#8239;произвол княжеской власти;<p>—&#8239;&#8239;неразборчивое отношение к своим слугам;<p>—&#8239;&#8239;нежелание следовать обычаям княжеского правления.<b>Критерии проверки:</b><p>   <table>       <tr> <th>Критерии оценивания ответа на задание С3</th>  <th>Баллы</th> </tr>   <tr> <td> Сформулирован итог, указаны две причины </td> <td>2</td> </tr>   <tr> <td> Сформулирован итог, указана одна причина </td> <td>1</td> </tr>   <tr> <td> Только сформулирован итог. ИЛИ ТОлько указаны 1&mdash;2 причины.<br> ИЛИ Ответ неправильный </td> <td>0</td> </tr>    <tr> <td>Максимальное количество баллов</td> <td>2</td> </tr>  </table> ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь","ans":""},{"id":4528,"tp":3,"kind":"open","type":"Тип 13","body":"<p>«[Князь] беспрепятственно спустился из Новгорода По Днепру, без особенного труда захватил по дороге Смоленск и Любеч и без борьбы завладел Киевом, погубивши своих земляков Аскольда с Диром. Утвердившись в Киеве, он начал рубить вокруг него новые города для Защиты киевской земли от набегов из степи, а йогом с соединёнными силами разных племён предпринял новый поход на Царьград, кончившийся также заключением торгового договора [Князя]. <...> Дружно поддерживали в этих походах все племена, заинтересованные во внешней торговле, преимущественно обитавшие по речной линии Днепра&#8239;&#8239;— Волхова, т.&#8239;е. обыватели больших торговых городов Руси, По крайней мере в летописном рассказе о походе [князя] читаем, что кроме подвластных [ему] племён в деле участвовали и племена неподвластные, добровольно к нему присоединившиеся, отдалённые дулебы и хорваты, жившие в области Верхнего Днестра и обоих Бугов, по северо-восточным склонам и предгорьям Карпат. Охрана страны от степных кочевников и далёкие военные походы на Царьград для поддержания торговых сношений, очевидно, вызывали общее и дружное содействие. <...> Этот общий интерес и соединил прибрежные торговые города под властью [князя] киевского, руководителя в этом деле по положению, какое создавалось для него... значением Киева».<p>О каком князе идёт речь? Укажите время его правления.","sol":"<b>Пояснение. </b><p>Может быть указано, что. <p>1.&#8239;&#8239;Речь идёт о князе Олеге (Вещем).<p>2.&#8239;&#8239;Время его правления&#8239;&#8239;— конец IX&#8239;&#8239;— начало X&#8239;в. (879−912&#8239;гг., могут быть указаны и 882−912&#8239;гг.&#8239;&#8239;— время киевского княжения).\nИсточник/автор: Соловьёв Я. В. (Москва)<b>Критерии проверки:</b><p><table><tr><th>Критерии оценивания выполнения задания</th><th>Баллы</th></tr><tr><td>Указаны десятилетие, руководитель страны, название периода</td><td>2</td></tr><tr><td>Указаны любые два элемента</td><td>1</td></tr><tr><td>Указан один любой элемент<p> ИЛИ<p> Ответ неправильный</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>2</td></tr></table>\nИсточник/автор: Соловьёв Я. В. (Москва)ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь1Тип 14&nbsp;№&nbsp;4529 <img src=\"img/ege/sd_hist_ege_sdamgia_ru_img_briefcase_plus_png.png\" loading=\"lazy\"><img src=\"img/ege/sd_hist_ege_sdamgia_ru_img_exclamation_white_png.png\" loading=\"lazy\">Раздел кодификатора ФИПИ/Решу ЕГЭ: 1.2.1 Возникновение государственности у восточных славян. Князья и дружина\nИсточник/автор: Соловьёв Я. В. (Москва) Поиск исторической информации. VIII - XVII векаi <p>На основе текста укажите не менее трёх задач, решаемых данным князем в годы его правления.<p></p><b>Пояснение. </b><p>Могут быть указаны следующие задачи.<p>1.&#8239;&#8239;Объединение Новгорода и Киева.<p>2.&#8239;&#8239;Установление контроля над всем путём «из варяг в греки».<p>3.&#8239;&#8239;Заключение выгодных для Руси торговых договоров с Византией.<p>4.&#8239;&#8239;Подчинение восточнославянских союзов, принуждение их платить дань.<p>5.&#8239;&#8239;Оборона от кочевых племён. <p><i>Могут быть названы и другие задачи.</i>\nИсточник/автор: Соловьёв Я. В. (Москва)<b>Критерии проверки:</b><p><table><tr><th>Критерии оценивания выполнения задания</th><th>Баллы</th></tr><tr><td>Правильно указаны три направления</td><td>2</td></tr><tr><td>Правильно указаны два направления</td><td>1</td></tr><tr><td>Правильно указано одно направление<p> ИЛИ<p> Ответ неправильный</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>2</td></tr></table>\nИсточник/автор: Соловьёв Я. В. (Москва)ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь\n2Тип Д22 C2&nbsp;№&nbsp;4530 <img src=\"img/ege/sd_hist_ege_sdamgia_ru_img_briefcase_plus_png.png\" loading=\"lazy\"><img src=\"img/ege/sd_hist_ege_sdamgia_ru_img_exclamation_white_png.png\" loading=\"lazy\">\nИсточник/автор: Соловьёв Я. В. (Москва) Анализ исторического источника. VIII - XVII векаi <p>Как историк объясняет причины, по которым князь получил содействие в своей политике не только подвластных ему, но и других восточнославянских племён? Приведите не менее двух положений.<p></p><b>Пояснение. </b><p>Могут быть даны следующие объяснения: восточнославянские союзы были заинтересованы в<p>-\tсовместной борьбе с кочевниками;<p>-\tвоенной добыче;<p>-\tустановлении выгодных торговых договоров с Византией\nИсточник/автор: Соловьёв Я. В. (Москва)<b>Критерии проверки:</b><p><table><tr><th>Критерии оценивания выполнения задания</th><th>Баллы</th></tr><tr><td>Сформулирован итог, указаны две причины</td><td>2</td></tr><tr><td>Сформулирован итог, указана одна причина</td><td>1</td></tr><tr><td>Только сформулирован итог. ИЛИ Только указаны одна-две причины. ИЛИ Ответ неправильный</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>2</td></tr></table>\nИсточник/автор: Соловьёв Я. В. (Москва)ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь","ans":""},{"id":57127,"tp":3,"kind":"open","type":"Тип 13","body":"<p>Прочтите отрывок из текста.<p>&nbsp;</p><p>«После смерти Святополка Изяславича (князь) созвал в селе Берестове свою дружину... и постановили: брать проценты только до третьего платежа, если заимодавец берёт деньги \"в треть\"; если кто возьмёт с должника два (третных) реза, то можно взыскать и основную сумму долга; а кто возьмет три реза, тот не должен требовать основную сумму долга...Если же ростовщик взимает с должника <p>по&#8239;10&#8239;кун за год с гривны, то это не запрещается.<p>Если закуп убежит от господина [не расплатившись с ним за ссуду], то становится полным холопом; если же он пойдёт искать денег с разрешения господина или побежит к князю и его судьям с жалобой на обиду со стороны своего господина, то за что его нельзя делать холопом, но следует дать ему суд...<p>Если закуп украдёт что-либо, господин может поступить, с ним по своей воле: либо, после того как закупа поймают, заплатит потерпевшему за коня или иное имущество, украденное закупом, и превратит его в своего холопа; либо если господни не захочет расплачивался за закупа, то пусть продаст его, отдав сначала потерпевшему за украденного коня или вола или за товар, остаток берёт себе...<p>Холопство полное троякого вида: если кто купит [поступающего в холопы] до полгривны в присутствии свидетелей [сделки] и ногату [княжескому судье] заплатит перед самим холопом. А второе холопство кто женится на рабе без договора [с её владельцем], а если с договором [рядом], То как договорились, так и будет. А вот третье холопство: кто поступит в тиуны или н ключники [господина] без договора с ним, если же с договором, на том и стоять...»<p>Какое событие стало поводом для разработки норм, о которых идет речь в отрывке? Укажите год, в который произошло что событие. Назовите князя, при активном участии которого были выработаны данные нормы.","sol":"<b>Пояснение. </b><p>1)&#8239;&#8239;Событие&#8239;&#8239;— восстание в Киеве;<p>2)&#8239;&#8239;Год&#8239;&#8239;— 1113&#8239;г.;<p>3)&#8239;&#8239;Князь&#8239;&#8239;— Владимир Мономах.<b>Критерии проверки:</b><p><table><tr><th>Критерии</th><th>Баллы</th></tr><tr><td>Правильно названы три элемента</td><td>2</td></tr><tr><td>Правильно названы два элемента ответа</td><td>1</td></tr><tr><td>Правильно назван один любой элемент ответа.<p>ИЛИ Ответ неправильный</td><td>0</td></tr><tr><td>Максимальный балл</td><td>2</td></tr></table>Источник: ЕГЭ по истории 11.06.2024. Основная волна. Дальний ВостокПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь1Тип 14&nbsp;№&nbsp;57128 <img src=\"img/ege/sd_hist_ege_sdamgia_ru_img_briefcase_plus_png.png\" loading=\"lazy\"><img src=\"img/ege/sd_hist_ege_sdamgia_ru_img_exclamation_white_png.png\" loading=\"lazy\">Источник: ЕГЭ по истории 11.06.2024. Основная волна. Дальний Восток\nРаздел кодификатора ФИПИ/Решу ЕГЭ: 1.2 Русь в IX – начале XII в.;1.2.2 Категории населения. «Русская Правда». Поиск исторической информации. VIII - XVII векаi <p>Используя текст источника, укажите любую одну причину превращения закупа в полного холопа. Используя текст, укажите любые два способа попадания в полное холопство свободного человека.<p></p><b>Пояснение. </b><p>1)&#8239;&#8239;Если закуп убежит от господина [не расплатившись с ним за ссуду], то становится полным холопом.<p>2)&#8239;&#8239;Способы:<p>— Если кто купит [поступающего в холопы] до полгривны в присутствии свидетелей [сделки] и ногату [княжескому судье] заплатит перед самим холопом.<p>— Кто женится на рабе без договора [с её владельцем].<b>Критерии проверки:</b><p><table><tr><th>Критерии</th><th>Баллы</th></tr><tr><td>Правильно приведены три элемента</td><td>2</td></tr><tr><td>Правильно приведены два любых элемента ответа</td><td>1</td></tr><tr><td>Правильно приведён один любой элемент.<p> ИЛИ Ответ неправильный</td><td>0</td></tr><tr><td>Максимальный балл</td><td>2</td></tr></table>Источник: ЕГЭ по истории 11.06.2024. Основная волна. Дальний ВостокПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь\n2Тип 15&nbsp;№&nbsp;63189 <img src=\"img/ege/sd_hist_ege_sdamgia_ru_img_briefcase_plus_png.png\" loading=\"lazy\"><img src=\"img/ege/sd_hist_ege_sdamgia_ru_img_exclamation_white_png.png\" loading=\"lazy\"> Сопоставление исторических событий. Задания для подготовкиi <p>В данном отрывке приводятся правовые нормы Древнерусского государства, регулирующие долговые отношения и ограничивающие ростовщичество во избежание закабаления. Назовите реформатора из истории Древнего мира (Афинский полис), который в&#8239;VI&#8239;в. до н.&#8239;э. провёл реформы, полностью отменившие долговое рабство граждан, и укажите образное название этой реформы (или её суть).<p></p><b>Пояснение. </b><p>1.&#8239;&#8239;Реформатор&#8239;&#8239;— Солон.<p>2.&#8239;&#8239;Образное название реформы&#8239;&#8239;— Сисахфия (др.&#8239;-&#8288;греч. «стряхивание бремени»). Ее суть&#8239;&#8239;— отмена долгового рабства.<b>Критерии проверки:</b><p><table><tr><th>Критерии оценивания выполнения задания</th><th>Баллы</th></tr><tr><td>Правильно указаны все элементы</td><td>2</td></tr><tr><td>Правильно указан только один элемент</td><td>1</td></tr><tr><td>Ответ неправильный</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>2</td></tr></table>ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":""},{"id":40004,"tp":2,"kind":"open","type":"Тип 19","body":"<p>В 988&#8239;г. Владимир Святославич крестил Русь. Укажите:<p>а)&#8239;&#8239;причину крещения, связанную с международным положением Руси;<p>б)&#8239;&#8239;последствие крещения, связанное с изменениями в области культуры;<p>в)&#8239;&#8239;последствие крещения для населения, которое сохранило приверженность язычеству.<p>Ответ оформите в следующем виде (обязательно соблюдайте порядок заполнения пунктов ответа).<p>а)&#8239;&#8239;________________________________________________________________<p>б)&#8239;&#8239;________________________________________________________________<p>в)&#8239;&#8239;________________________________________________________________","sol":"<b>Пояснение. </b><p>а)&#8239;&#8239; Крещение Руси было необходимо для укрепления международного авторитета Руси, появления возможности заключать династические браки с Византией и Европейскими странами;<p>б)&#8239;&#8239;вместе с христианством на Русь пришла высокая культура христианского мира (грамотность, иконопись, каменное строительство);<p>в)&#8239;&#8239;Крещение Руси привело к началу масштабных гонений на язычников, распространению двоеверия среди населения.<b>Критерии проверки:</b><p><table><tr><th>Содержание верного ответа и указания по оцениванию<p><i>(допускаются иные формулировки ответа, не искажающие его смысла)</i></th><th>Баллы</th></tr><tr><td>Правильно приведены три итога</td><td>3</td></tr><tr><td>Правильно приведены два итога</td><td>2</td></tr><tr><td>Правильно приведён один итог</td><td>1</td></tr><tr><td>Приведены рассуждения общего характера, не соответствующие требованию задания<p> ИЛИ<p> Ответ неправильный</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>3</td></tr></table><p><b>Примечание.</b><p>Если в ответе наряду с требуемым количеством элементов приведены дополнительные (сверх требуемого в условии задания<p>количества) элементы, являющиеся ошибочными, то при оценивании действует следующее правило:<p>—&#8239;&#8239;если среди дополнительных элементов ошибочными являются два или более, то за ответ выставляется 0 баллов;<p>—&#8239;&#8239;если среди дополнительных элементов ошибочным является один, то за ответ выставляется на 1 балл ниже фактического по критериям.ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь","ans":""},{"id":40005,"tp":4,"kind":"open","type":"Тип 19","body":"<p>В первой трети XII&#8239;века Русь окончательно распадается на независимые княжества. Укажите:<p>а)&#8239;&#8239;причину распада, связанную с торговыми связями Руси и Византии;<p>б)&#8239;&#8239;причину распада, связанную с внутриэкономическим развитием Руси;<p>в)&#8239;&#8239;последствие распада для военного потенциала русских княжеств.<p>Ответ оформите в следующем виде (обязательно соблюдайте порядок заполнения пунктов ответа).<p>а)&#8239;&#8239;________________________________________________________________<p>б)&#8239;&#8239;________________________________________________________________<p>в)&#8239;&#8239;________________________________________________________________","sol":"<b>Пояснение. </b><p>а)&#8239;&#8239; Торговый путь «из варяг в греки» связывал земли восточных славян в единое экономическое и политическое пространство. В XII в. торговля по нему резко сократилась из-за упадка Византийской империи. Расположенные вдоль торгового пути города, включая столичный Киев, стали беднеть. Центральная власть Киева слабела, а некогда единое экономическое пространство разобщилось.<p>б)&#8239;&#8239;На Руси преобладало натуральное хозяйство, поэтому разные регионы Руси мало торговали между собой. Отсутствие прочных рыночных связей делало разные русские земли мало зависящими друг от друга. Каждое княжество было самодостаточным в хозяйственном плане, поэтому не стремилось к восстановлению былого единства Древнерусского государства.<p>в)&#8239;&#8239;В результате распада Руси на удельные княжества сокращается общая обороноспособность русских земель.<b>Критерии проверки:</b><p><table><tr><th>Содержание верного ответа и указания по оцениванию<p><i>(допускаются иные формулировки ответа, не искажающие его смысла)</i></th><th>Баллы</th></tr><tr><td>Правильно приведены три итога</td><td>3</td></tr><tr><td>Правильно приведены два итога</td><td>2</td></tr><tr><td>Правильно приведён один итог</td><td>1</td></tr><tr><td>Приведены рассуждения общего характера, не соответствующие требованию задания<p> ИЛИ<p> Ответ неправильный</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>3</td></tr></table><p><b>Примечание.</b><p>Если в ответе наряду с требуемым количеством элементов приведены дополнительные (сверх требуемого в условии задания<p>количества) элементы, являющиеся ошибочными, то при оценивании действует следующее правило:<p>—&#8239;&#8239;если среди дополнительных элементов ошибочными являются два или более, то за ответ выставляется 0 баллов;<p>—&#8239;&#8239;если среди дополнительных элементов ошибочным является один, то за ответ выставляется на 1 балл ниже фактического по критериям.ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь","ans":""},{"id":40006,"tp":5,"kind":"open","type":"Тип 19","body":"<p>В 1237−1241&#8239;гг.  произошло нашествие Батыя на русские княжества. Укажите:<p>а)&#8239;&#8239;причину поражения русских княжеств, связанную с характером взаимоотношений между русскими князьями;<p>б)&#8239;&#8239;последствие поражения, связанное хозяйством и экономикой русских княжеств;<p>в)&#8239;&#8239;последствие поражения, связанное с изменениями в сфере княжеской власти.<p>Ответ оформите в следующем виде (обязательно соблюдайте порядок заполнения пунктов ответа).<p>а)&#8239;&#8239;________________________________________________________________<p>б)&#8239;&#8239;________________________________________________________________<p>в)&#8239;&#8239;________________________________________________________________","sol":"<b>Пояснение. </b><p>а)&#8239;&#8239;русские князья не смогли создать единую коалицию против монголов и выступить единым войском, поэтому были разбиты по одиночке;<p>б)&#8239;&#8239;После нашествия на Руси значительно замедлилось развитие ремёсел. Некоторые ремёсла на долгое время прекратили существование: многих мастеров убили и увели в плен. В разорённых землях надолго пресеклось каменное строительство. Русские княжества должны были платить регулярную дань Золотой Орде, что легло тяжелым бременем на население;<p>в)&#8239;&#8239;В сражениях с монголами погибли многие князья и их дружинники, составлявшие основу военного могущества русских земель. Значительная часть русских земель на долгое время попала в политическую зависимость из ордынских завоевателей, теперь для подтверждения своего права княжить, они должны были получать ярлык на княжение у ордынского хана.<b>Критерии проверки:</b><p><table><tr><th>Содержание верного ответа и указания по оцениванию<p><i>(допускаются иные формулировки ответа, не искажающие его смысла)</i></th><th>Баллы</th></tr><tr><td>Правильно приведены три итога</td><td>3</td></tr><tr><td>Правильно приведены два итога</td><td>2</td></tr><tr><td>Правильно приведён один итог</td><td>1</td></tr><tr><td>Приведены рассуждения общего характера, не соответствующие требованию задания<p> ИЛИ<p> Ответ неправильный</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>3</td></tr></table><p><b>Примечание.</b><p>Если в ответе наряду с требуемым количеством элементов приведены дополнительные (сверх требуемого в условии задания<p>количества) элементы, являющиеся ошибочными, то при оценивании действует следующее правило:<p>—&#8239;&#8239;если среди дополнительных элементов ошибочными являются два или более, то за ответ выставляется 0 баллов;<p>—&#8239;&#8239;если среди дополнительных элементов ошибочным является один, то за ответ выставляется на 1 балл ниже фактического по критериям.ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":""},{"id":40007,"tp":5,"kind":"open","type":"Тип 19","body":"<p>В 1237−1241&#8239;гг. монголы совершили два крупных похода в русские княжества. Укажите:<p>а)&#8239;&#8239;причину почему монголы не стали включать русские земли в состав Золотой Орды;<p>б)&#8239;&#8239;последствие поражения для культурных объектов в русских княжествах;<p>в)&#8239;&#8239;последствие поражения, связанное с обороноспособностью русских земель.<p>Ответ оформите в следующем виде (обязательно соблюдайте порядок заполнения пунктов ответа).<p>а)&#8239;&#8239;________________________________________________________________<p>б)&#8239;&#8239;________________________________________________________________<p>в)&#8239;&#8239;________________________________________________________________","sol":"<b>Пояснение. </b><p>Могут быть указаны следующие последствия:<p>а)&#8239;&#8239;Русские земли находились в неподходящей для монголов природно-климатической зоне (леса), они привыкли вести кочевой образ жизни в степи и не видели смысла захватывать данные территории, предпочитая установить на них Ордынское иго;<p>б)&#8239;&#8239;в результате походов монголо-татар были уничтожены многие культурные святыни Руси (памятники искусства, литературы, архитектуры), прекращено каменное строительство;<p>в)&#8239;&#8239;Нашествие Батыя ослабило обороноспособность Руси. В сражениях с монголами погибли многие князья и их дружинники, составлявшие основу военного могущества своих княжеств.<b>Критерии проверки:</b><p><table><tr><th>Содержание верного ответа и указания по оцениванию<p><i>(допускаются иные формулировки ответа, не искажающие его смысла)</i></th><th>Баллы</th></tr><tr><td>Правильно приведены три итога</td><td>3</td></tr><tr><td>Правильно приведены два итога</td><td>2</td></tr><tr><td>Правильно приведён один итог</td><td>1</td></tr><tr><td>Приведены рассуждения общего характера, не соответствующие требованию задания<p> ИЛИ<p> Ответ неправильный</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>3</td></tr></table><p><b>Примечание.</b><p>Если в ответе наряду с требуемым количеством элементов приведены дополнительные (сверх требуемого в условии задания<p>количества) элементы, являющиеся ошибочными, то при оценивании действует следующее правило:<p>—&#8239;&#8239;если среди дополнительных элементов ошибочными являются два или более, то за ответ выставляется 0 баллов;<p>—&#8239;&#8239;если среди дополнительных элементов ошибочным является один, то за ответ выставляется на 1 балл ниже фактического по критериям.ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь","ans":""},{"id":45790,"tp":4,"kind":"open","type":"Тип 19","body":"<p>В 1132&#8239;г. Древнерусское государство окончательно распалось на самостоятельные княжества. Укажите:<p>а)&#8239;&#8239;причину данного события, связанную ситуацией среди князей Рюриковичей;<p>б)&#8239;&#8239;причину данного события, связанную с действиями кочевников;<p>в)&#8239;&#8239;последствие данного события, связанное с военной сферой.<p>&nbsp;</p><p>Ответ оформите в следующем виде (обязательно соблюдайте порядок заполнения пунктов ответа).<p>а)&#8239;&#8239;________________________________________________________________<p>б)&#8239;&#8239;________________________________________________________________<p>в)&#8239;&#8239;________________________________________________________________","sol":"<b>Пояснение. </b><p>а)&#8239;&#8239;разрастание семейства Рюриковичей, что при традиции предоставления каждому мужскому потомку удела вело к сокращению земли, находящейся в непосредственном ведении киевского князя;<p>б)&#8239;&#8239;ослабление Киевской земли в результате набегов кочевников и разорительных междоусобиц, что сокращало ресурсы киевского князя, а значит и возможности держать в подчинении других князей;<p>в)&#8239;&#8239;в результате распада на уделы снизилась общая обороноспособность русских земель<b>Критерии проверки:</b><p><table><tr><th>Содержание верного ответа и указания по оцениванию<p><i>(допускаются иные формулировки ответа, не искажающие его смысла)</i></th><th>Баллы</th></tr><tr><td>Правильно названы три причины</td><td>3</td></tr><tr><td>Правильно названы только две причины</td><td>2</td></tr><tr><td>Правильно названа только одна причина</td><td>1</td></tr><tr><td>Приведены рассуждения общего характера, не соответствующие требованию задания<p> ИЛИ<p> Ответ неправильный</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>3</td></tr></table><p><b>Примечание.</b><p>Если в ответе наряду с требуемым количеством элементов приведены дополнительные (сверх требуемого в условии задания<p>количества) элементы, являющиеся ошибочными, то при оценивании действует следующее правило:<p>—&#8239;&#8239;если среди дополнительных элементов ошибочными являются два или более, то за ответ выставляется 0 баллов;<p>—&#8239;&#8239;если среди дополнительных элементов ошибочным является один, то за ответ выставляется на 1 балл ниже фактического по критериям.ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":""},{"id":47135,"tp":2,"kind":"open","type":"Тип 19","body":"<p>В конце X века по инициативе киевского князя Владимира Святославича произошло принятие Русью христианства по греческому (восточному) образцу. Укажите:<p>а)&#8239;&#8239;причину данного выбора, связанную с его экономическими преимуществами;<p>б)&#8239;&#8239;причину данного выбора, связанную с позицией части населения в отношении восточного христианства;<p>в)&#8239;&#8239;причину данного выбора, связанную с изменением политического статуса князя.<p>&nbsp;</p><p>Ответ оформите в следующем виде (обязательно соблюдайте порядок заполнения пунктов ответа).<p>а)&#8239;&#8239;________________________________________________________________<p>б)&#8239;&#8239;________________________________________________________________<p>в)&#8239;&#8239;________________________________________________________________","sol":"<b>Пояснение. </b><p>а)&#8239;&#8239;у Руси были более тесные экономические и политические связи с Византией, чем с Западной Европой и другими странами, принятие восточного христианства существенно укрепило бы их;<p>б)&#8239;&#8239;многие жители Руси еще до официального принятия христианства самостоятельно крестились в Константинополе, христианкой была бабушка отца Владимира, княгиня Ольга;<p>в)&#8239;&#8239;греческая церковь была подчинена государству и императору, тогда как в Западной Европе Папа Римский обладал намного большей политической властью и не подчинялся монархам. Князю Владимиру было выгоднее с политической точки зрение принять восточный вариант христианства.<b>Критерии проверки:</b><p><table><tr><th>Содержание верного ответа и указания по оцениванию<p><i>(допускаются иные формулировки ответа, не искажающие его смысла)</i></th><th>Баллы</th></tr><tr><td>Правильно названы три причины</td><td>3</td></tr><tr><td>Правильно названы только две причины</td><td>2</td></tr><tr><td>Правильно названа только одна причина</td><td>1</td></tr><tr><td>Приведены рассуждения общего характера, не соответствующие требованию задания<p> ИЛИ<p> Ответ неправильный</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>3</td></tr></table><p><b>Примечание.</b><p>Если в ответе наряду с требуемым количеством элементов приведены дополнительные (сверх требуемого в условии задания<p>количества) элементы, являющиеся ошибочными, то при оценивании действует следующее правило:<p>—&#8239;&#8239;если среди дополнительных элементов ошибочными являются два или более, то за ответ выставляется 0 баллов;<p>—&#8239;&#8239;если среди дополнительных элементов ошибочным является один, то за ответ выставляется на 1 балл ниже фактического по критериям.Источник: ЕГЭ по истории 31.03.2022. Досрочная волнаПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь","ans":""},{"id":51132,"tp":3,"kind":"open","type":"Тип 19","body":"<p>В первой трети XI века происходит принятие Русской Правды. Укажите:<p>а)&#8239;&#8239;причину принятия, связанную с становлением и укрепление Древнерусского государства;<p>б)&#8239;&#8239;последствие принятия для политико-правового статуса князя;<p>в)&#8239;&#8239;последствие принятия в социальной сфере.<p>&nbsp;</p><p>Ответ оформите в следующем виде (обязательно соблюдайте порядок заполнения пунктов ответа).<p>а)&#8239;&#8239;________________________________________________________________<p>б)&#8239;&#8239;________________________________________________________________<p>в)&#8239;&#8239;________________________________________________________________","sol":"<b>Пояснение. </b><p>а)&#8239;&#8239;укрепление единства Древнерусского государства было невозможно без установлению единого закона и единого порядка судопроизводства, что привело к разработке и принятию Русской Правды;<p>б)&#8239;&#8239;происходит укрепление власти великого князя, только уполномоченные люди которого могли вершить суд;<p>в)&#8239;&#8239;принятие Русской Правды привело к юридическому закреплению установившегося социального неравенства через назначение разных штрафов за убийство представителей разных социальных групп.<b>Критерии проверки:</b><p><table><tr><th>Содержание верного ответа и указания по оцениванию<p><i>(допускаются иные формулировки ответа, не искажающие его смысла)</i></th><th>Баллы</th></tr><tr><td>Правильно названы три последствия</td><td>3</td></tr><tr><td>Правильно названы только два последствия</td><td>2</td></tr><tr><td>Правильно названо только одно последствие</td><td>1</td></tr><tr><td>Приведены рассуждения общего характера, не соответствующие требованию задания<p> ИЛИ<p> Ответ неправильный</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>3</td></tr></table><p><b>Примечание.</b><p>Если в ответе наряду с требуемым количеством элементов приведены дополнительные (сверх требуемого в условии задания<p>количества) элементы, являющиеся ошибочными, то при оценивании действует следующее правило:<p>—&#8239;&#8239;если среди дополнительных элементов ошибочными являются два или более, то за ответ выставляется 0 баллов;<p>—&#8239;&#8239;если среди дополнительных элементов ошибочным является один, то за ответ выставляется на 1 балл ниже фактического по критериям.ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь","ans":""},{"id":51722,"tp":5,"kind":"open","type":"Тип 19","body":"<p>31&#8239;мая 1223&#8239;г. на реке Калке произошла битва между передовыми отрядами войска Чингисхана и русско-половецким войском, завершившаяся сокрушительным поражением последнего. Укажите:<p>а)&#8239;&#8239;причину поражения, связанную с организацией боя русскими дружинами;<p>б)&#8239;&#8239;причину поражения, связанную с действиями половцев;<p>в)&#8239;&#8239;последствие поражения для русских княжеств.<p>&nbsp;</p><p>Ответ оформите в следующем виде (обязательно соблюдайте порядок заполнения пунктов ответа).<p>а)&#8239;&#8239;________________________________________________________________<p>б)&#8239;&#8239;________________________________________________________________<p>в)&#8239;&#8239;________________________________________________________________","sol":"<b>Пояснение. </b><p>а)&#8239;&#8239;причиной поражения была несогласованность действий русских князей, участвовавших в битве, незнание русскими князьями тактики ведения боя, применяемой монголами и неучастие в основном сражении дружины киевского князя;<p>б)&#8239;&#8239;причиной поражения  было бегство половцев, смешавших ряды русского войска;<p>в)&#8239;&#8239;в результате сражения было уничтожено 9/10 русских дружин, что подорвало оборонных потенциал южнорусских княжеств.<b>Критерии проверки:</b><p><table><tr><th>Содержание верного ответа и указания по оцениванию<p><i>(допускаются иные формулировки ответа, не искажающие его смысла)</i></th><th>Баллы</th></tr><tr><td>Правильно указаны три причины (предпосылки)</td><td>3</td></tr><tr><td>Правильно указаны только две причины (предпосылки)</td><td>2</td></tr><tr><td>Правильно указана только одна причина (предпосылка)</td><td>1</td></tr><tr><td>Приведены рассуждения общего характера, не соответствующие требованию задания<p> ИЛИ<p> Ответ неправильный</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>3</td></tr></table><p><b>Примечание.</b><p>Если в ответе наряду с требуемым количеством элементов приведены дополнительные (сверх требуемого в условии задания<p>количества) элементы, являющиеся ошибочными, то при оценивании действует следующее правило:<p>—&#8239;&#8239;если среди дополнительных элементов ошибочными являются два или более, то за ответ выставляется 0 баллов;<p>—&#8239;&#8239;если среди дополнительных элементов ошибочным является один, то за ответ выставляется на 1 балл ниже фактического по критериям.ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь","ans":""},{"id":52382,"tp":5,"kind":"open","type":"Тип 19","body":"<p>В XIII веке произошло успешное нашествия войск хана Батыя на Русь. Укажите:<p>а)&#8239;&#8239;причину поражения русских княжеств, связанную с их политико-правовым статусом и характером взаимоотношений между собой;<p>б)&#8239;&#8239;причину поражения русских княжеств, связанную с военной организацией монголов;<p>в)&#8239;&#8239;последствие поражения для русских княжеств в экономической сфере.<p>&nbsp;</p><p>Ответ оформите в следующем виде (обязательно соблюдайте порядок заполнения пунктов ответа).<p>а)&#8239;&#8239;________________________________________________________________<p>б)&#8239;&#8239;________________________________________________________________<p>в)&#8239;&#8239;________________________________________________________________","sol":"<b>Пояснение. </b><p>а)&#8239;&#8239;политическая раздробленность русских земель, постоянные княжеские междоусобицы, что препятствовало единству действий и ослабляло обороноспособность; <p>б)&#8239;&#8239;многочисленность монгольского войска в сравнении с русскими дружинами (даже по самым скромным оценкам войско Батыя превышало 30&#8239;тысяч человек, тогда как войско великого князя Владимирского не превышало 8&#8239;тысяч), крепкая дисциплина и высокая степень организованности в монгольском войске (десятичная система организации войска, строгая иерархия, военачальники руководили сражением, а не подавали пример личного мужества), высокая мобильность монгольского войска благодаря выносливости монгольских лошадей и качествам монголов как наездников (внезапность нападения, окружение противника на поле сражения, фланговые удары), овладение монголами передовыми военными технологиями благодаря завоеванию Китая (стенобитные орудия, зажигательные снаряды);<p>в)&#8239;&#8239; монголы установили систему ига над русскими княжествами, которая предполагала регулярную выплату дани, что тяжелым бременем легло на экономику Руси.<b>Критерии проверки:</b><p><table><tr><th>Содержание верного ответа и указания по оцениванию<p><i>(допускаются иные формулировки ответа, не искажающие его смысла)</i></th><th>Баллы</th></tr><tr><td>Правильно указаны три причины</td><td>3</td></tr><tr><td>Правильно указаны только две причины</td><td>2</td></tr><tr><td>Правильно указана только одна причина </td><td>1</td></tr><tr><td>Приведены рассуждения общего характера, не соответствующие требованию задания<p> ИЛИ<p> Ответ неправильный</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>3</td></tr></table><p><b>Примечание.</b><p>Если в ответе наряду с требуемым количеством элементов приведены дополнительные (сверх требуемого в условии задания<p>количества) элементы, являющиеся ошибочными, то при оценивании действует следующее правило:<p>—&#8239;&#8239;если среди дополнительных элементов ошибочными являются два или более, то за ответ выставляется 0 баллов;<p>—&#8239;&#8239;если среди дополнительных элементов ошибочным является один, то за ответ выставляется на 1 балл ниже фактического по критериям.ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь","ans":""},{"id":52416,"tp":5,"kind":"open","type":"Тип 19","body":"<p>В 1237&#8239;г началось нашествие Батыя на Русь. Укажите:<p>а)&#8239;&#8239;последствие нашествия для населения русских княжеств;<p>б)&#8239;&#8239;последствие нашествия для экономики русских княжеств;<p>в)&#8239;&#8239;последствие нашествия, связанное с дальнейшими взаимоотношениями русских княжеств и монголов.<p>&nbsp;</p><p>Ответ оформите в следующем виде (обязательно соблюдайте порядок заполнения пунктов ответа).<p>а)&#8239;&#8239;________________________________________________________________<p>б)&#8239;&#8239;________________________________________________________________<p>в)&#8239;&#8239;________________________________________________________________","sol":"<b>Пояснение. </b><p>а)&#8239;&#8239;убийство и пленение миллионов русских людей (10−30% от всего населения, по оценкам разных историков);<p>б)&#8239;&#8239;разорение многих городов и селений (19 городов были разорены полностью, Рязань, например, так и не была отстроена на прежнем месте), ущерб хозяйству, особенно ремеслу и торговле (многие виды ремёсел исчезли навсегда или на время – чернение по металлу, например);<p>в)&#8239;&#8239;установление на два с лишним столетия ордынского ига над Русью, которое предполагало выплату дани и политическую зависимость русских княжеств от Орды;<b>Критерии проверки:</b><p><table><tr><th>Содержание верного ответа и указания по оцениванию<p><i>(допускаются иные формулировки ответа, не искажающие его смысла)</i></th><th>Баллы</th></tr><tr><td>Правильно указаны три последствия</td><td>3</td></tr><tr><td>Правильно указаны только два последствия</td><td>2</td></tr><tr><td>Правильно указана только одно последствие </td><td>1</td></tr><tr><td>Приведены рассуждения общего характера, не соответствующие требованию задания<p> ИЛИ<p> Ответ неправильный</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>3</td></tr></table><p><b>Примечание.</b><p>Если в ответе наряду с требуемым количеством элементов приведены дополнительные (сверх требуемого в условии задания<p>количества) элементы, являющиеся ошибочными, то при оценивании действует следующее правило:<p>—&#8239;&#8239;если среди дополнительных элементов ошибочными являются два или более, то за ответ выставляется 0 баллов;<p>—&#8239;&#8239;если среди дополнительных элементов ошибочным является один, то за ответ выставляется на 1 балл ниже фактического по критериям.ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":""},{"id":53026,"tp":4,"kind":"open","type":"Тип 19","body":"<p>В 30-х годах XII&#8239;века Древнерусское государство распалось. Но позже русские земли решили объединиться в единое государство. Укажите:<p>а)&#8239;&#8239;предпосылку объединения, связанную с внешнеполитической угрозой;<p>б)&#8239;&#8239;предпосылку объединения, связанную с экономической сферой;<p>в)&#8239;&#8239;последствие объединения, связанное культурой.<p>&nbsp;</p><p>Ответ оформите в следующем виде (обязательно соблюдайте порядок заполнения пунктов ответа).<p>а)&#8239;&#8239;________________________________________________________________<p>б)&#8239;&#8239;________________________________________________________________<p>в)&#8239;&#8239;________________________________________________________________","sol":"<b>Пояснение. </b><p>а)&#8239;&#8239;Одной из предпосылок являлась необходимость обретения независимости от Золотой Орды. По отдельности русские княжества не могли противостоять Орде. Только объединение позволило бы им обрести независимость. <p>б)&#8239;&#8239;Предпосылкой, способствующей объединению русских земель, являлось постепенное восстановление и развитие хозяйства русских земель. Так, например, все больше княжеств с восстановлением хозяйства после разрушительных набегов монголо-татар ощущали необходимость экономического единства, чтобы обмениваться между собой необходимыми товарами, восстановить экономический баланс, это сплотило их на основе экономических связей.<p>в)&#8239;&#8239;Благодаря объединение русских княжеств в единое государство удалось сохранить религиозное и культурное единство населения русских земель (православная вера, язык, традиции и обычаи и т.&#8239;д.).<b>Критерии проверки:</b><p><table><tr><th>Содержание верного ответа и указания по оцениванию <p><i>(допускаются иные формулировки ответа, не искажающие его смысла)</i></th><th>Баллы</th></tr><tr><td>Правильно указаны три причины (предпосылки)</td><td>3</td></tr><tr><td>Правильно указаны только две причины (предпосылки)</td><td>2</td></tr><tr><td>Правильно указана только одна причина (предпосылка)</td><td>1</td></tr><tr><td>Приведены рассуждения общего характера, не соответствующие требованию задания<p> ИЛИ<p> Ответ неправильный</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>3</td></tr></table><p><b>Примечание.</b><p>Если в ответе наряду с требуемым количеством элементов приведены дополнительные (сверх требуемого в условии задания<p>количества) элементы, являющиеся ошибочными, то при оценивании действует следующее правило:<p>—&#8239;&#8239;если среди дополнительных элементов ошибочными являются два или более, то за ответ выставляется 0 баллов;<p>—&#8239;&#8239;если среди дополнительных элементов ошибочным является один, то за ответ выставляется на 1 балл ниже фактического по критериям.Источник: ЕГЭ по истории 12.04.2023. Досрочная волна, резервный деньПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь","ans":""},{"id":53760,"tp":2,"kind":"open","type":"Тип 19","body":"<p>Княгиня Ольга приняла крещение в столице Византии, городе Константинополь. Укажите:<p>а)&#8239;&#8239;причину крещения, связанную с внешней политикой княгини Ольги;<p>б)&#8239;&#8239;последствие крещения, связанное с христианизацией Руси;<p>в)&#8239;&#8239;последствие крещения, связанное с культурным развитие Руси.<p>&nbsp;</p><p>Ответ оформите в следующем виде (обязательно соблюдайте порядок заполнения пунктов ответа).<p>а)&#8239;&#8239;________________________________________________________________<p>б)&#8239;&#8239;________________________________________________________________<p>в)&#8239;&#8239;________________________________________________________________","sol":"<b>Пояснение. </b><p>а)&#8239;&#8239;Княгиня Ольга стремилась через крещение укрепить отношения с Византией, вступить с ней в союз.<p>б)&#8239;&#8239;После крещения Ольги среди населения Руси росло число тех, кто привял христианство по примеру Ольги (этому способствовала деятельность самой Ольги после крещения) ИЛИ крещение Ольги оказало влияние на выбор князя Владимира в пользу христианства по византийскому образцу.<p>в)&#8239;&#8239;Согласно ряду источников княгиня Ольга основала несколько храмов на Руси, что способствовало проникновению на Русь христианской культуры.<b>Критерии проверки:</b><p><table><tr><th>Содержание верного ответа и указания по оцениванию<p><i>(допускаются иные формулировки ответа, не искажающие его смысла)</i></th><th>Баллы</th></tr><tr><td>Правильно приведены три последствия.</td><td>3</td></tr><tr><td>Правильно приведены два последствия.</td><td>2</td></tr><tr><td>Правильно приведено одно последствие.</td><td>1</td></tr><tr><td>Приведены рассуждения общего характера, не соответствующие требованию задания.<p> ИЛИ <p> Ответ неправильный.</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>3</td></tr></table><p><b>Примечание.</b><p>Если в ответе наряду с требуемым количеством элементов приведены дополнительные (сверх требуемого в условии задания<p>количества) элементы, являющиеся ошибочными, то при оценивании действует следующее правило:<p>—&#8239;&#8239;если среди дополнительных элементов ошибочными являются два или более, то за ответ выставляется 0&#8239;баллов;<p>—&#8239;&#8239;если среди дополнительных элементов ошибочным является один, то за ответ выставляется на 1&#8239;балл ниже фактического по критериям.ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь","ans":""},{"id":53763,"tp":2,"kind":"open","type":"Тип 19","body":"<p>В 945&#8239;г. произошло убийство племенем древлян князя Игоря Рюриковича. Укажите:<p>а)&#8239;&#8239;причину убийства, связанную с нарушением Игоря сложившихся обычаев;<p>б)&#8239;&#8239;последствие его убийства, связанное с политикой Ольги по отношению к древлянам;<p>в)&#8239;&#8239;последствие его убийства, связанное экономической сферой.<p>&nbsp;</p><p>Ответ оформите в следующем виде (обязательно соблюдайте порядок заполнения пунктов ответа).<p>а)&#8239;&#8239;________________________________________________________________<p>б)&#8239;&#8239;________________________________________________________________<p>в)&#8239;&#8239;________________________________________________________________","sol":"<b>Пояснение. </b><p>а)&#8239;&#8239;По требованию дружины, недовольной своим содержанием, князь отправился за данью к древлянам и произвольно увеличил размер прежней дани, а при ее сборе дружинники творили насилие над жителями. Не удовольствовавшись уже полученным, Игорь с небольшой частью дружины возвратился за новой данью. Тогда древляне возмутились, взяли Игоря в плен и убили.<p>б)&#8239;&#8239;Месть княгини Ольги древлянам за убийство Игоря, сожжение их племенного центра (города Искоростень) и начало регентства княгини Ольги при малолетнем князе Святославе Игоревиче.<p>в)&#8239;&#8239;Налоговая реформа княгини Ольги&#8239;&#8239;— введение уроков и погостов.<b>Критерии проверки:</b><p><table><tr><th>Содержание верного ответа и указания по оцениванию<p><i>(допускаются иные формулировки ответа, не искажающие его смысла)</i></th><th>Баллы</th></tr><tr><td>Правильно приведены три последствия.</td><td>3</td></tr><tr><td>Правильно приведены два последствия.</td><td>2</td></tr><tr><td>Правильно приведено одно последствие.</td><td>1</td></tr><tr><td>Приведены рассуждения общего характера, не соответствующие требованию задания.<p> ИЛИ <p> Ответ неправильный.</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>3</td></tr></table><p><b>Примечание.</b><p>Если в ответе наряду с требуемым количеством элементов приведены дополнительные (сверх требуемого в условии задания<p>количества) элементы, являющиеся ошибочными, то при оценивании действует следующее правило:<p>—&#8239;&#8239;если среди дополнительных элементов ошибочными являются два или более, то за ответ выставляется 0 баллов;<p>—&#8239;&#8239;если среди дополнительных элементов ошибочным является один, то за ответ выставляется на 1 балл ниже фактического по критериям.ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь","ans":""},{"id":55327,"tp":2,"kind":"open","type":"Тип 19","body":"<p>В 945&#8239;г. правительницей при малолетнем сыне стала княгиня Ольга, вскоре изменившая систему сбора дани.<p>Укажите: а) причину, по которой княгиня Ольга приняла решение изменить систему сбора дани; б) последствие для взаимоотношений Киева и подвластных племён от изменения системы сбора дани; в) последствие для великокняжеской власти от изменения системы сбора дани.<p>&nbsp;</p><p>Ответ оформите в следующем виде (обязательно соблюдайте порядок заполнения пунктов ответа).<p>а)&#8239;&#8239;_______________________________________________________________<p>б)&#8239;&#8239;_______________________________________________________________<p>в)&#8239;&#8239;_______________________________________________________________","sol":"<b>Пояснение. </b><p>а)&#8239;&#8239;Восстание древлян и гибель князя Игоря, спровоцированные нерегламентированностью полюдья.<p>б)&#8239;&#8239;Фиксированный размер дани примирял племена с необходимостью платить дань, вызывал меньшее их сопротивление Киеву.<p>в)&#8239;&#8239;Отсутствие необходимости выходить в полюдье позволяло киевскому князю больше внимания уделять другим делам управления, повысилась безопасность верховной власти, т.&#8239;к. князю не надо было рисковать своей жизнью в полюдье.<b>Критерии проверки:</b><p><table><tr><th>Критерии</th><th>Баллы</th></tr><tr><td>Правильно указаны три элемента ответа</td><td>3</td></tr><tr><td>Правильно указаны два элемента ответа</td><td>2</td></tr><tr><td>Правильно указаны один элемент ответа</td><td>1</td></tr><tr><td>Приведены рассуждения общего характера, не соответствующие требованию задания.<p> ИЛИ Ответ неправильный</td><td>0</td></tr><tr><td>Максимальный балл</td><td>3</td></tr></table>ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":""},{"id":55348,"tp":3,"kind":"open","type":"Тип 19","body":"<p>В 1113&#8239;г. умер князь Святополк Изяславич. После его смерти киевский престол должен был занять Давыд Святославич. Но в Киеве вспыхнуло восстание, и киевляне призвали на княжение Владимира Мономаха. Укажите: а) причину восстания в Киеве; б) причину приглашения на престол именно Владимира Мономаха; в) последствие восшествия на киевский престол Владимира Мономаха для развития правовой системы Древней Руси.<p>&nbsp;</p><p>Ответ оформите в следующем виде (обязательно соблюдайте порядок заполнения пунктов ответа).<p>а)&#8239;&#8239;_______________________________________________________________<p>б)&#8239;&#8239;_______________________________________________________________<p>в)&#8239;&#8239;_______________________________________________________________","sol":"<b>Пояснение. </b><p>а)&#8239;&#8239;После смерти Святополка Изяславича в Киеве вспыхнуло восстание против ростовщиков, давивших киевлян высокими процентами.<p>б)&#8239;&#8239;Владимир Мономах был известен своей борьбой с половцами, от набегов которых сильно страдала Киевская земля, и за это киевляне ему были благодарны.<p>в)&#8239;&#8239;При Владимире Мономахе был принят Устав о резах, дополнивший Русскую Правду, по которому были урегулированы вопросы, связанные со взятием ссуд.<b>Критерии проверки:</b><p><table><tr><th>Критерии</th><th>Баллы</th></tr><tr><td>Правильно указаны три элемента ответа</td><td>3</td></tr><tr><td>Правильно указаны два элемента ответа</td><td>2</td></tr><tr><td>Правильно указаны один элемент ответа</td><td>1</td></tr><tr><td>Приведены рассуждения общего характера, не соответствующие требованию задания.<p> ИЛИ Ответ неправильный</td><td>0</td></tr><tr><td>Максимальный балл</td><td>3</td></tr></table>ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь","ans":""},{"id":57789,"tp":3,"kind":"open","type":"Тип 19","body":"<p>В&#8239;1097&#8239;г. в Любеч съехались русские князья, чтобы принять важные для всей Руси решения. <p>Укажите: <p>&nbsp;</p><p>а)&#8239;&#8239;причину съезда, связанную с проблемами системы престолонаследия на Руси; <p>б)&#8239;&#8239;причину съезда, связанную с внешнеполитическим положением Руси; <p>в)&#8239;&#8239;последствие принятых на съезде решений для единства русских земель. <p>&nbsp;</p><p>Ответ оформите в следующем виде (обязательно соблюдайте порядок заполнения пунктов ответа). <p>а)&#8239;&#8239;_______________________________________________________________  <p>б)&#8239;&#8239;_______________________________________________________________  <p>в)&#8239;&#8239;_______________________________________________________________","sol":"<b>Пояснение. </b><p>Правильный ответ должен содержать следующие элементы:<p>а)&#8239;&#8239;существующая на Руси лествичная система престолонаследия провоцировала постоянные конфликты, так как возникали споры между младшими дядями и старшими племянниками, из-за перемещений князей с престола на престол по городам, из-за князей-изгоев;<p>б)&#8239;&#8239;задачей съезда было объединить князей в борьбе против половецких набегов, участившихся из-за княжеских междоусобиц;<p>в)&#8239;&#8239;с одной стороны, съезд, утвердив новый порядок&#8239;&#8239;— «каждый да владеет вотчиной своей»&#8239;&#8239;— и установив очерёдность занятия киевского престола, способствовал сохранению единства Руси ещё на несколько десятилетий; с другой стороны, была подготовлена правовая основа для распада Руси на отдельные княжества.<p>Могут быть указаны другая причина и/или последствие(-&#8288;я).<b>Критерии проверки:</b><p><table><tr><th>Критерии оценивания выполнения задания</th><th>Баллы</th></tr><tr><td>Правильно раскрыт смысл понятия (содержание понятия корректно раскрыто через родовую принадлежность понятия и, если это необходимо, его видовое(-ые) отличие(-я)), приведён один исторический факт, конкретизирующий данное понятие</td><td>2</td></tr><tr><td>Правильно раскрыт смысл понятия (содержание понятия корректно раскрыто через родовую принадлежность понятия и, если это необходимо, его видовое(-ые) отличие(-я)), но исторический факт, конкретизирующий данное понятие, приведён неправильно / не приведён / содержится в приведённом определении понятия. <p> ИЛИ Смысл понятия не раскрыт / раскрыт неправильно; приведён один исторический факт, конкретизирующий данное понятие</td><td>1</td></tr><tr><td>Смысл понятия не раскрыт / раскрыт неправильно; исторический факт, конкретизирующий данное понятие, приведён неправильно / не приведён.<p> ИЛИ Приведены рассуждения общего характера, не соответствующие требованию задания</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>2</td></tr></table>Источник: СтатГрад: Тренировочная работа 13.11.2024. Вариант ИС2410201ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":""},{"id":59707,"tp":4,"kind":"open","type":"Тип 19","body":"<p>В&#8239;XII&#8239;в. начался процесс политической раздробленности Руси, но на протяжении&#8239;XIII–XV&#8239;вв. возникали причины (предпосылки) объединения русских земель в единое государство. Укажите:  <p>&nbsp;</p><p>а)&#8239;&#8239;причину (предпосылку) объединения русских земель, связанную с внешнеполитическим фактором;<p>б)&#8239;&#8239;экономическую причину (предпосылку) объединения русских земель;  <p>в)&#8239;&#8239;причину (предпосылку) объединения русских земель, связанную с позицией Русской Православной Церкви.  <p>&nbsp;</p><p>Ответ оформите в следующем виде (обязательно соблюдайте порядок заполнения пунктов ответа). <p>&nbsp;</p><p>а)&#8239;&#8239;______________________________________________________________ <p>б)&#8239;&#8239;______________________________________________________________ <p>в)&#8239;&#8239;______________________________________________________________","sol":"<b>Пояснение. </b><p>а)&#8239;&#8239;предпосылкой объединения русских земель была внешняя угроза со стороны Орды; постепенно приходило осознание того, что покончить с властью ордынцев невозможно без объединения.<p>б)&#8239;&#8239;увеличение производительности земледелия, усиление товарного характера ремесла вели к развитию экономических связей между русскими княжествами и землями.<p>в)&#8239;&#8239;Русская Православная Церковь, стремившаяся сохранить и упрочить единую церковную организацию, поддерживала идею объединения земель Руси и князей, способных её реализовать. Например, митрополит Алексий содействовал окончательному закреплению великого княжения за московскими князьями.<b>Критерии проверки:</b><p><table><tr><th>Критерии оценивания выполнения задания</th><th>Баллы</th></tr><tr><td>Правильно раскрыт смысл понятия (содержание понятия корректно раскрыто через родовую принадлежность понятия и, если это необходимо, его видовое(-ые) отличие(-я)), приведён один исторический факт, конкретизирующий данное понятие</td><td>2</td></tr><tr><td>Правильно раскрыт смысл понятия (содержание понятия корректно раскрыто через родовую принадлежность понятия и, если это необходимо, его видовое(-ые) отличие(-я)), но исторический факт, конкретизирующий данное понятие, приведён неправильно / не приведён / содержится в приведённом определении понятия. <p> ИЛИ Смысл понятия не раскрыт / раскрыт неправильно; приведён один исторический факт, конкретизирующий данное понятие</td><td>1</td></tr><tr><td>Смысл понятия не раскрыт / раскрыт неправильно; исторический факт, конкретизирующий данное понятие, приведён неправильно / не приведён.<p> ИЛИ Приведены рассуждения общего характера, не соответствующие требованию задания</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>2</td></tr></table>ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь","ans":""},{"id":63138,"tp":2,"kind":"open","type":"Тип 20","body":"<p>Вспомните смысл понятия «полюдье» и ответьте на вопросы. Как полюдье связано с восстанием древлян? Чем заменила полюдье княгиня Ольга?","sol":"<b>Пояснение. </b><p>Полюдье&#8239;&#8239;— это объезд князем с дружиной подвластных земель для сбора дани, практиковавшийся в Древней Руси. В&#8239;945&#8239;г. князь Игорь отправился в полюдье к древлянам. Собрав дань, он посчитал её недостаточной и вернулся с малой частью дружины, чтобы потребовать дополнительную дань. После гибели мужа княгиня Ольга провела налоговую реформу, упорядочив систему сбора дани: ввела «уроки»&#8239;&#8239;— заранее установленные, строго фиксированные размеры дани и ввела «погосты»&#8239;&#8239;— специальные административно-хозяйственные центры, куда свозилась дань.<b>Критерии проверки:</b><p><table><tr><th>Критерии оценивания выполнения задания</th><th>Баллы</th></tr><tr><td>Приведены по одному аргументу для двух стран</td><td>3</td></tr><tr><td>Приведён только аргумент для одной страны</td><td>2</td></tr><tr><td>Аргумент(ы) не сформулирован(ы); приведено не менее двух фактов, которые могут быть использованы для аргументации</td><td>1</td></tr><tr><td>Аргумент(ы) не сформулирован(ы); приведён один факт, который может быть использован для аргументации. <p> ИЛИ Приведены рассуждения общего характера, не соответствующие требованию задания.<p> ИЛИ Ответ неправильный</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>3</td></tr></table>ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь","ans":""},{"id":63206,"tp":2,"kind":"open","type":"Тип 22","body":"<p>Согласно летописи в&#8239;862&#8239;г. ильменские словене пригласили к себе варягов. Используя исторические знания, приведите аргументы в подтверждение точки зрения, что указанное событие привело к важным последствиям для развития восточнославянского общества. При изложении аргументов обязательно используйте исторические факты. Для второго аргумента не следует использовать факты, которые Вы уже использовали для первого аргумента.<p>&nbsp;</p><p>Ответ запишите в следующем виде.<p>Аргумент&#8239;1: _________________________<p>Аргумент&#8239;2: _________________________","sol":"<b>Пояснение. </b><p>Аргумент&#8239;1: призвание варягов привело к образованию единого Древнерусского государства. В&#8239;862&#8239;г. Рюрик стал княжить в Новгороде, а в&#8239;882&#8239;г. его преемник Олег захватил Киев и объединил северные и южные восточнославянские земли. Это создало общую княжескую власть, дружину и систему сбора дани, что стало основой государственности восточных славян.<p>&nbsp;</p><p>Аргумент&#8239;2: призвание варягов в конечном счёте способствовало христианизации Руси. Утверждение варяжской династии привело к власти Владимира Святославича, который в&#8239;988&#8239;г. сделал христианство государственной религией. Это вызвало создание церковной организации, строительство храмов, распространение кириллической письменности и летописания, что глубоко изменило духовную и культурную жизнь восточнославянского общества.<b>Критерии проверки:</b><p><table><tr><th>Критерии оценивания выполнения задания</th><th>Баллы</th></tr><tr><td>Правильно сформулированы два аргумента</td><td>2</td></tr><tr><td>Правильно сформулирован только один аргумент</td><td>1</td></tr><tr><td>Аргумент(ы) не сформулирован(ы).<p> ИЛИ Приведены рассуждения общего характера, не соответствующие требованию задания.<p> ИЛИ Ответ неправильный</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>2</td></tr></table>ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь","ans":""},{"id":63211,"tp":2,"kind":"open","type":"Тип 22","body":"<p>Используя исторические знания, приведите аргументы в подтверждение точки зрения, что на Руси в&#8239;X&#8239;веке внешнеполитические обстоятельства значительно повлияли на принятие решений в церковно-религиозной жизни. При изложении аргументов обязательно используйте исторические факты. Для второго аргумента не следует использовать факты, которые Вы уже использовали для первого аргумента.<p>&nbsp;</p><p>Ответ запишите в следующем виде.<p>Аргумент&#8239;1: ______________________________.<p>Аргумент&#8239;2: ______________________________.","sol":"<b>Пояснение. </b><p>Аргумент&#8239;1: в&#8239;987&#8239;г. Византия, подавляя восстание Варды Фоки, обратилась за военной помощью к киевскому князю Владимиру. Условием помощи стал брак Владимира с сестрой императора Анной и крещение Руси. После подавления восстания и похода Владимира на Корсунь договор был выполнен. Крещение Руси по византийскому обряду привело к учреждению Киевской митрополии в составе Константинопольского патриархата, что закрепило церковную зависимость Руси от Византии и определило восточно-христианский вектор её религиозного развития.<p>&nbsp;</p><p>Аргумент&#8239;2: внешнеполитические контакты Руси с Волжской Булгарией, Хазарией и странами Западной Европы повлияли на выбор веры Владимиром. Согласно «Повести временных лет», около&#8239;986&#8239;г. Владимир отправил послов для испытания религий: ислама, иудаизма, католичества и православия. Выбор пал на православие, что было обусловлено стремлением сохранить союз с Византией и получить признание на международной арене.<b>Критерии проверки:</b><p><table><tr><th>Критерии оценивания выполнения задания</th><th>Баллы</th></tr><tr><td>Правильно сформулированы два аргумента</td><td>2</td></tr><tr><td>Правильно сформулирован только один аргумент</td><td>1</td></tr><tr><td>Аргумент(ы) не сформулирован(ы).<p> ИЛИ Приведены рассуждения общего характера, не соответствующие требованию задания.<p> ИЛИ Ответ неправильный</td><td>0</td></tr><tr><td><i>Максимальный балл</i></td><td>2</td></tr></table>ПояснениеСпрятать пояснение &middot; КритерииСпрятать критерии &middot; Помощь","ans":""},{"id":2160,"tp":3,"kind":"multi","type":"Тип 6","body":"<p>Прочтите отрывок из летописи.<p>&nbsp;</p><p>«В год 6390 (летоисчисление от Сотворения мира). Выступил в поход Олег, взяв с собою много воинов: варягов, чудь, словен, мерю, весь, кривичей, и пришел к Смоленску с кривичами, и принял власть в городе, и посадил в нем своего мужа. Оттуда отправился вниз, и взял Любеч, и также посадил мужа своего. И пришли к горам Киевским, и узнал Олег, что княжат тут Аскольд и Дир. Спрятал он одних воинов в ладьях, а других оставил позади, и сам приступил, неся младенца Игорь. И подплыл к Угорской горе, спрятав своих воинов, и послал к Аскольду и Диру, говоря им, что-де «мы купцы, идем в Греки от Олега и княжича Игоря. Придите к нам, к родичам своим». Когда же Аскольд и Дир пришли, выскочили все остальные из ладей, и сказал Олег Аскольду и Диру: «Не князья вы и не княжеского рода, но я княжеского рода», и показал Игоря: «А это сын Рюрика». И убили Аскольда и Дира, отнесли на гору и погребли Аскольда на горе, которая называется ныне Угорской, где теперь Ольмин двор; на той могиле Ольма поставил церковь святого Николы; а Дирова могила&#8239;&#8239;— за церковью святой Ирины. И сел Олег, княжа, в Киеве, и сказал Олег: «Да будет это мать городам русским». И были у него варяги, и славяне, и прочие, прозвавшиеся русью. Тот Олег начал ставить города и установил дани словенам, и кривичам, и мери, и установил варягам давать дань от Новгорода по 300 гривен ежегодно ради сохранения мира, что и давалось варягам до самой смерти Ярослава».<p>&nbsp;</p><p>Используя отрывок и знания по истории, выберите в приведённом списке верные суждения. Запишите в ответ цифры, под которыми они указаны.<p>&nbsp;</p><p>1.&#8239;&#8239;Олег был первым скандинавским князем, приглашённым на Русь славянскими и финскими племенами.<p>2.&#8239;&#8239;После Олега правил Русью князь Святослав.<p>3.&#8239;&#8239;Олег первым из князей подписал выгодный для Руси договор с Византией.<p>4.&#8239;&#8239;Указанные события относятся к концу IX&#8239;в.<p>5.&#8239;&#8239;Варяги&#8239;&#8239;— наёмные воины из Скандинавии на службе древнерусских князей.<p>6.&#8239;&#8239;Чудь, меря, весь относятся к восточнославянским племенам.","sol":"<b>Пояснение. </b><p>1.&#8239;&#8239;Олег был первым скандинавским князем, приглашённым на Русь славянскими и финскими племенами&#8239;&#8239;— нет, неверно, Олег был русским князем.<p>2.&#8239;&#8239;После Олега правил Русью князь Святослав&#8239;&#8239;— нет, неверно, после Олега правил Игорь.<p>3.&#8239;&#8239;Олег первым из князей подписал выгодный для Руси договор с Византией&#8239;&#8239;— да, верно, 907&#8239;г., 911&#8239;г.<p>4.&#8239;&#8239;Указанные события относятся к концу IX&#8239;в.&#8239;&#8239;— да, верно, в 882&#8239;г. (IX&#8239;в.) Олег объединил Киев и Новгород.<p>5.&#8239;&#8239;Варяги&#8239;&#8239;— наёмные воины из Скандинавии на службе древнерусских князей&#8239;&#8239;— да, верно.<p>6.&#8239;&#8239;Чудь, меря, весь относятся к восточнославянским племенам&#8239;&#8239;— нет, неверно, чудь, меря, весь&#8239;&#8239;— финно-угорские племена.<p>&nbsp;</p><p>Ответ: 345.Ответ: 345ПояснениеСпрятать пояснение &middot; Помощь","ans":"345"},{"id":2161,"tp":2,"kind":"multi","type":"Тип 6","body":"<p>Прочтите отрывок из летописи.<p>&nbsp;</p><p>«В год 6472 (летоисчисление от Сотворения мира). Когда Святослав вырос и возмужал, стал он собирать много воинов храбрых, и быстрым был, словно пардус (гепард), и много воевал. В походах же не возил за собою ни возов, ни котлов, не варил мяса, но, тонко нарезав конину, или зверину, или говядину и зажарив на углях, так ел; не имел он шатра, но спал, постилая потник с седлом в головах,&#8239;&#8239;— такими же были и все остальные его воины, И посылал в иные земли со словами: «Хочу на вас идти». И пошел на Оку реку и на Волгу, и встретил вятичей, и сказал вятичам: «Кому дань даете?» Они же ответили: «Хазарам&#8239;&#8239;— по щелягу (серебряная монета неизвестного достоинства) с сохи даем».<p>В год 6473. Пошел Святослав на хазар. Услышав же, хазары вышли навстречу во главе со своим князем Каганом и сошлись биться, и в битве одолел Святослав хазар, и столицу их и Белую Вежу взял. И победил ясов и касогов.<p>В год 6474. Вятичей победил Святослав и дань на них возложил.<p>В год 6475. Пошел Святослав на Дунай на болгар. И бились обе стороны, и одолел Святослав болгар, и взял городов их 80&#8239;по Дунаю, и сел княжить там в Переяславце, беря дань с греков».<p>&nbsp;</p><p>Используя отрывок и знания по истории, выберите в приведённом списке верные суждения. Запишите в ответ цифры, под которыми они указаны.<p>&nbsp;</p><p>1.&#8239;&#8239;Мать Святослава княгиня Ольга уговорила сына принять православие.<p>2.&#8239;&#8239;Вятичи селились в нижнем течении Днепра.<p>3.&#8239;&#8239;Кроме хазар Святослав окончательно разгромил печенегов.<p>4.&#8239;&#8239;Святославу не удалось закрепиться на Дунае в противоборстве с Византийской империей.<p>5.&#8239;&#8239;Данный текст летописи рассказывает о событиях X&#8239;в.<p>6.&#8239;&#8239;Отцом Святослава был князь Игорь.","sol":"<b>Пояснение. </b><p>1.&#8239;&#8239;Мать Святослава княгиня Ольга уговорила сына принять православие&#8239;&#8239;— нет, неверно, Святослав не принимал православие.<p>2.&#8239;&#8239;Вятичи селились в нижнем течении Днепра&#8239;&#8239;— нет, неверно, вятичи жили в междуречье Оки и Волги.<p>3.&#8239;&#8239;Кроме хазар Святослав окончательно разгромил печенегов&#8239;&#8239;— нет, неверно, окончательно разгромил печенегов Ярослав.<p>4.&#8239;&#8239;Святославу не удалось закрепиться на Дунае в противоборстве с Византийской империей&#8239;&#8239;— да, верно, разгромил хазар, но потерпел поражение в войне с Византией.<p>5.&#8239;&#8239;Данный текст летописи рассказывает о событиях X&#8239;в.&#8239;&#8239;— да, верно, совершал походы в 964−972&#8239;гг.<p>6.&#8239;&#8239;Отцом Святослава был князь Игорь&#8239;&#8239;— да, верно, Святослав&#8239;&#8239;— сын Игоря и Ольги.<p>&nbsp;</p><p>Ответ: 456.Ответ: 456ПояснениеСпрятать пояснение &middot; Помощь","ans":"456"},{"id":2163,"tp":3,"kind":"multi","type":"Тип 6","body":"<p>Прочтите фрагменты «Русской Правды», изложенные в современном переводе:<p>&nbsp;</p><p>1.&#8239;&#8239;Убьет муж мужа, то мстит брат за брата, или сын за отца, или сын брата, или сын сестры; если не будет никто мстить, то 40 гривен за убитого. Если убитый&#8239;&#8239;— русин, или гридин, или купец, или ябедник, или мечник, или же изгой, или словенин, то 40 гривен уплатить за него.<…><p>4.&#8239;&#8239;Если ударить мечом, не вынув его из ножен, или рукоятью меча, то 12 гривен за обиду. <…><p>8.&#8239;&#8239;Если кто вынет меч, а не ударит, то тот платит гривну. <…><p>10. Если холоп бежит и скроется у варяга или у колбяга, а они его в течение трех дней не выведут, а обнаружат на третий день, то господину отобрать своего холопа, а 3 гривны за обиду.<p>11. Если кто поедет на чужом коне без спросу, то уплатить 3 гривны. <…><p>16. Если холоп ударит свободного мужа и убежит в хоромы своего господина и тот начнет его не выдавать, то холопа взять и господин платит за него 12 гривен, а затем, где холопа застанет тот ударенный человек, пусть бьет его.<p>17. А если кто сломает копье, щит или испортит одежду, и испортивший захочет удержать у себя, то взять с него деньгами; а если тот, кто испортил, начнет настаивать (на возвращении испорченной вещи), платить деньгами, сколько стоит вещь.<p>18. Если убьют огнищанина умышленно, то убийце платить за него 80 гривен, а люди не платят; а за княжеского подъездного 80 гривен. <…><p>20. Если убьют огнищанина у клети, у коня, или у стада, или во время кражи коровы, то убить его, как пса; тот же закон и для тиуна.<p>23. А за убитого смерда или холопа 5 гривен. <…><p>&nbsp;</p><p>Используя фрагменты документа и знания по истории, выберите в приведённом списке верные суждения. Запишите в ответ цифры, под которыми они указаны.<p>&nbsp;</p><p>1.&#8239;&#8239;Гривна&#8239;&#8239;— это используемая в Древней Руси арабская монета.<p>2.&#8239;&#8239;Изначальные статьи «Русской Правды» появились в первой четверти XI&#8239;в.<p>3.&#8239;&#8239;Холоп&#8239;&#8239;— представитель полузависимого населения на Руси, попавший в зависимость от заимодавца.<p>4.&#8239;&#8239;Варяг&#8239;&#8239;— воин из народного ополчения.<p>5.&#8239;&#8239;Огнищанин&#8239;&#8239;— представитель старшей дружинной знати, управляющий княжеским двором.<p>6.&#8239;&#8239;Гридин&#8239;&#8239;— княжеский дружинник.","sol":"<b>Пояснение. </b><p>1.&#8239;&#8239;Гривна&#8239;&#8239;— это используемая в Древней Руси арабская монета&#8239;&#8239;— нет, неверно, гривна&#8239;&#8239;— это денежная единица Руси (слиток серебра).<p>2.&#8239;&#8239;Изначальные статьи «Русской Правды» появились в первой четверти XI&#8239;в.&#8239;&#8239;— да, верно, изначальные статьи «Русской Правды» составлены Ярославом Мудрым примерно в 1016&#8239;г.<p>3.&#8239;&#8239;Холоп&#8239;&#8239;— представитель полузависимого населения на Руси, попавший в зависимость от заимодавца&#8239;&#8239;— нет, неверно, холоп&#8239;&#8239;— это раб на Руси.<p>4.&#8239;&#8239;Варяг&#8239;&#8239;— воин из народного ополчения&#8239;&#8239;— нет, неверно, варяги&#8239;&#8239;— норманны, выходцы из Скандинавии.<p>5.&#8239;&#8239;Огнищанин&#8239;&#8239;— представитель старшей дружинной знати, управляющий княжеским двором&#8239;&#8239;— да, верно, согласно «Русской Правде».<p>6.&#8239;&#8239;Гридин&#8239;&#8239;— княжеский дружинник&#8239;&#8239;— да, верно, согласно «Русской Правде».<p>&nbsp;</p><p>Ответ: 256.Ответ: 256ПояснениеСпрятать пояснение &middot; Помощь","ans":"256"},{"id":2164,"tp":4,"kind":"multi","type":"Тип 6","body":"<p>Прочтите отрывок из летописи.<p>&nbsp;</p><p>«В год 6605 (летоисчисление от Сотворения мира). <…> Пришли Святополк, и Владимир, и Давыд Игоревич, и Василько Ростиславич, и Давыд Святославич, и брат его Олег, и собрались на совет в Любече для установления мира, и говорили друг другу: «Зачем губим Русскую землю, сами между собой устраивая распри? А половцы землю нашу несут розно и рады, что между нами идут воины. Да отныне объединимся единым сердцем и будем блюсти Русскую землю, и пусть каждый владеет отчиной своей: Святополк&#8239;&#8239;— Киевом, Изяславовой отчиной, Владимир&#8239;&#8239;— Всеволодовой, Давыд и Олег и Ярослав&#8239;&#8239;— Святославовой, и те, кому Всеволод роздал города: Давыду&#8239;&#8239;— Владимир, Ростиславичам же: Володарю&#8239;&#8239;— Перемышль, Васильку&#8239;&#8239;— Теребовль». И на том целовали крест: «Если отныне кто на кого пойдет, против того будем мы все и крест честной». Сказали все: «Да будет против того крест честной и вся земля Русская». И, попрощавшись, пошли восвояси».<p>&nbsp;</p><p>Используя отрывок и знания по истории, выберите в приведённом списке верные суждения. Запишите в ответ цифры, под которыми они указаны.<p>&nbsp;</p><p>1.&#8239;&#8239;Указанное событие произошло в 1097&#8239;г.<p>2.&#8239;&#8239;Съезд положил начало переходу власти в отдельных княжествах Руси (кроме Киева) по отчинному принципу «от отца к сыну».<p>3.&#8239;&#8239;В данный период времени в Киеве правил сын Ярослава Мудрого «Ярославич» Святополк.<p>4.&#8239;&#8239;Одним из противников княжеского съезда «на устроение мира» был Владимир Всеволодович Мономах.<p>5.&#8239;&#8239;Любеч находился на территории Владимиро-Суздальского княжества.<p>6.&#8239;&#8239;Договорённость участников съезда не остановила в дальнейшем княжеских междоусобиц.","sol":"<b>Пояснение. </b><p>1.&#8239;&#8239;Указанное событие произошло в 1097&#8239;г.&#8239;&#8239;— да, верно, в тексте речь идет о съезде князей в Любече, который состоялся в 1097&#8239;г.<p>2.&#8239;&#8239;Съезд положил начало переходу власти в отдельных княжествах Руси (кроме Киева) по отчинному принципу «от отца к сыну»&#8239;&#8239;— да, верно, на съезде было принято решение&#8239;&#8239;— «пусть каждый держит отчину свою».<p>3.&#8239;&#8239;В данный период времени в Киеве правил сын Ярослава Мудрого «Ярославич» Святополк&#8239;&#8239;— нет, неверно.<p>4.&#8239;&#8239;Одним из противников княжеского съезда «на устроение мира» был Владимир Всеволодович Мономах&#8239;&#8239;— нет, неверно.<p>5.&#8239;&#8239;Любеч находился на территории Владимиро-Суздальского княжества&#8239;&#8239;— нет, неверно.<p>6.&#8239;&#8239;Договорённость участников съезда не остановила в дальнейшем княжеских междоусобиц&#8239;&#8239;— да, верно, это решение не остановило прекращение усобиц и процесс раздробленности.<p>&nbsp;</p><p>Ответ: 126.Ответ: 126ПояснениеСпрятать пояснение &middot; \n                    1 комментарий\n                     &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"126"},{"id":2166,"tp":5,"kind":"multi","type":"Тип 6","body":"<p>Прочтите отрывок из «Повести о разорении Рязани Батыем».<p>&nbsp;</p><p>«В год 6745 (от Сотворения Мира). <…> Пришел на Русскую землю безбожный царь Батый со множеством воинов татарских и стал на реке на Воронеже близ земли Рязанской. И прислал послов непутевых на Рязань к великому князю Юрию Ингваревичу (Игоревичу) Рязанскому, требуя у него десятой доли во всем: во князьях, и во всяких людях, и в остальном. И услышал великий князь Юрий Ингваревич Рязанский о нашествии безбожного царя Батыя, и тотчас послал в город Владимир к благоверному великому князю Георгию Всеволодовичу Владимирскому, прося у него помощи против безбожного царя Батыя или чтобы сам на него пошел. Князь великий Георгий Всеволодович Владимирский и сам не пошел, и помощи не послал, задумав один сразиться с Батыем. И услышал великий князь Юрий Ингваревич Рязанский, что нет ему помощи от великого князя Георгия Всеволодовича Владимирского, и тотчас послал за братьями своими: за князем Давидом Ингваревичем Муромским, и за князем Глебом Ингваревичем Коломенским, и за князем Олегом Красным, и за Всеволодом Пронским, и за другими князьями. И стали совет держать, как утолить нечестивца дарами. И послал сына своего князя Федора Юрьевича Рязанского к безбожному царю Батыю с дарами и мольбами великими, чтобы не ходил войной на Рязанскую землю. И пришел князь Федор Юрьевич на реку на Воронеж к царю Батыю, и принес ему дары, и молил царя, чтоб не воевал Рязанской земли. Безбожный же, лживый и немилосердный царь Батый дары принял и во лжи своей притворно обещал не ходить войной на Рязанскую землю. Но хвалился-грозился повоевать всю Русскую землю. И стал просить у князей рязанских дочерей и сестер к себе на ложе. И некто из вельмож рязанских по зависти донес безбожному царю Батыю, что есть у князя Федора Юрьевича Рязанского княгиня из царского рода и что всех прекраснее она красотой телесною. Царь Батый лукав был и немилостив в неверии своем, распалился в похоти своей и сказал князю Федору Юрьевичу: «Дай мне, княже, изведать красоту жены твоей». Благоверный же князь Федор Юрьевич Рязанский посмеялся и ответил царю: «Не годится нам, христианам, водить к тебе, нечестивому царю, жен своих на блуд. Когда нас одолеешь, тогда и женами нашими владеть будешь». Безбожный царь Батый разъярился и оскорбился и тотчас повелел убить благоверного князя Федора Юрьевича, а тело его велся бросить на растерзание зверям и птицам, и других князей и воинов лучших поубивал». <p>&nbsp;</p><p>Используя отрывок и знания по истории, выберите в приведённом списке верные суждения. Запишите в ответ цифры, под которыми они указаны.<p>&nbsp;</p><p>1.&#8239;&#8239;Вторжение на Русь войск Батыя началось зимой 1237&#8239;г.<p>2.&#8239;&#8239;Вскоре после гибели Рязани удару войск Батыя подверглись города Владимиро-Суздальского княжества.<p>3.&#8239;&#8239;После разгрома Рязани на войско монголо-татар было совершено нападение дружины рязанского боярина Евпатия Коловрата.<p>4.&#8239;&#8239;Двигаясь через Черниговское княжество, отряд монголо-татар с ходу захватил и разграбил Козельск.<p>5.&#8239;&#8239;Автор повести не противопоставляет возвышенный христианский дух рязанского князя «плотским» помыслам завоевателя-язычника.<p>6.&#8239;&#8239;Защитники Новгорода сумели выдержать штурм города войска Батыя.","sol":"<b>Пояснение. </b><p>1.&#8239;&#8239;Вторжение на Русь войск Батыя началось зимой 1237&#8239;г.&#8239;&#8239;— да, верно, речь идет о походе хана Батыя на Русь, который начался в декабре 1237&#8239;г. с нападения на Рязанскую землю.<p>2.&#8239;&#8239;Вскоре после гибели Рязани удару войск Батыя подверглись города Владимиро-Суздальского княжества&#8239;&#8239;— да, верно, разорению подверглось Владимиро-Суздальское княжество.<p>3.&#8239;&#8239;После разгрома Рязани на войско монголо-татар было совершено нападение дружины рязанского боярина Евпатия Коловрата&#8239;&#8239;— да, верно, героем Рязанской земли был Евпатий Коловрат.<p>4.&#8239;&#8239;Двигаясь через Черниговское княжество, отряд монголо-татар с ходу захватил и разграбил Козельск&#8239;&#8239;— нет, неверно, Козельск был разорен в 1238&#8239;г., а Черниговское княжество было разорено в 1239&#8239;г.<p>5.&#8239;&#8239;Автор повести не противопоставляет возвышенный христианский дух рязанского князя «плотским» помыслам завоевателя-язычника&#8239;&#8239;— нет, неверно.<p>6.&#8239;&#8239;Защитники Новгорода сумели выдержать штурм города войска Батыя&#8239;&#8239;— нет, неверно, монголы до Новгорода не дошли 100 верст.<p>&nbsp;</p><p>Ответ: 123.Ответ: 123ПояснениеСпрятать пояснение &middot; Помощь","ans":"123"},{"id":2167,"tp":6,"kind":"multi","type":"Тип 6","body":"<p>Прочтите отрывок из житийной литературы.<p>&nbsp;</p><p>«…Сей князь Александр родился от отца милосердного и человеколюбивого, и более всего&#8239;&#8239;— кроткого, князя великого Ярослава и от матери Феодосии… <…> И красив он был, как никто другой, и голос его&#8239;&#8239;— как труба в народе, лицо его&#8239;&#8239;— как лицо Иосифа, которого египетский царь поставил вторым царем в Египте, сила же его была частью от силы Самсона, и дал ему бог премудрость Соломона, храбрость же его&#8239;&#8239;— как у царя римского Веспасиана, который покорил всю землю Иудейскую…<…> Услышав о такой доблести князя Александра, король страны Римской из северной земли подумал про себя: «Пойду и завоюю землю Александрову». И собрал силу великую, и наполнил многие корабли полками своими, двинулся с огромным войском, пыхая духом ратным. И пришел в Неву, опьяненный безумием, и отправил послов своих, возгордившись, в Новгород к князю Александру, говоря: «Если можешь, защищайся, ибо я уже здесь и разоряю землю твою». Александр же, услышав такие слова, разгорелся сердцем, и вошел в церковь святой Софии, и, упав на колени пред алтарем, начал молиться со слезами: «Боже славный, праведный, боже великий, сильный, боже праведный, сотворивший небо и землю и установивший пределы народам, ты повелел жить, не преступая чужих границ». И, припомнив слова пророка, сказал: «Суди, господи, обидящих меня и огради от борющихся со мною, возьми оружие и щит и встань на помощь мне». И, окончив молитву, он встал, поклонился архиепископу. Архиепископ же был тогда Спиридон, он благословил его и отпустил. Князь же, выйдя из церкви, осушил слезы и начал ободрять дружину свою, говоря: «Не в силе бог, но в правде. Вспомним Песнотворца, который сказал: «Одни с оружием, а другие на конях, мы же имя господа бога нашего призовем; они, поверженные, пали, мы же устояли и стоим прямо». Сказав это, пошел на врагов с малою дружиною, не дожидаясь своего большого войска, но уповая на святую троицу. <…> После того Александр поспешил напасть на врагов в шестом часу дня, и была сеча великая с римлянами, и перебил их князь бесчисленное множество, а на лице самого короля оставил след острого копья своего. Проявили себя здесь шесть храбрых, как он, мужей из полка Александра. Первый&#8239;&#8239;— по имени Гаврило Олексич. Он напал на шнек и, увидев королевича, влекомого под руки, въехал до самого корабля по сходням, по которым бежали с королевичем; преследуемые им схватили Гаврилу Олексича и сбросили его со сходен вместе с конем. Но по божьей милости он вышел из воды невредим, и снова напал на них, и бился с самим воеводою посреди их войска. Второй, по имени Сбыслав Якунович, новгородец. Этот много раз нападал на войско их и бился одним топором, не имея страха в душе своей; и пали многие от руки его, и дивились силе и храбрости его. Третий&#8239;&#8239;— Яков, родом полочанин, был ловчим у князя. Этот напал на полк с мечом, и похвалил его князь. Четвертый&#8239;&#8239;— новгородец, по имени Меша. Этот пеший с дружиною своею напал на корабли и потопил три корабля. Пятый&#8239;&#8239;— из младшей дружины, по имени Сава. Этот ворвался в большой королевский златоверхий шатер и подсек столб шатерный. Полки Александровы, видевши падение шатра, возрадовались…<…> На второй же год после возвращения с победой князя Александра вновь пришли из Западной страны и построили город на земле Александровой. Князь же Александр вскоре пошел и разрушил город их до основания, а их самих&#8239;&#8239;— одних повесил, других с собою увел, а иных, помиловав, отпустил, ибо был безмерно милостив. После победы Александровой, когда победил он короля, на третий год, в зимнее время, пошел он с великой силой на землю немецкую, чтобы не хвастались, говоря: «Покорим себе славянский народ». А был ими уже взят город Псков и наместники немецкие посажены. Он же вскоре изгнал их из Пскова и немцев перебил, а иных связал и город освободил от безбожных немцев, а землю их повоевал и пожег и пленных взял бесчисленное множество, а других перебил. Немцы же, дерзкие, соединились и сказали: «Пойдем, И победим Александра, и захватим его». Когда же приблизились немцы, то&#8239;&#8239;— проведали о них стражи. Князь же Александр приготовился к бою, и пошли они друг против друга, и покрылось озеро Чудское множеством тех и других воинов. Отец Александра, Ярослав, прислал ему на помощь младшего брата Андрея с большою дружиною. Да и у князя Александра было много храбрых воинов, как в древности у Давида-царя, сильных и стойких. Так и мужи Александра исполнились духа ратного, ведь были сердца их как сердца львов, и воскликнули: «О княже наш славный! Ныне пришло нам время положить головы свои за тебя». Князь же Александр воздел руки к небу и сказал: «Суди меня, боже, рассуди распрю мою с народом неправедным и помоги мне, господи, как в древности помог Моисею одолеть Амалика и прадеду нашему Ярославу окаянного Святополка». Была же тогда суббота, и когда взошло солнце, сошлись противники. И была сеча жестокая, и стоял треск от ломающихся копий и звон от ударов мечей, и казалось, что двинулось замерзшее озеро, и не было видно льда, ибо покрылось оно кровью…»<p>&nbsp;</p><p>Используя текст и знания по истории, выберите в приведённом списке верные суждения. Запишите в ответ цифры, под которыми они указаны.<p>&nbsp;</p><p>1.&#8239;&#8239;События, описанные в тексте жития, произошли в XII в.<p>2.&#8239;&#8239;Город, который немецкие рыцари построили на захваченной «земле Александровой», назывался Копорье.<p>3.&#8239;&#8239;За заслуги перед Новгородом бояре провозгласили князя Александра Ярославича Новгородским князем «на все времена».<p>4.&#8239;&#8239;В сражении на реке Неве войско князя Александра Ярославича сразилось с войском датчан.<p>5.&#8239;&#8239;Одним из описанных в житии ратных деяний князя Александра Ярославича была победа над немцами на льду Чудского озера.<p>6.&#8239;&#8239;В сражении против немецких рыцарей принимала участие дружина из Владимиро-Суздальского княжества.","sol":"<b>Пояснение. </b><p>1.&#8239;&#8239;События, описанные в тексте жития, произошли в XII&#8239;в.&#8239;&#8239;— нет, неверно, события относятся к XIII&#8239;в.<p>2.&#8239;&#8239;Город, который немецкие рыцари построили на захваченной «земле Александровой», назывался Копорье&#8239;&#8239;— да, верно, немецкие рыцари построили крепость Копорье.<p>3.&#8239;&#8239;За заслуги перед Новгородом бояре провозгласили князя Александра Ярославича Новгородским князем «на все времена»&#8239;&#8239;— нет, неверно, после победы над шведами князь Александр Невский ушел из Новгорода, поссорившись с новгородцами.<p>4.&#8239;&#8239;В сражении на реке Неве войско князя Александра Ярославича сразилось с войском датчан&#8239;&#8239;— нет, неверно, на реке Неве в 1240&#8239;г. князь Александр Ярославич одержал победу над шведами.<p>5.&#8239;&#8239;Одним из описанных в житии ратных деяний князя Александра Ярославича была победа над немцами на льду Чудского озера&#8239;&#8239;— да, верно, в 1242&#8239;г. русские войска под руководством Александра Невского разбили немецких рыцарей на льду Чудского озера.<p>6.&#8239;&#8239;В сражении против немецких рыцарей принимала участие дружина из Владимиро-Суздальского княжества&#8239;&#8239;— да, верно.<p>&nbsp;</p><p>Ответ: 256.Ответ: 256ПояснениеСпрятать пояснение &middot; Помощь","ans":"256"},{"id":10077,"tp":2,"kind":"multi","type":"Тип 6","body":"<p>Прочтите отрывок из летописи.<p>&nbsp;</p><p>«В год 6370. И изгнали варягов за море, и не дали им дани, и начали сами собой владеть, и не было среди них правды, и встал род на род, и была у них усобица, и стали воевать друг с другом. И сказали: «Поищем сами себе князя, который бы владел нами и рядил по ряду и по закону». Пошли за море к варягам, к руси. Те варяги назывались русью, как другие называются шведы, а иные&#8239;&#8239;— норманны и англы, а ещё иные&#8239;&#8239;— готы, вот так и эти. Сказали руси чудь, славяне, кривичи и весь: «Земля наша велика и обильна, а порядка в ней нет. Приходите княжить и владеть нами». И избрались трое братьев со своими родами, и взяли с собой всю русь, и пришли прежде всего к славянам. И поставили город Ладогу. И сел старший… в Ладоге, а другой&#8239;&#8239;— Синеус&#8239;&#8239;— на Белом озере, а третий&#8239;&#8239;— Трувор&#8239;&#8239;— в Изборске. И от тех варягов прозвалась Русская земля. Через два года умерли Синеус и брат его Трувор. И принял всю власть один… [князь], и пришёл к Ильменю, и поставил город над Волховом… и сел тут княжить, и стал раздавать мужам своим волости и города ставить». <p>&nbsp;</p><p>Используя отрывок и знания по истории, выберите в приведённом списке верные суждения. <i>Цифры укажите в порядке возрастания.</i><p>&nbsp;</p><p>1.&#8239;&#8239;В отрывке упомянут восточнославянский племенной союз, занимавший территорию по среднему течению реки Днепра, с центром в г.&#8239;Киеве.<p>2.&#8239;&#8239;Автор излагает в отрывке одну из существующих в настоящее время версий происхождения названия нашей страны.<p>3.&#8239;&#8239;В отрывке упомянуты финно-угорские племена.<p>4.&#8239;&#8239;В отрывке приведено название племенного союза восточных славян, поднявшего восстание, в ходе которого был убит сын князя, упомянутого в тексте.<p>5.&#8239;&#8239;Автор излагает в данном отрывке одну из существующих версий основания г.&#8239;Владимира.<p>6.&#8239;&#8239;В отрывке описано событие, датируемое по современному летосчислению 862&#8239;г.","sol":"<b>Пояснение. </b><p>1.&#8239;&#8239;В отрывке упомянут восточнославянский племенной союз, занимавший территорию по среднему течению реки Днепра, с центром в г.&#8239;Киеве&#8239;&#8239;— нет, неверно, полян здесь нет.<p>2.&#8239;&#8239;Автор излагает в отрывке одну из существующих в настоящее время версий происхождения названия нашей страны&#8239;&#8239;— да, верно.<p>3.&#8239;&#8239;В отрывке упомянуты финно-угорские племена&#8239;&#8239;— да, верно, чудь и весь.<p>4.&#8239;&#8239;В отрывке приведено название племенного союза восточных славян, поднявшего восстание, в ходе которого был убит сын князя, упомянутого в тексте&#8239;&#8239;— нет, неверно, древлян нет.<p>5.&#8239;&#8239;Автор излагает в данном отрывке одну из существующих версий основания г.&#8239;Владимира&#8239;&#8239;— нет, неверно, это про Новгород.<p>6.&#8239;&#8239;В отрывке описано событие, датируемое по современному летосчислению 862&#8239;г.&#8239;&#8239;— да, верно.<p>&nbsp;</p><p>Ответ: 236.Ответ: 236Источник: ЕГЭ по истории 29.03.2017. Досрочная волнаПояснениеСпрятать пояснение &middot; Помощь","ans":"236"},{"id":25887,"tp":3,"kind":"multi","type":"Тип 6","body":"<p>Прочтите отрывок из летописи.<p>&nbsp;</p><p>«Выступил в поход [князь] _____________, взяв с собою много воинов: варягов, чудь, словен, мерю, весь, кривичей, и пришёл к Смоленску с кривичами, и принял власть в городе, и посадил в нём своего мужа. Оттуда отправился вниз, и взял Любеч, и также посадил мужа своего. И пришли к горам Киевским, и узнал [князь], что княжат тут Аскольд и Дир. Спрятал он одних воинов в ладьях, а других оставил позади, и сам приступил, неся младенца Игоря. И подплыл к Угорской горе, спрятав своих воинов, и послал к Аскольду и Диру, говоря им, что-де «мы купцы, идём в Греки от Олега и княжича Игоря. Придите к нам, к родичам своим». Когда же Аскольд и Дир пришли, выскочили все остальные из ладей, и сказал [князь] __________________ Аскольду и Диру: «Не князья вы и не княжеского рода, но я княжеского рода», и показал Игоря: «А это сын Рюрика». И убили Аскольда и Дира…» <p>&nbsp;</p><p>Используя отрывок и знания по истории, выберите в приведённом списке верные суждения. Запишите в таблицу цифры, под которыми они указаны.<p>&nbsp;</p><p>1.&#8239;&#8239;Князь, чьё имя пропущено в тексте,&#8239;&#8239;— Владимир Святославович.<p>2.&#8239;&#8239;События, описываемые в отрывке, относятся к IX&#8239;в.<p>3.&#8239;&#8239;Князь, имя которого пропущено в тексте, совершил поход на Византию, в конце которого, согласно легенде, прибил свой щит к воротам Царьграда.<p>4.&#8239;&#8239;Родство, о котором говорится в отрывке, заключается в том, что все главные участники событий&#8239;&#8239;— хазары.<p>5.&#8239;&#8239;Князь, имя которого пропущено в отрывке, оправдывает свои действия своим княжеским происхождением.<p>6.&#8239;&#8239;В том же столетии, к которому относятся описываемые события, была принята «Русская Правда».","sol":"<b>Пояснение. </b><p>1.&#8239;&#8239;Князь, чьё имя пропущено в тексте,&#8239;&#8239;— Владимир Святославович. <i>Нет, неверно.</i> Это князь Олег Вещий.<p>2.&#8239;&#8239;События, описываемые в отрывке, относятся к IX&#8239;в. <i>Да, верно.</i> А именно к 882&#8239;году.<p>3.&#8239;&#8239;Князь, имя которого пропущено в тексте, совершил поход на Византию, в конце которого, согласно легенде, прибил свой щит к воротам Царьграда. <i>Да, верно.</i> Он совершал походы в 907 и 911&#8239;гг. После победы в первом походе Вещий Олег прибил свой щит на вратах Царьграда. <p>4.&#8239;&#8239;Родство, о котором говорится в отрывке, заключается в том, что все главные участники событий&#8239;&#8239;— хазары. <i>Нет, неверно.</i> Они были варягами (скандинавами).<p>5.&#8239;&#8239;Князь, имя которого пропущено в отрывке, оправдывает свои действия своим княжеским происхождением. <i>Да, верно.</i> Это вытекает из отрывка: «Не князья вы и не княжеского рода, но я княжеского рода».<p>6.&#8239;&#8239;В том же столетии, к которому относятся описываемые события, была принята «Русская правда». <i>Нет, неверно.</i> Она была принята в XII&#8239;веке, а не в IX.<p>&nbsp;</p><p>Ответ: 235.Ответ: 235ПояснениеСпрятать пояснение &middot; Помощь","ans":"235"},{"id":26046,"tp":2,"kind":"multi","type":"Тип 6","body":"<p>Прочтите отрывок из летописи.<p>&nbsp;</p><p>«Пришли печенеги впервые на Русскую землю, а [...] был в Переяславце, и затворилась княгиня Ольга с внуками своими, Ярополком, Олегом и Владимиром в городе Киеве. И обступили печенеги город в силе великой, бесчисленное множество их около города, и нельзя было из города выйти, ни вести князю послать. Изнемогали люди от голода и жажды. Собрались люди на другой стороне Днепра в лодках. Они стояли на другой стороне, и нельзя было ни одному из них войти в Киев, ни из города выйти к ним. И закручинились люди в городе и сказали: «Нет ли кого, кто мог бы на ту сторону дойти и сказать им: если кто не придёт к нам утром на выручку, придётся нам сдаться печенегам».<p>&nbsp;</p><p>Используя отрывок и знания по истории, выберите в приведённом списке верные суждения. Запишите в таблицу цифры, под которыми они указаны.<p>&nbsp;</p><p>1.&#8239;&#8239;Имя князя, пропущенное в тексте документа,&#8239;&#8239;— Святослав.<p>2.&#8239;&#8239;Внук князя, чье имя пропущено в тексте, нанесет поражение печенегам, после которого они больше не будут представлять опасности для Руси.<p>3.&#8239;&#8239;Осада Киева, описанная в тексте документа, завершилась сдачей города печенегам.<p>4.&#8239;&#8239;Согласно документу, это было уже второе нашествие печенегов на Русь.<p>5.&#8239;&#8239;В правление князя, чье имя пропущено в тексте, Русь приняла христианство.<p>6.&#8239;&#8239;Княгиня, упоминаемая в тексте, провела налоговую реформу.","sol":"<b>Пояснение. </b><p>1.&#8239;&#8239;Имя князя, пропущенное в тексте документа,&#8239;&#8239;— Святослав. <i>Да, верно. </i>В тексте упоминается его мать (Ольга) и дети (Ярополк, Олег и Владимир).<p>2.&#8239;&#8239;Внук князя, чье имя пропущено в тексте, нанесет поражение печенегам, после которого они больше не будут представлять опасности для Руси.<i> Да, верно. </i>Им будет Ярослав Мудрый в 1036&#8239;г.<p>3.&#8239;&#8239;Осада Киева, описанная в тексте документа, завершилась сдачей города печенегам. <i>Нет, неверно. </i>Святослав прибыл с дружиной под Киев и нанес поражение печенегам. <p>4.&#8239;&#8239;Согласно документу, это было уже второе нашествие печенегов на Русь. <i>Нет, неверно. </i>Согласно документу: «Пришли печенеги <i>впервые</i> на Русскую землю».<p>5.&#8239;&#8239;В правление князя, чье имя пропущено в тексте, Русь приняла христианство. <i>Нет, неверно. </i>Христианство было принято при его сыне Владимире. <p>6.&#8239;&#8239;Княгиня, упоминаемая в тексте, провела налоговую реформу. <i>Да, верно. </i>В 945&#8239;году она ввела уроки и погосты. <p>&nbsp;</p><p>Ответ: 126.Ответ: 126Источник: ЕГЭ по истории 13.07.2020. Основная волна. ЦентрПояснениеСпрятать пояснение &middot; Помощь","ans":"126"},{"id":33731,"tp":3,"kind":"multi","type":"Тип 6","body":"<p>Прочтите отрывок из записок иностранца.<p>&nbsp;</p><p>«С медными деньгами ежедневно было хуже и хуже. В начале сего года 5 или 6 шли к одному серебром, а когда я приехал в страну&#8239;&#8239;— всего по 3. <...><p>Этой зимой боярин Борис Иванович Морозов умер бездетным, оставив царю огромное состояние и много денег. <...><p>Рано утром, когда я обучал полк на поле у Новоспасского монастыря, к нам явился полковник Крофорд, сообщил, что в городе великое смятение, и дал приказ выступить к Таганским воротам. Я осведомился, где [царь], и, узнав, что он в Коломенском, советовал идти туда. <...><p>Мятежники толпою вышли из Серпуховских ворот. Их было около 4 или 5 тысяч, без оружия, лишь у некоторых имелись дубины и палки. Они притязали на возмещение [убытков] за медные деньги, соль и многое другое.<p>С сею целью в разных местах города были расклеены листы, а один стряпчий... читал лист, содержащий их жалобы, имена некоторых особ, коих они мнили виновными в злоупотреблениях, и призыв ко всем идти к царю и добиваться возмещения, а также голов дурных советников».<p>&nbsp;</p><p>Используя отрывок и знания по истории, выберите в приведённом списке верные суждения. Запишите в таблицу цифры, под которыми они указаны.<p>&nbsp;</p><p>1.&#8239;&#8239;Описываемые в отрывке события получили в истории название «Медный бунт».<p>2.&#8239;&#8239;Упоминаемый в отрывке царь&#8239;&#8239;— Михаил Фёдорович.<p>3.&#8239;&#8239;Автор записок указывает на то, что восставшие были хорошо вооружены, в том числе огнестрельным оружием.<p>4.&#8239;&#8239;Автор записок указывает, что одним из намерений восставших было наказание за сложившееся положение приближенных царя.<p>5.&#8239;&#8239;В царствование, в которое происходили описываемые в отрывке события, в России произошёл церковный раскол.<p>6.&#8239;&#8239;Царь, о котором говорится в отрывке, был первым представителем своей династии на престоле.","sol":"<b>Пояснение. </b><p>1.&#8239;&#8239;Описываемые в отрывке события получили в истории название «Медный бунт». <i>Да, верно. </i>Он произошел в 1662&#8239;г.<p>2.&#8239;&#8239;Упоминаемый в отрывке царь&#8239;&#8239;— Михаил Фёдорович. <i>Нет, неверно. </i>Это Алексей Михайлович.<p>3.&#8239;&#8239;Автор записок указывает на то, что восставшие были хорошо вооружены, в том числе огнестрельным оружием. <i>Нет, неверно.</i> Автор говорит: «Их было около 4 или 5 тысяч, без оружия, лишь у некоторых имелись дубины и палки».<p>4.&#8239;&#8239;Автор записок указывает, что одним из намерений восставших было наказание за сложившееся положение приближенных царя. <i>Да, верно. </i>Согласно тексту источника: «а один стряпчий... читал лист, содержащий их жалобы, имена некоторых особ, коих они мнили виновными в злоупотреблениях, и призыв ко всем идти к царю и добиваться возмещения, а также голов дурных советников».<p>5.&#8239;&#8239;В царствование, в которое происходили описываемые в отрывке события, в России произошёл церковный раскол. <i>Да, верно. </i>С 1653&#8239;г. начался церковный раскол, а Алексей Михайлович правил с 1645&#8239;по 1676&#8239;гг.<p>6.&#8239;&#8239;Царь, о котором говорится в отрывке, был первым представителем своей династии на престоле. <i>Нет, неверно.</i> Он был вторым в династии Романовых. <p>&nbsp;</p><p>Ответ: 145.Ответ: 145ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"145"},{"id":53925,"tp":3,"kind":"match","type":"Тип 6","body":"<p>Прочтите отрывок из исторического источника.<p>&nbsp;</p><p>«... Сказал Святослав матери своей и боярам своим: \"Не любо мне сидеть в Киеве, хо чу жить в Переяславце на Дунае&#8239;&#8239;— ибо там середина земли моей, туда стекаются все блага: из Греческой земли&#8239;&#8239;— золото, паволоки, вина, различные плоды, из Чехии и из Венгрии&#8239;&#8239;— серебро и кони, из Руси же&#8239;&#8239;— меха и воск, мёд и рабы\". Отвечала ему Ольга: \"Видишь&#8239;&#8239;— я больна; куда хочешь уйти от меня?\"&#8239;&#8239;— ибо она уже разболелась. И сказала: \"Когда похоронишь меня,&#8239;&#8239;— отправляйся куда захочешь\". Через три дня Ольга умерла, и плакали по ней плачем великим сын её, и внуки её, и все люди, и понесли, и похоронили её на вы бранном месте, Ольга же завещала не совершать по ней тризны, так как имела при себе священника&#8239;&#8239;— тот и похоронил блаженную Ольгу. <...> Святослав посадил Ярополка в Киеве, а Олега у древлян. В то время пришли новгородцы, прося себе князя: \"Если не пойдёте к нам, то сами добудем себе князя\". И сказал им Святослав: \"А кто бы пошёл к вам?\". И отказались Ярополк и Олег. И сказал Добрыня: \"Просите Владимира\"... И сказали новгородцы Святославу: \"Дай нам Влади мира\". Он же ответил им: \"Вот он вам\". И взяли к себе новгородцы Владимира».<p>&nbsp;</p><p>Используя отрывок и знания по истории, выберите в приведённом списке верные суждения. Запишите в таблицу цифры, под которыми они указаны.<p>&nbsp;</p><p>1)&#8239;&#8239;Источником, из которого приведён данный отрывок, является «Повесть временных лет». <p>2)&#8239;&#8239;События, о которых говорится в отрывке, произошли в IX веке. <p>3)&#8239;&#8239;Несмотря на завещание Ольги, её похоронили в соответствии с языческими традициями. <p>4)&#8239;&#8239;Святослав действительно перенёс столицу из Киева в город, упомянутый в отрывке, на 10 лет. <p>5)&#8239;&#8239;Автор пишет, что новгородцы требовали от Святослава прислать к ним князя, предупреждая, что в случае отказа Святослава они самостоятельно призовут князя в Новгород. <p>6)&#8239;&#8239;Сразу после смерти Святослава киевским князем стал тот из его сыновей, которого сам Святослав при жизни посадил в Киеве.","sol":"<b>Пояснение. </b><p>1.&#8239;&#8239;Источником, из которого приведён данный отрывок, является «Повесть временных лет»&#8239;&#8239;— <i>да, верно, это цитата из «Повести временных лет»</i>.<p>2.&#8239;&#8239;События, о которых говорится в отрывке, произошли в IX веке&#8239;&#8239;— <i>нет, неверно, это вторая половина X века, когда проходили походы князя Святослава Игоревича. </i><p>3.&#8239;&#8239;Несмотря на завещание Ольги, её похоронили в соответствии с языческими традициями. <i>Нет, неверно, согласно тексту: «Ольга же завещала не совершать по ней тризны, так как имела при себе священника  — тот и похоронил блаженную Ольгу».</i><p>4.&#8239;&#8239;Святослав действительно перенёс столицу из Киева в город, упомянутый в отрывке, на 10&#8239;лет&#8239;&#8239;— <i>нет, неверно, он потерпел поражение в войне с византийцами и вынужден был освободить завоеванные земли на Дунае.</i><p>5.&#8239;&#8239;Автор пишет, что новгородцы требовали от Святослава прислать к ним князя, предупреждая, что в случае отказа Святослава они самостоятельно призовут князя в Новгород&#8239;&#8239;— <i>да, верно, согласно тексту: «В то время пришли новгородцы, прося себе князя: \"Если не пойдёте к нам, то сами добудем себе князя\"».</i><p>6.&#8239;&#8239;Сразу после смерти Святослава киевским князем стал тот из его сыновей, которого сам Святослав при жизни посадил в Киеве. <i>Да, верно, Ярополк Святославич правил с&#8239;972 по 980&#8239;гг. в Киеве.</i><p>&nbsp;</p><p>Ответ: 156.Ответ: 156Источник: ЕГЭ по истории 05.06.2023. Основная волна. Вариант 2ПояснениеСпрятать пояснение &middot; Помощь","ans":"156"},{"id":53967,"tp":5,"kind":"multi","type":"Тип 6","body":"<p>Прочтите отрывок из летописи.<p>&nbsp;</p><p>И вот однажды этот треклятый пришел со множеством печенегов, и Ярослав, собрав войско, вышел навстречу ему на Альту и стал в том месте, где был убит святой Борис. И воздев руки к небу, сказал: «Кровь брата моего, как прежде Авелева, вопиет к Тебе, Владыка. И Ты отомсти за него и, как братоубийцу Каина, повергни Святополка в ужас и трепет. Молю Тебя, Господи,&#8239;&#8239;— да будут отомщены братья мои! Если телом вы отошли отсюда, то благодатию живы и предстоите перед Господом и своей молитвой поможете мне!»<p>После этих слов сошлись противники друг с другом, и покрылось поле Альтское множеством воинов. И принял отмщение от Господа: довел Святополка до гибели охвативший его недуг, и по смерти&#8239;&#8239;— муку вечную. И так потерял обе жизни: здесь не только княжения, но и жизни лишился, а там не только царства небесного и с ангелами пребывания не получил, но мукам и огню был предан.<p>И с тех пор прекратились усобицы в русской земле, а Ярослав принял всю землю Русскую. И начал он расспрашивать о телах святых&#8239;&#8239;— где и как похоронены? И о святом Борисе поведали ему, что похоронен в Вышгороде. А о святом Глебе не все знали, что у Смоленска был убит. И тогда рассказали Ярославу, что слышали от приходящих оттуда: как видели прохожие свет и свечи в пустынном месте. И, услышав это, Ярослав послал к Смоленску священников разузнать, в чем дело, говоря: «Это брат мой». И нашли его, где были видения, и, придя туда с крестами и свечами и с кадилами, торжественно положили Глеба в ладью и, возвратившись, похоронили его в Вышгороде, где лежит тело преблаженного Бориса: раскопав землю, тут и Глеба положили с подобающим почетом.<p>И не знали многие о лежащих тут мощах святых Бориса и Глеба, но как говорил Господь: «Не может укрыться город, стоящий на верху горы, и, зажегши свечу, не ставят ее под спудом, но на подсвечнике выставляют, чтобы светила всем». Так и этих святых страстотерпцев поставил Бог светить в мире, многочисленными чудесами сиять в великой русской земле, где многие страждущие исцеляются: слепые прозревают, хромые бегают быстрее серны, горбатые выпрямляются.<p>&nbsp;</p><p>Используя отрывок и знания по истории, выберите в приведённом списке верные суждения. Запишите в таблицу цифры, под которыми они указаны.<p>&nbsp;</p><p>1)&#8239;&#8239;В тексте упоминается православная традиция поклоняться святым мощам.<p>2)&#8239;&#8239;Автор текста сочувствует судьбе Святополка.<p>3)&#8239;&#8239;Упомянутые в тексте Борис и Глеб были сыновьями Владимира Святого.<p>4)&#8239;&#8239;События, о которых идет речь в тексте, происходили в XI в.<p>5)&#8239;&#8239;Упоминаемый в тексте кочевой народ принимал участие в сражении против монгольского войска. на реке Калке<p>6)&#8239;&#8239;В отрывке описывается сражение, длившееся несколько дней.","sol":"<b>Пояснение. </b><p>1.&#8239;&#8239;В тексте упоминается православная традиция поклоняться святым мощам&#8239;&#8239;— <i>да, верно, согласно тексту: «И не знали многие о лежащих тут мощах святых Бориса и Глеба, но как говорил Господь: «Не может укрыться город, стоящий на верху горы, и, зажегши свечу, не ставят ее под спудом, но на подсвечнике выставляют, чтобы светила всем». Так и этих святых страстотерпцев поставил Бог светить в мире, многочисленными чудесами сиять в великой русской земле, где многие страждущие исцеляются: слепые прозревают, хромые бегают быстрее серны, горбатые выпрямляются.»</i><p>2.&#8239;&#8239;Автор текста сочувствует судьбе Святополка&#8239;&#8239;— <i>нет, неверно, он сравнивает его с библейским Каином, убившим своего брата.</i><p>3.&#8239;&#8239;Упомянутые в тексте Борис и Глеб были сыновьями Владимира Святого&#8239;&#8239;— <i>да, верно, они были русскими князьями, сыновьями киевского великого князя Владимира Святославича.</i><p>4.&#8239;&#8239;События, о которых идет речь в тексте, происходили в XI&#8239;в.&#8239;&#8239;— <i>да, верно, в тексте описана междоусобная борьба, вспыхнувшая в 1015&#8239;году после смерти их отца, в ходе которой Борис и Глеб были убиты своим старшим братом Святополком. Борис и Глеб стали первыми русскими святыми, их канонизировали в лике мучеников-страстотерпцев, сделав их покровителями Русской земли и «небесными помощниками» русских князей.</i><p>5.&#8239;&#8239;Упоминаемый в тексте кочевой народ принимал участие в сражении против монгольского войска на реке Калке&#8239;&#8239;— <i>нет, неверно, в тексте упомянуты печенеги, а на калке были половцы.</i><p>6.&#8239;&#8239;В отрывке описывается сражение, длившееся несколько дней&#8239;&#8239;— <i>нет, неверно.</i><p>&nbsp;</p><p>Ответ: 134.Ответ: 134Источник: ЕГЭ по истории 05.06.2023. Основная волна. Вариант 4ПояснениеСпрятать пояснение &middot; Помощь","ans":"134"},{"id":55336,"tp":2,"kind":"multi","type":"Тип 6","body":"<p>Прочтите отрывок из летописи.<p>&nbsp;</p><p>«В тот год сказала дружина [князю]: „Отроки Свенельда изоделись оружием и одеждой, а мы наги. Пойдём, князь, с нами за данью, и себе добудешь, и нам“. И послушал их [князь]&#8239;&#8239;— пошёл к древлянам за данью и прибавил к прежней дани новую, и творили насилие над ними мужи его. Взяв дань, пошёл он в свой город. Когда же шёл он назад,&#8239;&#8239;—поразмыслив, сказал своей дружине: „Идите с данью домой, а я возвращусь и похожу ещё“. И отпустил дружину, а сам с малой частью дружины вернулся, желая большего богатства. Древляне же, услышав, что идёт снова, держали совет с князем своим Малом: „Если повадится волк к овцам, то вынесет всё стадо, пока не убьют его; так и этот: если не убьём его, то всех нас погубит“. И послали к нему, говоря: „Зачем идёшь опять? Забрал уже всю дань“. И не послушал их [князь]; и …, убили [князя] и дружинников его».<p>&nbsp;</p><p>Используя отрывок и знания по истории, выберите в приведённом списке верные суждения.<p>Запишите цифры, под которыми они указаны.<p>&nbsp;</p><p>1)&#8239;&#8239;События, описываемые в отрывке, происходили в девятом веке.<p>2)&#8239;&#8239;Князь, о гибели которого говорится в тексте,&#8239;&#8239;— Святослав Игоревич.<p>3)&#8239;&#8239;Столицей союза племён, упоминаемого в тексте, был Чернигов.<p>4)&#8239;&#8239;В летописи описывается давление дружины на князя при решении о сборе дани.<p>5)&#8239;&#8239;Князь, о гибели которого говорится в тексте, прославился разгромом Хазарского каганата.<p>6)&#8239;&#8239;Система сбора дани, описываемая в тексте, называется полюдье.","sol":"<b>Пояснение. </b><p>1)&#8239;&#8239;События, описываемые в отрывке, происходили в девятом веке. <i>Нет, неверно, это 945 год, то есть X век.</i><p>2)&#8239;&#8239;Князь, о гибели которого говорится в тексте,&#8239;&#8239;— Святослав Игоревич. <i>Нет, неверно, это Игорь Рюрикович (Игорь Старый).</i><p>3)&#8239;&#8239;Столицей союза племён, упоминаемого в тексте, был Чернигов. <i>Нет, неверно, это Искоростень.</i><p>4)&#8239;&#8239;В летописи описывается давление дружины на князя при решении о сборе дани. <i>Да, верно, согласно тексту: «В тот год сказала дружина [князю]: «Отроки Свенельда изоделись оружием и одеждой, а мы наги. Пойдём, князь, с нами за данью, и себе добудешь, и нам».</i><p>5)&#8239;&#8239;Князь, о гибели которого говорится в тексте, прославился разгромом Хазарского каганата. <i>Нет, неверно, его разгромит его сын, Святослав Игоревич.</i><p>6)&#8239;&#8239;Система сбора дани, описываемая в тексте, называется полюдье. <i>Да, верно, полюдьем назывался сбор дани со славянских и финно-угорских племён, а затем с населения Древнерусского государства князьями и их дружиной.</i><p>&nbsp;</p><p>Ответ: 46.Ответ: 46ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"46"},{"id":58502,"tp":2,"kind":"multi","type":"Тип 6","body":"<p>Прочтите отрывок из записей А.&#8239;А.&#8239;Валентинова. <p>&nbsp;</p><p>«Заднепровская операция была последней операцией, предпринятой по инициативе главного командования. <p>С момента её печального завершения инициатива окончательно переходила в руки противника, почти открыто стягивающего свои силы к границам северной Таврии для решительного боя за обладание Крымом. <p>Разведывательные сводки каждый день приносят сведения о появлении у противника новых и новых резервов, переброшенных с Польского фронта. <p>Обстановка с каждым лишним днём становится всё более и более серьёзной. <p>Самим генералом Врангелем эта обстановка была обрисована в беседе с представителями Крымской печати вечером&#8239;22 октября, то есть ровно за четыре дня до катастрофы. Воспроизводим её от начала до конца дословно по газете «Военный голос» (от&#8239;23 октября, №163), где в этот день напечатано: <p>«Главнокомандующий в беседе с представителями Севастопольской печати по поводу последних событий на фронте сообщил следующее: После заключения [перемирия] с Польшей большевики получили возможность все свои силы бросить на нас и вот, как вы знаете, уже три месяца идёт лозунг: «Все на Врангеля!». <p>&nbsp;</p><p>Используя отрывок и знания по истории, выберите в приведённом списке верные суждения. <p>&nbsp;</p><p>Запишите в таблицу цифры, под которыми они указаны.<p>&nbsp;</p><p>1)&#8239;&#8239;Ситуация, описываемая в отрывке, относится к периоду Гражданской войны в России.<p>2)&#8239;&#8239;В том же году, к которому относятся события, описываемые в отрывке, была принята первая советская конституция.<p>3)&#8239;&#8239;Главнокомандующий, о котором говорится в тексте, был расстрелян после попадания в плен к противнику.<p>4)&#8239;&#8239;Участником событий, охарактеризованных автором как надвигающаяся «катастрофа», был М.&#8239;В.&#8239;Фрунзе.<p>5)&#8239;&#8239;Перемирие с Польшей, о котором говорится в отрывке, закончилось подписанием мира, по которому полякам доставалась западная часть Украины.<p>6)&#8239;&#8239;Автор отмечает, что после Заднепровской операции противник овладел стратегической инициативой.","sol":"<b>Пояснение. </b><p>1)&#8239;&#8239;Ситуация, описываемая в отрывке, относится к периоду Гражданской войны в России&#8239;&#8239;— да, верно.<p>2)&#8239;&#8239;В том же году, к которому относятся события, описываемые в отрывке, была принята первая советская конституция&#8239;&#8239;— нет, Конституция РСФСР 1918 года была принята раньше, а события относятся к 1920 году.<p>3)&#8239;&#8239;Главнокомандующий, о котором говорится в тексте, был расстрелян после попадания в плен к противнику&#8239;&#8239;— нет, П.&#8239;Н.&#8239;Врангель эмигрировал и не был расстрелян.<p>4)&#8239;&#8239;Участником событий, охарактеризованных автором как надвигающаяся «катастрофа», был М.&#8239;В.&#8239;Фрунзе&#8239;&#8239;— да, верно.<p>5)&#8239;&#8239;Перемирие с Польшей, о котором говорится в отрывке, закончилось подписанием мира, по которому полякам доставалась западная часть Украины&#8239;&#8239;— да, верно.<p>6)&#8239;&#8239;Автор отмечает, что после Заднепровской операции противник овладел стратегической инициативой&#8239;&#8239;— да, верно.<p>&nbsp;</p><p>Ответ: 1456.Ответ: 1456Источник: СтатГрад: Тренировочная работа 26.02.2025. Вариант ИС2410402ПояснениеСпрятать пояснение &middot; Помощь","ans":"1456"},{"id":58934,"tp":2,"kind":"multi","type":"Тип 6","body":"<p>Прочтите отрывок из договора. <p>&nbsp;</p><p>«Список с договора, заключённого при царях Романе, Константине и Стефане, христолюбивых владыках. Мы от рода Русского послы и купцы, Ивор, посол Игорев, великого князя Русского, и общие послы: Вуфаст от Святослава, сына Игорева, Искусеви от Ольги княгини... И им поручено возобновить старый мир, нарушенный уже много лет ненавидящим добро и враждолюбцем дьяволом, и утвердить любовь между греками и русскими.  <p>И великий князь наш Игорь, и князья, и бояре его, и все русские послали нас к Роману, и к Константину, и к Стефану, к великим царям Греческим, утвердить дружбу с самими царями и со всем боярством и со всеми людьми греческими... И если кто из русских замыслит разрушить эту дружбу, то крещённые из них да примут за то месть от бога вседержителя, и осуждение на погибель вечную, а некрещённые да не примут помощи от бога и от Перуна, да не защитятся они щитами своими, да будут посечены мечами своими». <p>&nbsp;</p><p>Используя отрывок и знания по истории, выберите в приведённом списке верные суждения. <p>&nbsp;</p><p>Запишите в таблицу цифры, под которыми они указаны.<p>&nbsp;</p><p>1)&#8239;&#8239;Данный договор был заключён в&#8239;960-&#8288;е&#8239;гг.<p>2)&#8239;&#8239;Князь, от имени которого выступали русские послы, был первым, кто объединил под своей властью Новгород и Киев.<p>3)&#8239;&#8239;Столицу государства, с которым Русь заключила данный договор, в русских летописях называли Царьградом.<p>4)&#8239;&#8239;Князь, от имени которого выступали русские послы, погиб в результате восстания подвластных племен.<p>5)&#8239;&#8239;Славянский бог, упоминаемый в отрывке, считался богом Солнца.<p>6)&#8239;&#8239;Текст договора свидетельствует о том, что среди русских к моменту его заключения уже были христиане.","sol":"<b>Пояснение. </b><p>1)&#8239;&#8239;Данный договор был заключён в&#8239;960-&#8288;е&#8239;гг.&#8239;&#8239;— нет, не подходит, договор заключён не в 960-&#8288;е&#8239;гг., а в 944&#8239;г.<p>2)&#8239;&#8239;Князь, от имени которого выступали русские послы, был первым, кто объединил под своей властью Новгород и Киев&#8239;&#8239;— нет, не подходит, первым объединителем Новгорода и Киева был Олег Вещий.<p>3)&#8239;&#8239;Столицу государства, с которым Русь заключила данный договор, в русских летописях называли Царьградом&#8239;&#8239;— да, подходит, византийскую столицу Константинополь русские летописи именовали Царьградом. В тексте упомянуты греческие цари (Роман, Константин, Стефан)&#8239;&#8239;— это византийские императоры.<p>4)&#8239;&#8239;Князь, от имени которого выступали русские послы, погиб в результате восстания подвластных племен&#8239;&#8239;— да, подходит, князь Игорь погиб в 945&#8239;г. во время восстания древлян после попытки повторного сбора дани.<p>5)&#8239;&#8239;Славянский бог, упоминаемый в отрывке, считался богом Солнца&#8239;&#8239;— нет, не подходит, Перун&#8239;&#8239;— бог грома и войны, а не Солнца.<p>6)&#8239;&#8239;Текст договора свидетельствует о том, что среди русских к моменту его заключения уже были христиане&#8239;&#8239;— да, подходит, в отрывке прямо указано разделение на крещёных («примут месть от бога») и некрещёных («не примут помощи от Перуна»).<p>&nbsp;</p><p>Ответ: 346.Ответ: 346Источник: СтатГрад: Тренировочная работа 04.04.2025. Вариант ИС2410501ПояснениеСпрятать пояснение &middot; Помощь<br>Пройти тестирование по этим заданиям\n<br><br>Наверх\n\n    \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    О проекте &middot; Редакция &middot; Правовая информация  &middot; О рекламе  \n © Гущин Д. Д., 2011&mdash;2026","ans":"346"},{"id":58957,"tp":4,"kind":"multi","type":"Тип 6","body":"<p>Прочтите отрывок из летописи. <p>&nbsp;</p><p>«Ярослав прибежал к Новгороду и хотел бежать за море. Посадник Константин, сын Добрыни, с новгородцами, разбил лодки Ярослава, говоря: «хотим ещё биться с Болеславом и Святополком». Начали собирать деньги: с мужа&#8239;&#8239;— по&#8239;4&#8239;куны, с старост&#8239;&#8239;— по&#8239;10&#8239;гривен, с бояр&#8239;&#8239;— по&#8239;18&#8239;гривен. Привели варягов, дали им денег, и собрал Ярослав много воинов... И пошёл Ярослав против Святополка, и убежал Святополк к печенегам. <p>Пришёл Святополк с печенегами, с большой силой. Ярослав собрал множество воинов и вышел против него на Альту. <p>Ярослав стал на месте, где убили Бориса, поднял руки к небу и сказал: «Кровь брата моего вопиет к тебе, владыка»… Когда он сказал это, пошли враги друг против друга, и покрылось поле около Альты с обеих сторон множеством воинов. Сошлись оба войска, был бой злой, какого не было на Руси, боролись врукопашную, трижды сходились, текла кровь ручьями. К вечеру одолел Ярослав, а Святополк убежал». <p>&nbsp;</p><p>Используя отрывок и знания по истории, выберите в приведённом <p>списке верные суждения. <p>&nbsp;</p><p>Запишите в таблицу цифры, под которыми они указаны.<p>&nbsp;</p><p>1)&#8239;&#8239;События, описываемые в отрывке, происходили в X веке.<p>2)&#8239;&#8239;Победитель в битве, описываемой в отрывке, был сыном князя, крестившего Русь.<p>3)&#8239;&#8239;Один из упоминаемых в отрывке исторических деятелей получил в истории прозвание «Окаянный».<p>4)&#8239;&#8239;В противостоянии, описанном в отрывке, участвовали племена кочевников.<p>5)&#8239;&#8239;В отрывке упоминается один из первых русских святых.<p>6)&#8239;&#8239;Автор отмечает, что войску Ярослава легко далась победа в описываемом сражении.","sol":"<b>Пояснение. </b><p>1)&#8239;&#8239;События, описываемые в отрывке, происходили в X веке&#8239;&#8239;— <i>нет, не подходит, события относятся к 1015–1019&#8239;гг.&#8239;&#8239;— междоусобица после смерти Владимира</i>.<p>2)&#8239;&#8239;Победитель в битве, описываемой в отрывке, был сыном князя, крестившего Русь&#8239;&#8239;— д<i>а, подходит, Ярослав Мудрый (победитель)&#8239;&#8239;— сын Владимира Святого, крестившего Русь в 988&#8239;г</i>.<p>3)&#8239;&#8239;Один из упоминаемых в отрывке исторических деятелей получил в истории прозвание «Окаянный»&#8239;&#8239;— <i>да, подходит, Святополк, убийца Бориса и Глеба, прозван «Окаянным»</i>.<p>4)&#8239;&#8239;В противостоянии, описанном в отрывке, участвовали племена кочевников&#8239;&#8239;— д<i>а, подходит, Печенеги&#8239;&#8239;— кочевой народ, союзники Святополка</i>.<p>5)&#8239;&#8239;В отрывке упоминается один из первых русских святых&#8239;&#8239;— <i>да, подходит, Борис, убитый Святополком, канонизирован как святой страстотерпец</i>.<p>6)&#8239;&#8239;Автор отмечает, что войску Ярослава легко далась победа в описываемом сражении&#8239;&#8239;— <i>нет, не подходит, автор подчёркивает ожесточённость битвы («бой злой», «кровь ручьями»), а не лёгкость победы</i>.<p>&nbsp;</p><p>Ответ: 2345.Ответ: 2345Источник: СтатГрад: Тренировочная работа 04.04.2025. Вариант ИС2410502ПояснениеСпрятать пояснение &middot; Помощь","ans":"2345"}];
